{
  "name": "LeaguePro - Sports Management Suite",
  "description": "A comprehensive digital league management application for sports teams, featuring team registration, player management, automated standings, and administrative controls."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Player {
  id: string;
  name: string;
  jerseyNumber: number;
  position: string;
  age: number;
  photoUrl: string;
}

export interface Team {
  id: string;
  name: string;
  logo: string;
  manager: string;
  contact: string;
  homeGround: string;
  players: Player[];
}

export interface Match {
  id: string;
  date: string;
  time: string;
  venue: string;
  homeTeamId: string;
  awayTeamId: string;
  homeScore?: number;
  awayScore?: number;
  isCompleted: boolean;
  matchWeek: number;
}

export interface Standing {
  teamId: string;
  teamName: string;
  played: number;
  won: number;
  drawn: number;
  lost: number;
  goalsFor: number;
  goalsAgainst: number;
  goalDifference: number;
  points: number;
}

export enum UserRole {
  PUBLIC = 'PUBLIC',
  TEAM_MANAGER = 'TEAM_MANAGER',
  ADMIN = 'ADMIN'
}

import { Team, Match } from './types';

export const MAX_SQUAD_SIZE = 22;

export const INITIAL_TEAMS: Team[] = [
  {
    id: 't1',
    name: 'Thunder FC',
    logo: 'https://picsum.photos/seed/thunder/100/100',
    manager: 'Alex Ferguson',
    contact: 'alex@thunder.com',
    homeGround: 'Storm Arena',
    players: []
  },
  {
    id: 't2',
    name: 'Lightning United',
    logo: 'https://picsum.photos/seed/lightning/100/100',
    manager: 'Pep Guardiola',
    contact: 'pep@lightning.com',
    homeGround: 'Voltage Stadium',
    players: []
  },
  {
    id: 't3',
    name: 'Gale Warriors',
    logo: 'https://picsum.photos/seed/gale/100/100',
    manager: 'Jurgen Klopp',
    contact: 'jurgen@gale.com',
    homeGround: 'Windy Park',
    players: []
  }
];

export const INITIAL_MATCHES: Match[] = [
  {
    id: 'm1',
    date: '2024-06-01',
    time: '15:00',
    venue: 'Storm Arena',
    homeTeamId: 't1',
    awayTeamId: 't2',
    isCompleted: false,
    matchWeek: 1
  },
  {
    id: 'm2',
    date: '2024-06-02',
    time: '18:00',
    venue: 'Windy Park',
    homeTeamId: 't3',
    awayTeamId: 't1',
    isCompleted: false,
    matchWeek: 2
  }
];

import React, { useState, useMemo, useEffect } from 'react';
import { Team, Match, Player, Standing, UserRole } from './types';
import { INITIAL_TEAMS, INITIAL_MATCHES } from './constants';
import Dashboard from './components/Dashboard';
import TeamRegistration from './components/TeamRegistration';
import StandingsTable from './components/StandingsTable';
import MatchScheduler from './components/MatchScheduler';
import AdminPanel from './components/AdminPanel';
import PlayerManager from './components/PlayerManager';
import Navbar from './components/Navbar';

const App: React.FC = () => {
  const [view, setView] = useState<string>('standings');
  const [role, setRole] = useState<UserRole>(UserRole.PUBLIC);
  const [teams, setTeams] = useState<Team[]>(INITIAL_TEAMS);
  const [matches, setMatches] = useState<Match[]>(INITIAL_MATCHES);
  const [selectedTeamId, setSelectedTeamId] = useState<string | null>(null);

  // Persistence (Simulated)
  useEffect(() => {
    const savedTeams = localStorage.getItem('lp_teams');
    const savedMatches = localStorage.getItem('lp_matches');
    if (savedTeams) setTeams(JSON.parse(savedTeams));
    if (savedMatches) setMatches(JSON.parse(savedMatches));
  }, []);

  useEffect(() => {
    localStorage.setItem('lp_teams', JSON.stringify(teams));
    localStorage.setItem('lp_matches', JSON.stringify(matches));
  }, [teams, matches]);

  // Standing Calculation Logic
  const standings = useMemo(() => {
    const table: Record<string, Standing> = {};

    teams.forEach(team => {
      table[team.id] = {
        teamId: team.id,
        teamName: team.name,
        played: 0,
        won: 0,
        drawn: 0,
        lost: 0,
        goalsFor: 0,
        goalsAgainst: 0,
        goalDifference: 0,
        points: 0
      };
    });

    matches.filter(m => m.isCompleted).forEach(match => {
      const home = table[match.homeTeamId];
      const away = table[match.awayTeamId];
      if (!home || !away) return;

      const hScore = match.homeScore || 0;
      const aScore = match.awayScore || 0;

      home.played += 1;
      away.played += 1;
      home.goalsFor += hScore;
      home.goalsAgainst += aScore;
      away.goalsFor += aScore;
      away.goalsAgainst += hScore;

      if (hScore > aScore) {
        home.won += 1;
        home.points += 3;
        away.lost += 1;
      } else if (aScore > hScore) {
        away.won += 1;
        away.points += 3;
        home.lost += 1;
      } else {
        home.drawn += 1;
        away.drawn += 1;
        home.points += 1;
        away.points += 1;
      }

      home.goalDifference = home.goalsFor - home.goalsAgainst;
      away.goalDifference = away.goalsFor - away.goalsAgainst;
    });

    return Object.values(table).sort((a, b) => {
      if (b.points !== a.points) return b.points - a.points;
      if (b.goalDifference !== a.goalDifference) return b.goalDifference - a.goalDifference;
      return b.goalsFor - a.goalsFor;
    });
  }, [teams, matches]);

  const addTeam = (team: Omit<Team, 'id' | 'players'>) => {
    const newTeam: Team = { ...team, id: `t${Date.now()}`, players: [] };
    setTeams([...teams, newTeam]);
    setView('standings');
  };

  const updateMatch = (matchId: string, hScore: number, aScore: number) => {
    setMatches(matches.map(m => m.id === matchId ? { ...m, homeScore: hScore, awayScore: aScore, isCompleted: true } : m));
  };

  const addMatch = (newMatch: Match) => {
    setMatches([...matches, newMatch]);
  };

  const updatePlayers = (teamId: string, players: Player[]) => {
    setTeams(teams.map(t => t.id === teamId ? { ...t, players } : t));
  };

  const renderView = () => {
    switch (view) {
      case 'standings':
        return <StandingsTable standings={standings} teams={teams} />;
      case 'registration':
        return <TeamRegistration onRegister={addTeam} existingNames={teams.map(t => t.name)} />;
      case 'schedule':
        return <MatchScheduler matches={matches} teams={teams} isAdmin={role === UserRole.ADMIN} onAddMatch={addMatch} onUpdateMatch={updateMatch} />;
      case 'admin':
        return <AdminPanel teams={teams} matches={matches} onUpdateMatch={updateMatch} onReset={() => { setTeams(INITIAL_TEAMS); setMatches([]); }} />;
      case 'players':
        const teamToManage = teams.find(t => t.id === selectedTeamId);
        return teamToManage ? (
          <PlayerManager team={teamToManage} onUpdate={(p) => updatePlayers(teamToManage.id, p)} onBack={() => setView('standings')} />
        ) : <div className="p-8 text-center text-gray-500">Please select a team from the dashboard first.</div>;
      default:
        return <StandingsTable standings={standings} teams={teams} />;
    }
  };

  return (
    <div className="min-h-screen flex flex-col">
      <Navbar 
        currentView={view} 
        setView={setView} 
        role={role} 
        setRole={setRole} 
        setSelectedTeamId={setSelectedTeamId}
        teams={teams}
      />
      <main className="flex-1 container mx-auto px-4 py-8 max-w-6xl">
        {renderView()}
      </main>
      <footer className="bg-white border-t border-gray-200 py-6 text-center text-gray-500 text-sm">
        &copy; 2024 LeaguePro Management Suite. Built for Champions.
      </footer>
    </div>
  );
};

export default App;

import React from 'react';
import { UserRole, Team } from '../types';

interface NavbarProps {
  currentView: string;
  setView: (v: string) => void;
  role: UserRole;
  setRole: (r: UserRole) => void;
  setSelectedTeamId: (id: string | null) => void;
  teams: Team[];
}

const Navbar: React.FC<NavbarProps> = ({ currentView, setView, role, setRole, setSelectedTeamId, teams }) => {
  return (
    <nav className="bg-white shadow-sm border-b border-gray-100 sticky top-0 z-50">
      <div className="container mx-auto px-4 flex flex-col md:flex-row justify-between items-center h-auto md:h-16 py-3 md:py-0">
        <div className="flex items-center space-x-2 cursor-pointer" onClick={() => setView('standings')}>
          <div className="bg-blue-600 p-2 rounded-lg">
            <i className="fas fa-trophy text-white text-xl"></i>
          </div>
          <span className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-600 to-indigo-600">
            LeaguePro
          </span>
        </div>

        <div className="flex flex-wrap justify-center space-x-1 md:space-x-4 mt-4 md:mt-0">
          <NavItem active={currentView === 'standings'} onClick={() => setView('standings')} icon="fa-list-ol" label="Standings" />
          <NavItem active={currentView === 'schedule'} onClick={() => setView('schedule')} icon="fa-calendar-alt" label="Fixtures" />
          {role === UserRole.PUBLIC && (
            <NavItem active={currentView === 'registration'} onClick={() => setView('registration')} icon="fa-user-plus" label="Register Team" />
          )}
          {role === UserRole.TEAM_MANAGER && (
            <NavItem active={currentView === 'players'} onClick={() => setView('players')} icon="fa-users" label="My Players" />
          )}
          {role === UserRole.ADMIN && (
            <NavItem active={currentView === 'admin'} onClick={() => setView('admin')} icon="fa-cog" label="Admin Panel" />
          )}
        </div>

        <div className="flex items-center space-x-3 mt-4 md:mt-0">
          <select 
            className="bg-gray-50 border border-gray-200 text-gray-700 text-xs rounded-full px-3 py-1.5 focus:ring-blue-500 focus:border-blue-500"
            value={role}
            onChange={(e) => {
              const newRole = e.target.value as UserRole;
              setRole(newRole);
              if (newRole !== UserRole.TEAM_MANAGER) setSelectedTeamId(null);
              setView('standings');
            }}
          >
            <option value={UserRole.PUBLIC}>Public Viewer</option>
            <option value={UserRole.TEAM_MANAGER}>Team Manager</option>
            <option value={UserRole.ADMIN}>League Admin</option>
          </select>

          {role === UserRole.TEAM_MANAGER && (
            <select 
              className="bg-blue-50 border border-blue-200 text-blue-700 text-xs rounded-full px-3 py-1.5"
              onChange={(e) => {
                setSelectedTeamId(e.target.value);
                setView('players');
              }}
            >
              <option value="">Select Team</option>
              {teams.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
            </select>
          )}
        </div>
      </div>
    </nav>
  );
};

const NavItem: React.FC<{ active: boolean; onClick: () => void; icon: string; label: string }> = ({ active, onClick, icon, label }) => (
  <button 
    onClick={onClick}
    className={`flex items-center space-x-2 px-3 py-2 rounded-md transition-all duration-200 ${
      active ? 'bg-blue-50 text-blue-600 font-semibold' : 'text-gray-600 hover:bg-gray-100'
    }`}
  >
    <i className={`fas ${icon} text-sm`}></i>
    <span className="text-sm">{label}</span>
  </button>
);

export default Navbar;

import React, { useState } from 'react';
import { Match, Team } from '../types';

interface MatchSchedulerProps {
  matches: Match[];
  teams: Team[];
  isAdmin: boolean;
  onAddMatch: (m: Match) => void;
  onUpdateMatch: (id: string, h: number, a: number) => void;
}

const MatchScheduler: React.FC<MatchSchedulerProps> = ({ matches, teams, isAdmin, onAddMatch, onUpdateMatch }) => {
  const [showAdd, setShowAdd] = useState(false);
  const [newMatch, setNewMatch] = useState<Partial<Match>>({
    date: '',
    time: '',
    venue: '',
    homeTeamId: '',
    awayTeamId: '',
    matchWeek: 1
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newMatch.homeTeamId && newMatch.awayTeamId && newMatch.homeTeamId !== newMatch.awayTeamId) {
      onAddMatch({
        ...newMatch as Match,
        id: `m${Date.now()}`,
        isCompleted: false
      });
      setShowAdd(false);
    }
  };

  const getTeam = (id: string) => teams.find(t => t.id === id);

  return (
    <div className="space-y-8">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-3xl font-bold text-gray-900">Fixtures & Results</h2>
          <p className="text-gray-500">Upcoming games and recent scores.</p>
        </div>
        {isAdmin && (
          <button 
            onClick={() => setShowAdd(!showAdd)}
            className="bg-blue-600 text-white px-6 py-2.5 rounded-xl font-semibold shadow-lg shadow-blue-200 hover:bg-blue-700 transition-all flex items-center space-x-2"
          >
            <i className={`fas ${showAdd ? 'fa-times' : 'fa-plus'}`}></i>
            <span>{showAdd ? 'Cancel' : 'Schedule Match'}</span>
          </button>
        )}
      </div>

      {showAdd && (
        <form onSubmit={handleSubmit} className="bg-white p-6 rounded-2xl border-2 border-blue-500 shadow-xl grid grid-cols-1 md:grid-cols-3 gap-6 animate-in fade-in slide-in-from-top-4 duration-300">
          <div className="space-y-2">
            <label className="text-xs font-bold text-gray-400 uppercase">Home Team</label>
            <select 
              required
              className="w-full border border-gray-200 rounded-lg px-3 py-2 outline-none focus:border-blue-500"
              value={newMatch.homeTeamId}
              onChange={e => setNewMatch({ ...newMatch, homeTeamId: e.target.value })}
            >
              <option value="">Select Home</option>
              {teams.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
            </select>
          </div>
          <div className="space-y-2 text-center flex flex-col justify-center">
            <span className="text-xl font-black text-gray-300">VS</span>
          </div>
          <div className="space-y-2">
            <label className="text-xs font-bold text-gray-400 uppercase">Away Team</label>
            <select 
              required
              className="w-full border border-gray-200 rounded-lg px-3 py-2 outline-none focus:border-blue-500"
              value={newMatch.awayTeamId}
              onChange={e => setNewMatch({ ...newMatch, awayTeamId: e.target.value })}
            >
              <option value="">Select Away</option>
              {teams.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-xs font-bold text-gray-400 uppercase">Date & Time</label>
            <div className="flex space-x-2">
              <input type="date" required className="flex-1 border border-gray-200 rounded-lg px-3 py-2" value={newMatch.date} onChange={e => setNewMatch({ ...newMatch, date: e.target.value })} />
              <input type="time" required className="w-24 border border-gray-200 rounded-lg px-3 py-2" value={newMatch.time} onChange={e => setNewMatch({ ...newMatch, time: e.target.value })} />
            </div>
          </div>
          <div className="space-y-2">
            <label className="text-xs font-bold text-gray-400 uppercase">Venue</label>
            <input type="text" required className="w-full border border-gray-200 rounded-lg px-3 py-2" placeholder="Stadium Name" value={newMatch.venue} onChange={e => setNewMatch({ ...newMatch, venue: e.target.value })} />
          </div>
          <div className="flex items-end">
            <button type="submit" className="w-full bg-blue-600 text-white py-2.5 rounded-lg font-bold hover:bg-blue-700">
              Confirm Schedule
            </button>
          </div>
        </form>
      )}

      <div className="space-y-4">
        {matches.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime()).map(match => (
          <div key={match.id} className="bg-white rounded-2xl border border-gray-100 p-6 flex flex-col md:flex-row items-center justify-between hover:shadow-md transition-shadow group">
            <div className="flex flex-col items-center md:items-start space-y-1 mb-4 md:mb-0 w-full md:w-1/4">
              <span className="text-xs font-black text-blue-600 bg-blue-50 px-2 py-1 rounded">WEEK {match.matchWeek}</span>
              <span className="text-sm font-semibold text-gray-900">{new Date(match.date).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' })}</span>
              <span className="text-xs text-gray-400">{match.time} • {match.venue}</span>
            </div>

            <div className="flex items-center justify-center space-x-4 md:space-x-8 w-full md:w-2/4">
              <div className="flex flex-col items-center space-y-2 w-1/3">
                <img src={getTeam(match.homeTeamId)?.logo} alt="" className="w-12 h-12 rounded-full border border-gray-100 shadow-sm" />
                <span className="text-sm font-bold text-gray-900 text-center">{getTeam(match.homeTeamId)?.name}</span>
              </div>

              <div className="flex flex-col items-center justify-center px-4 min-w-[100px]">
                {match.isCompleted ? (
                  <div className="flex items-center space-x-3">
                    <span className="text-3xl font-black text-gray-900">{match.homeScore}</span>
                    <span className="text-gray-300 font-bold">-</span>
                    <span className="text-3xl font-black text-gray-900">{match.awayScore}</span>
                  </div>
                ) : (
                  <div className="bg-gray-100 text-gray-500 px-3 py-1 rounded-full text-xs font-black">UPCOMING</div>
                )}
              </div>

              <div className="flex flex-col items-center space-y-2 w-1/3">
                <img src={getTeam(match.awayTeamId)?.logo} alt="" className="w-12 h-12 rounded-full border border-gray-100 shadow-sm" />
                <span className="text-sm font-bold text-gray-900 text-center">{getTeam(match.awayTeamId)?.name}</span>
              </div>
            </div>

            <div className="flex justify-center md:justify-end w-full md:w-1/4 mt-4 md:mt-0">
              {isAdmin && !match.isCompleted && (
                <button 
                  onClick={() => {
                    const h = prompt('Home score?');
                    const a = prompt('Away score?');
                    if (h !== null && a !== null) onUpdateMatch(match.id, parseInt(h), parseInt(a));
                  }}
                  className="bg-green-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-green-700"
                >
                  Enter Result
                </button>
              )}
              {match.isCompleted && (
                <div className="flex space-x-1">
                   {[1,2,3].map(i => <div key={i} className="w-2 h-2 rounded-full bg-green-500"></div>)}
                </div>
              )}
            </div>
          </div>
        ))}
        {matches.length === 0 && <div className="text-center py-20 text-gray-400">No matches scheduled yet.</div>}
      </div>
    </div>
  );
};

export default MatchScheduler;

import React, { useState } from 'react';
import { Player, Team } from '../types';
import { MAX_SQUAD_SIZE } from '../constants';

interface PlayerManagerProps {
  team: Team;
  onUpdate: (players: Player[]) => void;
  onBack: () => void;
}

const PlayerManager: React.FC<PlayerManagerProps> = ({ team, onUpdate, onBack }) => {
  const [showAdd, setShowAdd] = useState(false);
  const [newPlayer, setNewPlayer] = useState<Partial<Player>>({
    name: '',
    jerseyNumber: 1,
    position: 'Goalkeeper',
    age: 18
  });

  const addPlayer = (e: React.FormEvent) => {
    e.preventDefault();
    if (team.players.length >= MAX_SQUAD_SIZE) {
      alert(`Maximum squad size of ${MAX_SQUAD_SIZE} reached.`);
      return;
    }
    const player: Player = {
      ...newPlayer as Player,
      id: `p${Date.now()}`,
      photoUrl: `https://picsum.photos/seed/${Math.random()}/150/150`
    };
    onUpdate([...team.players, player]);
    setShowAdd(false);
    setNewPlayer({ name: '', jerseyNumber: 1, position: 'Goalkeeper', age: 18 });
  };

  const removePlayer = (id: string) => {
    onUpdate(team.players.filter(p => p.id !== id));
  };

  return (
    <div className="space-y-8">
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-4">
          <button onClick={onBack} className="bg-gray-100 p-2 rounded-full hover:bg-gray-200 transition-colors">
            <i className="fas fa-arrow-left text-gray-600"></i>
          </button>
          <div className="flex items-center space-x-4">
            <img src={team.logo} className="w-12 h-12 rounded-full border-2 border-white shadow-sm" alt="" />
            <div>
              <h2 className="text-3xl font-bold text-gray-900">{team.name} Squad</h2>
              <p className="text-gray-500">{team.players.length} / {MAX_SQUAD_SIZE} Players Registered</p>
            </div>
          </div>
        </div>
        <button 
          onClick={() => setShowAdd(!showAdd)}
          className="bg-blue-600 text-white px-6 py-2.5 rounded-xl font-semibold shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all flex items-center space-x-2"
        >
          <i className={`fas ${showAdd ? 'fa-times' : 'fa-plus'}`}></i>
          <span>{showAdd ? 'Cancel' : 'Add Player'}</span>
        </button>
      </div>

      {showAdd && (
        <form onSubmit={addPlayer} className="bg-white p-8 rounded-2xl border border-gray-200 shadow-xl grid grid-cols-1 md:grid-cols-4 gap-6 animate-in slide-in-from-right-4">
          <div className="space-y-2">
            <label className="text-xs font-bold text-gray-400 uppercase">Full Name</label>
            <input 
              required
              className="w-full border border-gray-200 rounded-lg px-3 py-2"
              value={newPlayer.name}
              onChange={e => setNewPlayer({ ...newPlayer, name: e.target.value })}
            />
          </div>
          <div className="space-y-2">
            <label className="text-xs font-bold text-gray-400 uppercase">Jersey #</label>
            <input 
              type="number"
              required
              min="1"
              className="w-full border border-gray-200 rounded-lg px-3 py-2"
              value={newPlayer.jerseyNumber}
              onChange={e => setNewPlayer({ ...newPlayer, jerseyNumber: parseInt(e.target.value) })}
            />
          </div>
          <div className="space-y-2">
            <label className="text-xs font-bold text-gray-400 uppercase">Position</label>
            <select 
              className="w-full border border-gray-200 rounded-lg px-3 py-2"
              value={newPlayer.position}
              onChange={e => setNewPlayer({ ...newPlayer, position: e.target.value })}
            >
              <option>Goalkeeper</option>
              <option>Defender</option>
              <option>Midfielder</option>
              <option>Forward</option>
            </select>
          </div>
          <div className="flex items-end">
            <button type="submit" className="w-full bg-blue-600 text-white py-2.5 rounded-lg font-bold hover:bg-blue-700">
              Save Player
            </button>
          </div>
        </form>
      )}

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        {team.players.map(player => (
          <div key={player.id} className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden hover:shadow-lg transition-shadow group relative">
            <div className="aspect-square bg-gray-50 relative">
              <img src={player.photoUrl} className="w-full h-full object-cover" alt="" />
