import React, { useState, useRef } from 'react';
import { Player, Team } from '../types';
import { MAX_SQUAD_SIZE } from '../constants';

interface PlayerManagerProps {
  team: Team;
  onUpdate: (players: Player[]) => void;
  onBack: () => void;
}

const PlayerManager: React.FC<PlayerManagerProps> = ({ team, onUpdate, onBack }) => {
  const [showAdd, setShowAdd] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [previewPhoto, setPreviewPhoto] = useState<string>('');
  const [newPlayer, setNewPlayer] = useState<Partial<Player>>({
    name: '',
    jerseyNumber: 1,
    position: 'Goalkeeper',
    age: 18,
    photoUrl: ''
  });

  const handlePhotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        setPreviewPhoto(base64String);
        setNewPlayer(prev => ({ ...prev, photoUrl: base64String }));
      };
      reader.readAsDataURL(file);
    }
  };

  const addPlayer = (e: React.FormEvent) => {
    e.preventDefault();
    if (team.players.length >= MAX_SQUAD_SIZE) {
      alert(`Maximum squad size of ${MAX_SQUAD_SIZE} reached.`);
      return;
    }

    const player: Player = {
      id: `p${Date.now()}`,
      name: newPlayer.name || 'Unknown Player',
      jerseyNumber: newPlayer.jerseyNumber || 0,
      position: newPlayer.position || 'Unknown',
      age: newPlayer.age || 18,
      photoUrl: newPlayer.photoUrl || `https://api.dicebear.com/7.x/avataaars/svg?seed=${newPlayer.name}`
    };

    onUpdate([...team.players, player]);
    setShowAdd(false);
    resetForm();
  };

  const resetForm = () => {
    setNewPlayer({ name: '', jerseyNumber: 1, position: 'Goalkeeper', age: 18, photoUrl: '' });
    setPreviewPhoto('');
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const removePlayer = (id: string) => {
    if (confirm('Are you sure you want to remove this player from the squad?')) {
      onUpdate(team.players.filter(p => p.id !== id));
    }
  };

  const positionsCount = team.players.reduce((acc, p) => {
    acc[p.position] = (acc[p.position] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="flex items-center space-x-4">
          <button onClick={onBack} className="bg-white border border-gray-200 p-3 rounded-xl hover:bg-gray-50 transition-colors shadow-sm text-gray-600">
            <i className="fas fa-arrow-left"></i>
          </button>
          <div className="flex items-center space-x-4">
            <img src={team.logo} className="w-16 h-16 rounded-2xl border-4 border-white shadow-md object-cover" alt="" />
            <div>
              <h2 className="text-3xl font-black text-gray-900 tracking-tight">{team.name}</h2>
              <div className="flex items-center space-x-2 text-sm text-gray-500">
                <span className="bg-blue-100 text-blue-700 px-2 py-0.5 rounded font-bold uppercase text-[10px]">Manager</span>
                <span>{team.manager}</span>
              </div>
