interface MatchSchedulerProps {
  matches: Match[];
  teams: Team[];
  isAdmin: boolean;
  role: UserRole;
  selectedTeamId: string | null;
  onAddMatch: (m: Match) => void;
  onUpdateMatch: (id: string, h: number, a: number) => void;
}

const MatchScheduler: React.FC<MatchSchedulerProps> = ({ 
  matches, 
  teams, 
  isAdmin, 
  role,
  selectedTeamId,
  onAddMatch, 
  onUpdateMatch 
}) => {
  const [showAdd, setShowAdd] = useState(false);
  const [newMatch, setNewMatch] = useState<Partial<Match>>({
    date: '',
    time: '',
    venue: '',
    homeTeamId: '',
    awayTeamId: '',
    matchWeek: 1
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newMatch.homeTeamId && newMatch.awayTeamId && newMatch.homeTeamId !== newMatch.awayTeamId) {
      onAddMatch({
        ...newMatch as Match,
        id: `m${Date.now()}`,
        isCompleted: false
      });
      setShowAdd(false);
    }
  };

  const getTeam = (id: string) => teams.find(t => t.id === id);

  const canManageMatch = (match: Match) => {
    if (isAdmin) return true;
    if (role === UserRole.TEAM_MANAGER && selectedTeamId) {
      return match.homeTeamId === selectedTeamId || match.awayTeamId === selectedTeamId;
    }
    return false;
  };

  const handleResultEntry = (match: Match) => {
    const h = prompt(`Enter goals for ${getTeam(match.homeTeamId)?.name}:`, '0');
    const a = prompt(`Enter goals for ${getTeam(match.awayTeamId)?.name}:`, '0');

    if (h !== null && a !== null) {
      const homeScore = parseInt(h);
      const awayScore = parseInt(a);
      if (!isNaN(homeScore) && !isNaN(awayScore)) {
        onUpdateMatch(match.id, homeScore, awayScore);
      } else {
        alert('Invalid scores entered. Please enter numbers only.');
