          const isManagerMatch = !isAdmin && role === UserRole.TEAM_MANAGER && (match.homeTeamId === selectedTeamId || match.awayTeamId === selectedTeamId);
          const isEditing = editingMatchId === match.id;

          return (
            <div key={match.id} className={`bg-white rounded-3xl border ${isManagerMatch ? 'border-blue-200 ring-4 ring-blue-50/50 shadow-blue-100 shadow-xl' : 'border-gray-100'} p-6 flex flex-col md:flex-row items-center justify-between hover:shadow-xl transition-all group relative overflow-hidden`}>
