              </div>

              <div className="flex justify-center md:justify-end w-full md:w-1/4 mt-6 md:mt-0">
                {canManageMatch(match) && !isEditing ? (
                  <button 
                    onClick={() => startEditing(match)}
                    className="bg-green-600 text-white px-6 py-2.5 rounded-xl text-sm font-black hover:bg-green-700 shadow-lg shadow-green-100 transition-all flex items-center space-x-2 active:scale-95"
                  >
                    <i className="fas fa-edit"></i>
                    <span>{match.isCompleted ? 'Edit Result' : 'Enter Result'}</span>
                  </button>
                ) : match.isCompleted && !isEditing ? (
                  <div className="flex items-center space-x-1.5 bg-green-50 px-4 py-2 rounded-xl">
                    <i className="fas fa-check-double text-green-500 text-xs"></i>
                    <span className="text-[10px] font-black text-green-700 uppercase tracking-widest">Verified</span>
                  </div>
                ) : !isEditing && (
                  <button className="text-gray-300 cursor-not-allowed opacity-50 flex items-center space-x-2" disabled>
                    <i className="fas fa-lock text-sm"></i>
                    <span className="text-[10px] font-bold uppercase">Restricted</span>
                  </button>
                )}
              </div>
            </div>
          );
        })}
        {matches.length === 0 && (
          <div className="text-center py-24 bg-gray-50 rounded-3xl border-2 border-dashed border-gray-200">
            <i className="fas fa-calendar-times text-4xl text-gray-200 mb-4"></i>
            <p className="text-gray-400 font-bold">No matches scheduled for this season yet.</p>
          </div>
        )}
      </div>
    </div>
  );
};

