                <span className="text-lg font-black text-gray-900">{new Date(match.date).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' })}</span>
                <span className="text-xs text-gray-400 font-medium uppercase tracking-widest">{match.time} • {match.venue}</span>
              </div>

              <div className="flex items-center justify-center space-x-4 md:space-x-8 w-full md:w-2/4">
                <div className="flex flex-col items-center space-y-3 w-1/3 group/home text-center">
                  <img src={getTeam(match.homeTeamId)?.logo} alt="" className="w-14 h-14 rounded-full border-4 border-white shadow-md group-hover/home:scale-110 transition-transform" />
                  <span className="text-sm font-black text-gray-900 leading-tight">{getTeam(match.homeTeamId)?.name}</span>
                </div>

                <div className="flex flex-col items-center justify-center px-4 min-w-[140px]">
                  {isEditing ? (
                    <div className="flex flex-col items-center space-y-3 bg-blue-50 p-4 rounded-2xl border border-blue-100">
                       <div className="flex items-center space-x-2">
                         <input 
                           type="number" 
                           min="0"
                           className="w-12 text-center border-2 border-blue-300 rounded-lg font-black py-2 focus:ring-2 focus:ring-blue-500 outline-none text-blue-700 shadow-inner"
                           value={scores.home}
                           onChange={(e) => setScores({ ...scores, home: parseInt(e.target.value) || 0 })}
                         />
                         <span className="font-bold text-blue-300 text-lg">:</span>
                         <input 
                           type="number" 
                           min="0"
                           className="w-12 text-center border-2 border-blue-300 rounded-lg font-black py-2 focus:ring-2 focus:ring-blue-500 outline-none text-blue-700 shadow-inner"
                           value={scores.away}
                           onChange={(e) => setScores({ ...scores, away: parseInt(e.target.value) || 0 })}
                         />
                       </div>
                       <div className="flex space-x-2 w-full">
                         <button 
                           onClick={() => saveResult(match.id)} 
                           className="flex-1 bg-blue-600 text-white text-[10px] py-1.5 rounded-lg font-black uppercase hover:bg-blue-700 shadow-sm"
                         >
                           Save
                         </button>
                         <button 
                           onClick={() => setEditingMatchId(null)} 
                           className="flex-1 bg-white text-gray-500 text-[10px] py-1.5 rounded-lg font-black uppercase hover:bg-gray-100 border border-gray-200"
                         >
                           Cancel
                         </button>
                       </div>
                    </div>
                  ) : match.isCompleted ? (
                    <div className="flex flex-col items-center">
                      <div className="flex items-center space-x-4 bg-gray-50 px-6 py-2 rounded-2xl border border-gray-100">
                        <span className="text-3xl font-black text-gray-900">{match.homeScore}</span>
                        <span className="text-gray-300 font-bold text-xl">:</span>
                        <span className="text-3xl font-black text-gray-900">{match.awayScore}</span>
                      </div>
                      <span className="text-[10px] font-bold text-green-600 mt-2 uppercase tracking-widest">Final Result</span>
                    </div>
                  ) : (
                    <div className="bg-gray-100 text-gray-400 px-4 py-1.5 rounded-full text-[10px] font-black tracking-widest uppercase border border-gray-200">UPCOMING</div>
                  )}
                </div>

                <div className="flex flex-col items-center space-y-3 w-1/3 group/away text-center">
                  <img src={getTeam(match.awayTeamId)?.logo} alt="" className="w-14 h-14 rounded-full border-4 border-white shadow-md group-hover/away:scale-110 transition-transform" />
                  <span className="text-sm font-black text-gray-900 leading-tight">{getTeam(match.awayTeamId)?.name}</span>
                </div>
              </div>

              <div className="flex justify-center md:justify-end w-full md:w-1/4 mt-6 md:mt-0">
                {canManageMatch(match) && !isEditing ? (
                  <button 
                    onClick={() => startEditing(match)}
                    className="bg-green-600 text-white px-6 py-2.5 rounded-xl text-sm font-black hover:bg-green-700 shadow-lg shadow-green-100 transition-all flex items-center space-x-2 active:scale-95"
                  >
                    <i className="fas fa-edit"></i>
                    <span>{match.isCompleted ? 'Edit Result' : 'Enter Result'}</span>
                  </button>
                ) : match.isCompleted && !isEditing ? (
                  <div className="flex items-center space-x-1.5 bg-green-50 px-4 py-2 rounded-xl">
                    <i className="fas fa-check-double text-green-500 text-xs"></i>
                    <span className="text-[10px] font-black text-green-700 uppercase tracking-widest">Verified</span>
                  </div>
                ) : !isEditing && (
                  <button className="text-gray-300 cursor-not-allowed opacity-50 flex items-center space-x-2" disabled>
                    <i className="fas fa-lock text-sm"></i>
                    <span className="text-[10px] font-bold uppercase">Restricted</span>
                  </button>
                )}
              </div>
            </div>
          );
        })}
        {matches.length === 0 && (
          <div className="text-center py-24 bg-gray-50 rounded-3xl border-2 border-dashed border-gray-200">
            <i className="fas fa-calendar-times text-4xl text-gray-200 mb-4"></i>
            <p className="text-gray-400 font-bold">No matches scheduled for this season yet.</p>
          </div>
        )}
      </div>
    </div>
  );
};

