import React, { useState, useRef } from 'react';
import { Player, Team } from '../types';
import { MAX_SQUAD_SIZE } from '../constants';

interface PlayerManagerProps {
  team: Team;
  onUpdate: (players: Player[]) => void;
  onBack: () => void;
}

const PlayerManager: React.FC<PlayerManagerProps> = ({ team, onUpdate, onBack }) => {
  const [showAdd, setShowAdd] = useState(false);
  const [editingPlayerId, setEditingPlayerId] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const formRef = useRef<HTMLDivElement>(null);
  const [previewPhoto, setPreviewPhoto] = useState<string>('');
  const [newPlayer, setNewPlayer] = useState<Partial<Player>>({
    name: '',
    jerseyNumber: 1,
    position: 'Goalkeeper',
    age: 18,
    photoUrl: ''
  });

  const handlePhotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        setPreviewPhoto(base64String);
        setNewPlayer(prev => ({ ...prev, photoUrl: base64String }));
      };
      reader.readAsDataURL(file);
    }
  };

  const savePlayer = (e: React.FormEvent) => {
    e.preventDefault();

    if (!editingPlayerId && team.players.length >= MAX_SQUAD_SIZE) {
      alert(`Maximum squad size of ${MAX_SQUAD_SIZE} reached.`);
      return;
    }

    if (editingPlayerId) {
      // Update existing player
      const updatedPlayers = team.players.map(p => 
        p.id === editingPlayerId 
          ? { ...p, ...newPlayer as Player } 
          : p
      );
      onUpdate(updatedPlayers);
    } else {
      // Add new player
      const player: Player = {
        id: `p${Date.now()}`,
        name: newPlayer.name || 'Unknown Player',
        jerseyNumber: newPlayer.jerseyNumber || 0,
        position: newPlayer.position || 'Unknown',
        age: newPlayer.age || 18,
        photoUrl: newPlayer.photoUrl || `https://api.dicebear.com/7.x/avataaars/svg?seed=${newPlayer.name}`
      };
      onUpdate([...team.players, player]);
    }

    setShowAdd(false);
    setEditingPlayerId(null);
    resetForm();
  };

  const resetForm = () => {
    setNewPlayer({ name: '', jerseyNumber: 1, position: 'Goalkeeper', age: 18, photoUrl: '' });
    setPreviewPhoto('');
    setEditingPlayerId(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleEditClick = (player: Player) => {
    setNewPlayer(player);
    setPreviewPhoto(player.photoUrl);
    setEditingPlayerId(player.id);
    setShowAdd(true);

    // Scroll to form
    setTimeout(() => {
      formRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }, 100);
  };

  const removePlayer = (e: React.MouseEvent, id: string) => {
    e.stopPropagation(); // Prevent triggering the card click (edit)
    if (confirm('Are you sure you want to remove this player from the squad?')) {
      onUpdate(team.players.filter(p => p.id !== id));
      if (editingPlayerId === id) resetForm();
    }
  };

  const positionsCount = team.players.reduce((acc, p) => {
    acc[p.position] = (acc[p.position] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="flex items-center space-x-4">
          <button onClick={onBack} className="bg-white border border-gray-200 p-3 rounded-xl hover:bg-gray-50 transition-colors shadow-sm text-gray-600">
            <i className="fas fa-arrow-left"></i>
          </button>
          <div className="flex items-center space-x-4">
            <img src={team.logo} className="w-16 h-16 rounded-2xl border-4 border-white shadow-md object-cover" alt="" />
            <div>
              <h2 className="text-3xl font-black text-gray-900 tracking-tight">{team.name}</h2>
              <div className="flex items-center space-x-2 text-sm text-gray-500">
                <span className="bg-blue-100 text-blue-700 px-2 py-0.5 rounded font-bold uppercase text-[10px]">Manager</span>
                <span>{team.manager}</span>
              </div>
            </div>
          </div>
        </div>
        <button 
          onClick={() => {
            if (showAdd) resetForm();
            setShowAdd(!showAdd);
          }}
          className={`flex items-center justify-center space-x-2 px-6 py-3 rounded-xl font-bold transition-all shadow-lg ${
            showAdd ? 'bg-gray-200 text-gray-700 hover:bg-gray-300' : 'bg-blue-600 text-white hover:bg-blue-700 shadow-blue-200'
          }`}
        >
          <i className={`fas ${showAdd ? 'fa-times' : 'fa-user-plus'}`}></i>
          <span>{showAdd ? 'Cancel' : 'Register New Player'}</span>
        </button>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm">
          <p className="text-xs font-bold text-gray-400 uppercase">Squad Size</p>
          <p className="text-2xl font-black text-gray-900">{team.players.length} <span className="text-gray-300 text-sm">/ {MAX_SQUAD_SIZE}</span></p>
        </div>
        <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm">
          <p className="text-xs font-bold text-gray-400 uppercase">Goalkeepers</p>
          <p className="text-2xl font-black text-gray-900">{positionsCount['Goalkeeper'] || 0}</p>
        </div>
        <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm">
          <p className="text-xs font-bold text-gray-400 uppercase">Avg. Age</p>
          <p className="text-2xl font-black text-gray-900">
            {team.players.length ? (team.players.reduce((a, b) => a + b.age, 0) / team.players.length).toFixed(1) : '0'}
          </p>
        </div>
        <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm">
          <p className="text-xs font-bold text-gray-400 uppercase">Vacancies</p>
          <p className="text-2xl font-black text-green-600">{MAX_SQUAD_SIZE - team.players.length}</p>
        </div>
      </div>

      {showAdd && (
        <div ref={formRef} className="bg-white rounded-3xl border-2 border-blue-100 shadow-2xl overflow-hidden animate-in slide-in-from-top-8 duration-300">
          <div className="bg-blue-600 p-6 text-white flex justify-between items-center">
            <div>
              <h3 className="text-xl font-bold">{editingPlayerId ? 'Edit Player Profile' : 'Player Registration Form'}</h3>
              <p className="text-blue-100 text-sm">{editingPlayerId ? 'Update details for this squad member.' : 'Fill in the official details for the upcoming season.'}</p>
            </div>
            {editingPlayerId && (
              <button onClick={resetForm} className="text-xs bg-white/20 hover:bg-white/30 px-3 py-1.5 rounded-lg font-bold uppercase tracking-wider transition-colors">
                Clear Selection
              </button>
            )}
          </div>
          <form onSubmit={savePlayer} className="p-8">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
              {/* Photo Upload Section */}
              <div className="flex flex-col items-center space-y-4">
                <div 
                  onClick={() => fileInputRef.current?.click()}
                  className="w-48 h-60 bg-gray-50 border-2 border-dashed border-gray-200 rounded-2xl flex flex-col items-center justify-center cursor-pointer hover:border-blue-400 hover:bg-blue-50 transition-all group relative overflow-hidden"
                >
                  {previewPhoto ? (
                    <>
                      <img src={previewPhoto} className="w-full h-full object-cover" alt="Preview" />
                      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                        <span className="text-white text-xs font-bold">Change Photo</span>
                      </div>
                    </>
                  ) : (
                    <div className="text-center p-4">
                      <div className="w-12 h-12 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-2 text-gray-400 group-hover:text-blue-500 transition-colors">
                        <i className="fas fa-camera text-xl"></i>
                      </div>
                      <p className="text-xs font-bold text-gray-400 group-hover:text-blue-600 uppercase">Upload Photo</p>
                      <p className="text-[10px] text-gray-300 mt-1">PNG, JPG up to 2MB</p>
                    </div>
                  )}
                </div>
                <input 
                  type="file" 
                  ref={fileInputRef} 
                  className="hidden" 
                  accept="image/*" 
                  onChange={handlePhotoChange} 
                />
              </div>

              {/* Form Details */}
              <div className="md:col-span-2 space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-xs font-black text-gray-400 uppercase tracking-wider">Full Name</label>
                    <input 
                      required
                      placeholder="e.g. Cristiano Ronaldo"
                      className="w-full border border-gray-200 rounded-xl px-4 py-3 focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                      value={newPlayer.name}
                      onChange={e => setNewPlayer({ ...newPlayer, name: e.target.value })}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-black text-gray-400 uppercase tracking-wider">Jersey Number</label>
                    <input 
                      type="number"
                      required
                      min="1"
                      max="99"
                      className="w-full border border-gray-200 rounded-xl px-4 py-3 focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                      value={newPlayer.jerseyNumber}
                      onChange={e => setNewPlayer({ ...newPlayer, jerseyNumber: parseInt(e.target.value) || 0 })}
                    />
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-xs font-black text-gray-400 uppercase tracking-wider">Position</label>
                    <select 
                      className="w-full border border-gray-200 rounded-xl px-4 py-3 focus:ring-2 focus:ring-blue-500 outline-none transition-all bg-white"
                      value={newPlayer.position}
                      onChange={e => setNewPlayer({ ...newPlayer, position: e.target.value })}
                    >
                      <option>Goalkeeper</option>
                      <option>Defender</option>
                      <option>Midfielder</option>
                      <option>Forward</option>
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-black text-gray-400 uppercase tracking-wider">Age</label>
                    <input 
                      type="number"
                      required
                      min="15"
                      max="50"
                      className="w-full border border-gray-200 rounded-xl px-4 py-3 focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                      value={newPlayer.age}
                      onChange={e => setNewPlayer({ ...newPlayer, age: parseInt(e.target.value) || 0 })}
                    />
                  </div>
                </div>

                <div className="pt-4">
                  <button 
                    type="submit" 
                    className={`w-full text-white py-4 rounded-xl font-black text-lg shadow-lg transition-all flex items-center justify-center space-x-2 ${
                      editingPlayerId ? 'bg-green-600 hover:bg-green-700 shadow-green-100' : 'bg-blue-600 hover:bg-blue-700 shadow-blue-100'
                    }`}
                  >
                    <i className={`fas ${editingPlayerId ? 'fa-check-circle' : 'fa-plus-circle'}`}></i>
                    <span>{editingPlayerId ? 'Update Player Profile' : 'Finalize Player Registration'}</span>
                  </button>
                </div>
              </div>
            </div>
          </form>
        </div>
      )}

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
        {team.players.sort((a,b) => a.jerseyNumber - b.jerseyNumber).map(player => (
          <div 
            key={player.id} 
            onClick={() => handleEditClick(player)}
            className={`bg-white rounded-2xl shadow-sm border transition-all group cursor-pointer ${
              editingPlayerId === player.id ? 'border-blue-500 ring-4 ring-blue-50 shadow-xl scale-105' : 'border-gray-100 hover:shadow-xl hover:-translate-y-1'
            }`}
          >
            <div className="aspect-[3/4] bg-gray-100 relative overflow-hidden rounded-t-2xl">
              <img src={player.photoUrl} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" alt={player.name} />
              <div className="absolute top-4 left-4">
                <div className="bg-white/95 backdrop-blur px-3 py-1 rounded-lg text-xl font-black text-gray-900 border border-gray-100 shadow-sm">
                  #{player.jerseyNumber}
                </div>
              </div>
              <div className="absolute top-4 right-4 flex flex-col space-y-2 opacity-0 group-hover:opacity-100 transition-opacity">
                <button 
                  onClick={(e) => removePlayer(e, player.id)}
                  className="w-10 h-10 bg-red-500 text-white rounded-full flex items-center justify-center shadow-lg hover:bg-red-600 transition-colors"
                  title="Remove Player"
                >
                  <i className="fas fa-trash-alt"></i>
                </button>
              </div>
              <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/90 via-black/40 to-transparent p-4">
                <p className="text-white font-black text-lg truncate leading-tight">{player.name}</p>
                <div className="flex items-center space-x-2 mt-1">
                  <span className={`text-[10px] font-black px-2 py-0.5 rounded uppercase ${
                    player.position === 'Goalkeeper' ? 'bg-yellow-400 text-yellow-900' :
                    player.position === 'Defender' ? 'bg-blue-400 text-white' :
                    player.position === 'Midfielder' ? 'bg-green-400 text-white' :
                    'bg-red-400 text-white'
                  }`}>
                    {player.position}
                  </span>
                  <span className="text-white/70 text-[10px] font-bold uppercase">{player.age} Yrs</span>
                </div>
              </div>
            </div>
            <div className="p-4 bg-white flex justify-between items-center rounded-b-2xl border-t border-gray-50">
              <div className="flex items-center space-x-2">
                <i className="fas fa-edit text-blue-500 text-xs"></i>
                <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Click to Edit</span>
              </div>
              <div className="flex -space-x-1">
                 {[1,2,3].map(i => <div key={i} className="w-1.5 h-1.5 rounded-full bg-blue-500/20"></div>)}
              </div>
            </div>
          </div>
        ))}
        {team.players.length === 0 && !showAdd && (
          <div className="col-span-full py-24 bg-gray-50 border-2 border-dashed border-gray-200 rounded-3xl flex flex-col items-center justify-center space-y-6">
            <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center text-gray-300">
              <i className="fas fa-user-plus text-4xl"></i>
            </div>
            <div className="text-center space-y-2">
              <h4 className="text-xl font-bold text-gray-900">Start Your Squad</h4>
              <p className="text-gray-400 max-w-xs mx-auto">Click the button above to register your first player for the 2024 season.</p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

