  const addGoal = (player: Player, teamId: string) => {
    const existing = currentScorers.find(s => s.playerId === player.id);
    if (existing) {
      setCurrentScorers(currentScorers.map(s => s.playerId === player.id ? { ...s, goals: s.goals + 1 } : s));
    } else {
      setCurrentScorers([...currentScorers, { playerId: player.id, playerName: player.name, teamId, goals: 1 }]);
    }
  };

  const removeGoal = (playerId: string) => {
    const existing = currentScorers.find(s => s.playerId === playerId);
    if (existing && existing.goals > 1) {
      setCurrentScorers(currentScorers.map(s => s.playerId === playerId ? { ...s, goals: s.goals - 1 } : s));
    } else {
      setCurrentScorers(currentScorers.filter(s => s.playerId !== playerId));
    }
