  const saveResult = (match: Match) => {
    // Basic validation: ensure recorded goals match total score
    const homeGoals = currentScorers.filter(s => s.teamId === match.homeTeamId).reduce((sum, s) => sum + s.goals, 0);
    const awayGoals = currentScorers.filter(s => s.teamId === match.awayTeamId).reduce((sum, s) => sum + s.goals, 0);

