                          <p className="text-[10px] italic text-gray-300">No scorers recorded</p>
                        )}
                      </div>
                    </div>

                    {/* Away Scorers */}
                    <div>
                      <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-3">{awayTeam?.name} Scorers</h4>
                      <div className="space-y-2">
                        {currentScorers.filter(s => s.teamId === match.awayTeamId).map(s => (
                          <div key={s.playerId} className="flex items-center justify-between bg-gray-50 px-3 py-1.5 rounded-lg border border-gray-100">
                            <span className="text-xs font-bold text-gray-700">{s.playerName} ({s.goals})</span>
                            {isEditing && (
                              <div className="flex space-x-1">
                                <button onClick={() => addGoal({ id: s.playerId, name: s.playerName } as Player, match.awayTeamId)} className="w-5 h-5 bg-blue-100 text-blue-600 rounded flex items-center justify-center hover:bg-blue-200">+</button>
                                <button onClick={() => removeGoal(s.playerId)} className="w-5 h-5 bg-red-100 text-red-600 rounded flex items-center justify-center hover:bg-red-200">-</button>
                              </div>
                            )}
                          </div>
                        ))}
                        {isEditing && (
                          <select 
                            className="w-full text-xs border border-gray-200 rounded-lg p-2 bg-white"
                            onChange={(e) => {
                              const p = awayTeam?.players.find(p => p.id === e.target.value);
                              if (p) addGoal(p, match.awayTeamId);
                              e.target.value = "";
                            }}
                          >
                            <option value="">Add Scorer...</option>
                            {awayTeam?.players.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                          </select>
                        )}
                        {!isEditing && currentScorers.filter(s => s.teamId === match.awayTeamId).length === 0 && (
                          <p className="text-[10px] italic text-gray-300">No scorers recorded</p>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

