}

import React, { useState, useRef } from 'react';
import { Player, Team } from '../types';
import { MAX_SQUAD_SIZE } from '../constants';

interface PlayerManagerProps {
  team: Team;
  onUpdate: (players: Player[]) => void;
  onBack: () => void;
}

const PlayerManager: React.FC<PlayerManagerProps> = ({ team, onUpdate, onBack }) => {
  const [showAdd, setShowAdd] = useState(false);
  const [editingPlayerId, setEditingPlayerId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const formRef = useRef<HTMLDivElement>(null);
  const [previewPhoto, setPreviewPhoto] = useState<string>('');
  const [newPlayer, setNewPlayer] = useState<Partial<Player>>({
    name: '',
    jerseyNumber: 1,
    position: 'Goalkeeper',
    age: 18,
    photoUrl: '',
    goals: 0,
    assists: 0,
    appearances: 0
  });

  const handlePhotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        setPreviewPhoto(base64String);
        setNewPlayer(prev => ({ ...prev, photoUrl: base64String }));
      };
      reader.readAsDataURL(file);
    }
  };

  const isJerseyTaken = (num: number, excludeId: string | null) => {
    return team.players.some(p => p.jerseyNumber === num && p.id !== excludeId);
  };

  const savePlayer = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    const jerseyNum = newPlayer.jerseyNumber || 0;

    if (isJerseyTaken(jerseyNum, editingPlayerId)) {
      setError(`Jersey number #${jerseyNum} is already assigned to another player.`);
      return;
    }

    if (!editingPlayerId && team.players.length >= MAX_SQUAD_SIZE) {
      setError(`Maximum squad size of ${MAX_SQUAD_SIZE} reached.`);
      return;
    }

    if (editingPlayerId) {
      const updatedPlayers = team.players.map(p => 
        p.id === editingPlayerId 
          ? { ...p, ...newPlayer as Player } 
          : p
      );
      onUpdate(updatedPlayers);
    } else {
      const player: Player = {
        id: `p${Date.now()}`,
        name: newPlayer.name || 'Unknown Player',
        jerseyNumber: jerseyNum,
        position: newPlayer.position || 'Unknown',
        age: newPlayer.age || 18,
        photoUrl: newPlayer.photoUrl || `https://api.dicebear.com/7.x/avataaars/svg?seed=${newPlayer.name}`,
        goals: newPlayer.goals || 0,
        assists: newPlayer.assists || 0,
        appearances: newPlayer.appearances || 0
      };
      onUpdate([...team.players, player]);
    }

    setShowAdd(false);
    setEditingPlayerId(null);
    resetForm();
  };

  const resetForm = () => {
    setNewPlayer({ name: '', jerseyNumber: 1, position: 'Goalkeeper', age: 18, photoUrl: '', goals: 0, assists: 0, appearances: 0 });
    setPreviewPhoto('');
    setEditingPlayerId(null);
    setError(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleEditClick = (player: Player) => {
    setNewPlayer(player);
    setPreviewPhoto(player.photoUrl);
    setEditingPlayerId(player.id);
    setError(null);
    setShowAdd(true);
    setTimeout(() => {
      formRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }, 100);
  };

  const removePlayer = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm('Are you sure you want to remove this player from the squad?')) {
      onUpdate(team.players.filter(p => p.id !== id));
      if (editingPlayerId === id) resetForm();
    }
  };

  const positionsCount = team.players.reduce((acc, p) => {
    acc[p.position] = (acc[p.position] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="flex items-center space-x-4">
          <button onClick={onBack} className="bg-white border border-gray-200 p-3 rounded-xl hover:bg-gray-50 transition-colors shadow-sm text-gray-600">
            <i className="fas fa-arrow-left"></i>
          </button>
          <div className="flex items-center space-x-4">
            <img src={team.logo} className="w-16 h-16 rounded-2xl border-4 border-white shadow-md object-cover" alt="" />
            <div>
              <h2 className="text-3xl font-black text-gray-900 tracking-tight">{team.name}</h2>
              <div className="flex items-center space-x-2 text-sm text-gray-500">
                <span className="bg-blue-100 text-blue-700 px-2 py-0.5 rounded font-bold uppercase text-[10px]">Manager</span>
                <span>{team.manager}</span>
              </div>
            </div>
          </div>
        </div>
        <button 
          onClick={() => {
            if (showAdd) resetForm();
            setShowAdd(!showAdd);
          }}
          className={`flex items-center justify-center space-x-2 px-6 py-3 rounded-xl font-bold transition-all shadow-lg ${
            showAdd ? 'bg-gray-200 text-gray-700 hover:bg-gray-300' : 'bg-blue-600 text-white hover:bg-blue-700 shadow-blue-200'
          }`}
        >
          <i className={`fas ${showAdd ? 'fa-times' : 'fa-user-plus'}`}></i>
          <span>{showAdd ? 'Cancel' : 'Register New Player'}</span>
        </button>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm">
          <p className="text-xs font-bold text-gray-400 uppercase">Squad Size</p>
          <p className="text-2xl font-black text-gray-900">{team.players.length} <span className="text-gray-300 text-sm">/ {MAX_SQUAD_SIZE}</span></p>
        </div>
        <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm">
          <p className="text-xs font-bold text-gray-400 uppercase">Total Goals</p>
          <p className="text-2xl font-black text-blue-600">{team.players.reduce((sum, p) => sum + (p.goals || 0), 0)}</p>
        </div>
        <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm">
          <p className="text-xs font-bold text-gray-400 uppercase">Total Assists</p>
          <p className="text-2xl font-black text-indigo-600">{team.players.reduce((sum, p) => sum + (p.assists || 0), 0)}</p>
        </div>
        <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm">
          <p className="text-xs font-bold text-gray-400 uppercase">Avg. Appearances</p>
          <p className="text-2xl font-black text-gray-900">
            {team.players.length ? (team.players.reduce((a, b) => a + (b.appearances || 0), 0) / team.players.length).toFixed(1) : '0'}
          </p>
        </div>
      </div>

      {showAdd && (
        <div ref={formRef} className="bg-white rounded-3xl border-2 border-blue-100 shadow-2xl overflow-hidden animate-in slide-in-from-top-8 duration-300">
          <div className="bg-blue-600 p-6 text-white flex justify-between items-center">
            <div>
              <h3 className="text-xl font-bold">{editingPlayerId ? 'Edit Player Profile' : 'Player Registration Form'}</h3>
              <p className="text-blue-100 text-sm">Official season data and player statistics.</p>
            </div>
            {editingPlayerId && (
              <button onClick={resetForm} className="text-xs bg-white/20 hover:bg-white/30 px-3 py-1.5 rounded-lg font-bold uppercase tracking-wider transition-colors">
                New Player instead
              </button>
            )}
          </div>
          <form onSubmit={savePlayer} className="p-8">
            {error && (
              <div className="mb-6 p-4 bg-red-50 border-l-4 border-red-500 rounded-r-xl flex items-center space-x-3 animate-in fade-in slide-in-from-left-4">
                <i className="fas fa-exclamation-circle text-red-500"></i>
                <p className="text-red-700 text-sm font-bold">{error}</p>
              </div>
            )}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
              <div className="flex flex-col items-center space-y-4">
                <div 
                  onClick={() => fileInputRef.current?.click()}
                  className="w-48 h-60 bg-gray-50 border-2 border-dashed border-gray-200 rounded-2xl flex flex-col items-center justify-center cursor-pointer hover:border-blue-400 hover:bg-blue-50 transition-all group relative overflow-hidden"
                >
                  {previewPhoto ? (
                    <>
                      <img src={previewPhoto} className="w-full h-full object-cover" alt="Preview" />
                      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                        <span className="text-white text-xs font-bold">Change Photo</span>
                      </div>
                    </>
                  ) : (
                    <div className="text-center p-4">
                      <div className="w-12 h-12 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-2 text-gray-400 group-hover:text-blue-500 transition-colors">
                        <i className="fas fa-camera text-xl"></i>
                      </div>
                      <p className="text-xs font-bold text-gray-400 group-hover:text-blue-600 uppercase">Upload Photo</p>
                    </div>
                  )}
                </div>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handlePhotoChange} />
              </div>

              <div className="md:col-span-2 space-y-8">
                <div className="space-y-4">
                  <h4 className="text-sm font-black text-gray-900 border-b pb-2 uppercase tracking-widest">Personal Info</h4>
