                <div className="flex items-center justify-center space-x-4 md:space-x-8 w-full md:w-2/4">
                  <div className="flex flex-col items-center space-y-3 w-1/3 group/home text-center">
                    <img src={homeTeam?.logo} alt="" className="w-14 h-14 rounded-full border-4 border-white shadow-md group-hover/home:scale-110 transition-transform" />
                    <span className="text-sm font-black text-gray-900 leading-tight">{homeTeam?.name}</span>
                  </div>

                  <div className="flex flex-col items-center justify-center px-4 min-w-[140px]">
                    {isEditing ? (
                      <div className="flex items-center space-x-2">
                        <input 
                          type="number" 
                          min="0"
                          className="w-12 text-center border-2 border-blue-300 rounded-lg font-black py-2 focus:ring-2 focus:ring-blue-500 outline-none text-blue-700 shadow-inner"
                          value={scores.home}
                          onChange={(e) => setScores({ ...scores, home: parseInt(e.target.value) || 0 })}
                        />
                        <span className="font-bold text-blue-300 text-lg">:</span>
                        <input 
