                          className="w-12 text-center border-2 border-blue-300 rounded-lg font-black py-2 focus:ring-2 focus:ring-blue-500 outline-none text-blue-700 shadow-inner"
                          value={scores.away}
                          onChange={(e) => setScores({ ...scores, away: parseInt(e.target.value) || 0 })}
                        />
                      </div>
                    ) : match.isCompleted ? (
                      <div className="flex flex-col items-center">
                        <div className="flex items-center space-x-4 bg-gray-50 px-6 py-2 rounded-2xl border border-gray-100">
                          <span className="text-3xl font-black text-gray-900">{match.homeScore}</span>
                          <span className="text-gray-300 font-bold text-xl">:</span>
                          <span className="text-3xl font-black text-gray-900">{match.awayScore}</span>
                        </div>
                        <span className="text-[10px] font-bold text-green-600 mt-2 uppercase tracking-widest">Final Result</span>
                      </div>
                    ) : (
                      <div className="bg-gray-100 text-gray-400 px-4 py-1.5 rounded-full text-[10px] font-black tracking-widest uppercase border border-gray-200">UPCOMING</div>
                    )}
                  </div>

                  <div className="flex flex-col items-center space-y-3 w-1/3 group/away text-center">
                    <img src={awayTeam?.logo} alt="" className="w-14 h-14 rounded-full border-4 border-white shadow-md group-hover/away:scale-110 transition-transform" />
                    <span className="text-sm font-black text-gray-900 leading-tight">{awayTeam?.name}</span>
                  </div>
                </div>

                <div className="flex justify-center md:justify-end w-full md:w-1/4 mt-6 md:mt-0">
                  {canManageMatch(match) && !isEditing ? (
                    <button 
                      onClick={() => startEditing(match)}
                      className="bg-green-600 text-white px-6 py-2.5 rounded-xl text-sm font-black hover:bg-green-700 shadow-lg shadow-green-100 transition-all flex items-center space-x-2 active:scale-95"
                    >
                      <i className="fas fa-edit"></i>
                      <span>{match.isCompleted ? 'Edit Result' : 'Enter Result'}</span>
                    </button>
                  ) : isEditing ? (
                    <div className="flex space-x-2">
                      <button 
                        onClick={() => saveResult(match)} 
                        className="bg-blue-600 text-white text-xs px-4 py-2 rounded-lg font-black uppercase hover:bg-blue-700 shadow-sm"
                      >
                        Save
                      </button>
                      <button 
