              {/* Goal Scorers Section */}
              {(isEditing || (match.scorers && match.scorers.length > 0)) && (
                <div className="mt-6 pt-6 border-t border-gray-100">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    {/* Home Scorers */}
