            <div key={match.id} className={`bg-white rounded-3xl border ${isManagerMatch ? 'border-blue-200 ring-4 ring-blue-50/50 shadow-blue-100 shadow-xl' : 'border-gray-100'} p-6 flex flex-col hover:shadow-xl transition-all group relative overflow-hidden`}>
              <div className="flex flex-col md:flex-row items-center justify-between">
                <div className="flex flex-col items-center md:items-start space-y-1 mb-4 md:mb-0 w-full md:w-1/4">
                  <div className="flex items-center space-x-2">
