import React, { useState } from 'react';
import { Match, Team, UserRole, GoalScorer, Player } from '../types';

interface MatchSchedulerProps {
  matches: Match[];
  teams: Team[];
  isAdmin: boolean;
  role: UserRole;
  selectedTeamId: string | null;
  onAddMatch: (m: Match) => void;
  onUpdateMatch: (id: string, h: number, a: number, scorers: GoalScorer[]) => void;
}

const MatchScheduler: React.FC<MatchSchedulerProps> = ({ 
  matches, 
  teams, 
  isAdmin, 
  role,
  selectedTeamId,
  onAddMatch, 
  onUpdateMatch 
}) => {
  const [showAdd, setShowAdd] = useState(false);
  const [editingMatchId, setEditingMatchId] = useState<string | null>(null);
  const [scores, setScores] = useState({ home: 0, away: 0 });
  const [currentScorers, setCurrentScorers] = useState<GoalScorer[]>([]);

  const [newMatch, setNewMatch] = useState<Partial<Match>>({
    date: '',
    time: '',
    venue: '',
    homeTeamId: '',
    awayTeamId: '',
    matchWeek: 1
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newMatch.homeTeamId && newMatch.awayTeamId && newMatch.homeTeamId !== newMatch.awayTeamId) {
      onAddMatch({
        ...newMatch as Match,
        id: `m${Date.now()}`,
        isCompleted: false
      });
      setShowAdd(false);
      setNewMatch({
        date: '',
        time: '',
        venue: '',
        homeTeamId: '',
        awayTeamId: '',
        matchWeek: (newMatch.matchWeek || 1)
      });
    }
  };

  const getTeam = (id: string) => teams.find(t => t.id === id);

  const canManageMatch = (match: Match) => {
    if (isAdmin) return true;
    if (role === UserRole.TEAM_MANAGER && selectedTeamId) {
      return match.homeTeamId === selectedTeamId || match.awayTeamId === selectedTeamId;
    }
    return false;
  };

  const startEditing = (match: Match) => {
    setEditingMatchId(match.id);
    setScores({ home: match.homeScore || 0, away: match.awayScore || 0 });
    setCurrentScorers(match.scorers || []);
  };

  const addGoal = (player: Player, teamId: string) => {
    setCurrentScorers([...currentScorers, { 
      playerId: player.id, 
      playerName: player.name, 
      teamId, 
      goals: 1, 
      minute: 0 
    }].sort((a, b) => (a.minute || 0) - (b.minute || 0)));
  };

  const updateScorerMinute = (index: number, minute: number) => {
    const updated = [...currentScorers];
    updated[index] = { ...updated[index], minute };
    setCurrentScorers(updated.sort((a, b) => (a.minute || 0) - (b.minute || 0)));
  };

  const removeGoal = (index: number) => {
    setCurrentScorers(currentScorers.filter((_, i) => i !== index));
  };

  const saveResult = (match: Match) => {
    onUpdateMatch(match.id, scores.home, scores.away, currentScorers);
    setEditingMatchId(null);
  };

  // Helper to find player photo by ID from any team
  const getPlayerPhoto = (playerId: string) => {
    for (const team of teams) {
      const player = team.players.find(p => p.id === playerId);
      if (player) return player.photoUrl;
    }
    return `https://api.dicebear.com/7.x/avataaars/svg?seed=${playerId}`;
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-3xl font-black text-gray-900 tracking-tight">Fixtures & Results</h2>
          <p className="text-gray-500">Upcoming games and recent scores.</p>
        </div>
        {isAdmin && (
          <button 
            onClick={() => setShowAdd(!showAdd)}
            className="bg-blue-600 text-white px-6 py-3 rounded-xl font-bold shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all flex items-center space-x-2 w-full md:w-auto justify-center"
          >
            <i className={`fas ${showAdd ? 'fa-times' : 'fa-plus'}`}></i>
            <span>{showAdd ? 'Cancel' : 'Schedule New Match'}</span>
          </button>
        )}
      </div>

      {showAdd && (
        <form onSubmit={handleSubmit} className="bg-white p-8 rounded-3xl border border-blue-100 shadow-2xl grid grid-cols-1 md:grid-cols-3 gap-6 animate-in slide-in-from-top-4 duration-300">
          <div className="space-y-2">
            <label className="text-xs font-black text-gray-400 uppercase tracking-widest">Home Team</label>
            <select required className="w-full border border-gray-200 rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-blue-500 bg-gray-50" value={newMatch.homeTeamId} onChange={e => setNewMatch({ ...newMatch, homeTeamId: e.target.value })}>
              <option value="">Select Home</option>
              {teams.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
            </select>
          </div>
          <div className="space-y-2 text-center flex flex-col justify-center">
            <span className="text-2xl font-black text-gray-200">VS</span>
          </div>
          <div className="space-y-2">
            <label className="text-xs font-black text-gray-400 uppercase tracking-widest">Away Team</label>
            <select required className="w-full border border-gray-200 rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-blue-500 bg-gray-50" value={newMatch.awayTeamId} onChange={e => setNewMatch({ ...newMatch, awayTeamId: e.target.value })}>
              <option value="">Select Away</option>
              {teams.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-xs font-black text-gray-400 uppercase tracking-widest">Date & Time</label>
            <div className="flex space-x-2">
              <input type="date" required className="flex-1 border border-gray-200 rounded-xl px-4 py-3 bg-gray-50" value={newMatch.date} onChange={e => setNewMatch({ ...newMatch, date: e.target.value })} />
              <input type="time" required className="w-28 border border-gray-200 rounded-xl px-4 py-3 bg-gray-50" value={newMatch.time} onChange={e => setNewMatch({ ...newMatch, time: e.target.value })} />
            </div>
          </div>
          <div className="space-y-2">
            <label className="text-xs font-black text-gray-400 uppercase tracking-widest">Venue</label>
            <input type="text" required className="w-full border border-gray-200 rounded-xl px-4 py-3 bg-gray-50" placeholder="Stadium Name" value={newMatch.venue} onChange={e => setNewMatch({ ...newMatch, venue: e.target.value })} />
          </div>
          <div className="space-y-2">
            <label className="text-xs font-black text-gray-400 uppercase tracking-widest">Match Week</label>
            <input type="number" min="1" required className="w-full border border-gray-200 rounded-xl px-4 py-3 bg-gray-50 focus:ring-2 focus:ring-blue-500 outline-none" placeholder="e.g. 1" value={newMatch.matchWeek} onChange={e => setNewMatch({ ...newMatch, matchWeek: parseInt(e.target.value) || 1 })} />
          </div>
          <div className="flex items-end md:col-span-3">
            <button type="submit" className="w-full bg-blue-600 text-white py-3.5 rounded-xl font-black hover:bg-blue-700 transition-all shadow-lg shadow-blue-100 uppercase tracking-widest text-sm">
              Confirm Schedule
            </button>
          </div>
        </form>
      )}

      <div className="space-y-6">
        {matches.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime()).map(match => {
          const isManagerMatch = !isAdmin && role === UserRole.TEAM_MANAGER && (match.homeTeamId === selectedTeamId || match.awayTeamId === selectedTeamId);
          const isEditing = editingMatchId === match.id;
          const homeTeam = getTeam(match.homeTeamId);
          const awayTeam = getTeam(match.awayTeamId);

          return (
            <div key={match.id} className={`bg-white rounded-3xl border ${isManagerMatch ? 'border-blue-200 ring-4 ring-blue-50/50 shadow-blue-100 shadow-xl' : 'border-gray-100'} p-6 flex flex-col hover:shadow-xl transition-all group relative overflow-hidden`}>
              <div className="flex flex-col md:flex-row items-center justify-between">
                <div className="flex flex-col items-center md:items-start space-y-1 mb-4 md:mb-0 w-full md:w-1/4">
                  <div className="flex items-center space-x-2">
                    <span className="text-[10px] font-black text-blue-600 bg-blue-50 px-2 py-0.5 rounded-full uppercase tracking-tighter">WEEK {match.matchWeek}</span>
                  </div>
                  <span className="text-lg font-black text-gray-900">{new Date(match.date).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' })}</span>
                  <span className="text-xs text-gray-400 font-medium uppercase tracking-widest">{match.time} • {match.venue}</span>
                </div>

                <div className="flex items-center justify-center space-x-4 md:space-x-8 w-full md:w-2/4">
                  <div className="flex flex-col items-center space-y-3 w-1/3 group/home text-center">
                    <img src={homeTeam?.logo} alt="" className="w-14 h-14 rounded-full border-4 border-white shadow-md group-hover/home:scale-110 transition-transform object-cover" />
                    <span className="text-sm font-black text-gray-900 leading-tight">{homeTeam?.name}</span>
                  </div>

                  <div className="flex flex-col items-center justify-center px-4 min-w-[140px]">
                    {isEditing ? (
                      <div className="flex items-center space-x-2">
                        <input type="number" min="0" className="w-12 text-center border-2 border-blue-300 rounded-lg font-black py-2 text-blue-700" value={scores.home} onChange={(e) => setScores({ ...scores, home: parseInt(e.target.value) || 0 })} />
                        <span className="font-bold text-blue-300 text-lg">:</span>
                        <input type="number" min="0" className="w-12 text-center border-2 border-blue-300 rounded-lg font-black py-2 text-blue-700" value={scores.away} onChange={(e) => setScores({ ...scores, away: parseInt(e.target.value) || 0 })} />
                      </div>
                    ) : match.isCompleted ? (
                      <div className="flex flex-col items-center">
                        <div className="flex items-center space-x-4 bg-gray-50 px-6 py-2 rounded-2xl border border-gray-100">
                          <span className="text-3xl font-black text-gray-900">{match.homeScore}</span>
                          <span className="text-gray-300 font-bold text-xl">:</span>
                          <span className="text-3xl font-black text-gray-900">{match.awayScore}</span>
                        </div>
                      </div>
                    ) : (
                      <div className="bg-gray-100 text-gray-400 px-4 py-1.5 rounded-full text-[10px] font-black tracking-widest uppercase border border-gray-200">UPCOMING</div>
                    )}
                  </div>

                  <div className="flex flex-col items-center space-y-3 w-1/3 group/away text-center">
                    <img src={awayTeam?.logo} alt="" className="w-14 h-14 rounded-full border-4 border-white shadow-md group-hover/away:scale-110 transition-transform object-cover" />
                    <span className="text-sm font-black text-gray-900 leading-tight">{awayTeam?.name}</span>
                  </div>
                </div>

                <div className="flex justify-center md:justify-end w-full md:w-1/4 mt-6 md:mt-0">
                  {canManageMatch(match) && !isEditing ? (
                    <button onClick={() => startEditing(match)} className="bg-green-600 text-white px-6 py-2.5 rounded-xl text-sm font-black hover:bg-green-700 shadow-lg shadow-green-100 transition-all flex items-center space-x-2">
                      <i className="fas fa-edit"></i>
                      <span>{match.isCompleted ? 'Edit Result' : 'Enter Result'}</span>
                    </button>
                  ) : isEditing ? (
                    <div className="flex space-x-2">
                      <button onClick={() => saveResult(match)} className="bg-blue-600 text-white text-xs px-4 py-2 rounded-lg font-black uppercase hover:bg-blue-700">Save</button>
                      <button onClick={() => setEditingMatchId(null)} className="bg-white text-gray-500 text-xs px-4 py-2 rounded-lg font-black uppercase hover:bg-gray-100 border border-gray-200">Cancel</button>
                    </div>
                  ) : match.isCompleted ? (
                    <div className="flex items-center space-x-1.5 bg-green-50 px-4 py-2 rounded-xl">
                      <i className="fas fa-check-double text-green-500 text-xs"></i>
                      <span className="text-[10px] font-black text-green-700 uppercase tracking-widest">Verified</span>
                    </div>
                  ) : null}
                </div>
              </div>

              {/* Enhanced Chronological Goal Events Section */}
              {(isEditing || (match.scorers && match.scorers.length > 0)) && (
                <div className="mt-8 pt-8 border-t border-gray-100 space-y-8 animate-in slide-in-from-bottom-2 duration-300">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                    {/* Home Team Scorer Entry */}
                    <div className="space-y-4">
                      <div className="flex items-center space-x-2 mb-2">
                        <img src={homeTeam?.logo} className="w-6 h-6 rounded-full" alt="" />
                        <h4 className="text-[11px] font-black text-gray-900 uppercase tracking-wider">{homeTeam?.name} Timeline</h4>
                      </div>

                      <div className="space-y-3">
                        {currentScorers.filter(s => s.teamId === match.homeTeamId).map((s, idx) => (
                          <div key={`${s.playerId}-${idx}`} className="group flex items-center justify-between bg-blue-50/40 p-3 rounded-2xl border border-blue-100/50 hover:border-blue-200 transition-all">
                            <div className="flex items-center space-x-4">
                              <div className="bg-white w-10 h-10 rounded-xl flex items-center justify-center border border-blue-100 shadow-sm font-black text-blue-600 text-sm">
                                {s.minute}'
                              </div>
                              <img src={getPlayerPhoto(s.playerId)} className="w-10 h-10 rounded-full border-2 border-white shadow-sm object-cover" alt="" />
                              <div>
                                <p className="text-sm font-black text-gray-900">{s.playerName}</p>
                                <p className="text-[10px] font-bold text-gray-400 uppercase">Goal Scored</p>
                              </div>
                            </div>
                            {isEditing && (
                              <div className="flex items-center space-x-3">
                                <div className="flex items-center space-x-1 bg-white border border-gray-200 rounded-lg px-2 py-1">
                                  <label className="text-[10px] font-black text-gray-400 uppercase">Min</label>
                                  <input 
                                    type="number" 
                                    min="0" max="120"
                                    className="w-8 text-[11px] font-black text-blue-600 outline-none"
                                    value={s.minute || 0}
                                    onChange={(e) => updateScorerMinute(currentScorers.indexOf(s), parseInt(e.target.value) || 0)}
                                  />
                                </div>
                                <button onClick={() => removeGoal(currentScorers.indexOf(s))} className="w-8 h-8 bg-red-50 text-red-500 rounded-xl flex items-center justify-center hover:bg-red-500 hover:text-white transition-all">
                                  <i className="fas fa-times text-xs"></i>
                                </button>
                              </div>
                            )}
                          </div>
                        ))}
                        {isEditing && (
                          <div className="pt-2">
                            <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-2 px-1">Add Scoring Event</label>
                            <select 
                              className="w-full text-xs font-bold border-2 border-gray-100 rounded-2xl p-3 bg-gray-50 focus:border-blue-500 focus:bg-white outline-none transition-all"
                              onChange={(e) => {
                                const p = homeTeam?.players.find(p => p.id === e.target.value);
                                if (p) addGoal(p, match.homeTeamId);
                                e.target.value = "";
                              }}
                            >
                              <option value="">Select a Player...</option>
                              {homeTeam?.players.map(p => <option key={p.id} value={p.id}>{p.name} (#{p.jerseyNumber})</option>)}
                            </select>
                          </div>
                        )}
                        {!isEditing && currentScorers.filter(s => s.teamId === match.homeTeamId).length === 0 && (
                          <p className="text-xs italic text-gray-400 pl-2">No goals recorded</p>
                        )}
                      </div>
                    </div>

                    {/* Away Team Scorer Entry */}
                    <div className="space-y-4">
                      <div className="flex items-center space-x-2 mb-2">
                        <img src={awayTeam?.logo} className="w-6 h-6 rounded-full" alt="" />
                        <h4 className="text-[11px] font-black text-gray-900 uppercase tracking-wider">{awayTeam?.name} Timeline</h4>
                      </div>

                      <div className="space-y-3">
                        {currentScorers.filter(s => s.teamId === match.awayTeamId).map((s, idx) => (
                          <div key={`${s.playerId}-${idx}`} className="group flex items-center justify-between bg-indigo-50/40 p-3 rounded-2xl border border-indigo-100/50 hover:border-indigo-200 transition-all">
                            <div className="flex items-center space-x-4">
                              <div className="bg-white w-10 h-10 rounded-xl flex items-center justify-center border border-indigo-100 shadow-sm font-black text-indigo-600 text-sm">
                                {s.minute}'
                              </div>
                              <img src={getPlayerPhoto(s.playerId)} className="w-10 h-10 rounded-full border-2 border-white shadow-sm object-cover" alt="" />
                              <div>
                                <p className="text-sm font-black text-gray-900">{s.playerName}</p>
                                <p className="text-[10px] font-bold text-gray-400 uppercase">Goal Scored</p>
                              </div>
                            </div>
                            {isEditing && (
                              <div className="flex items-center space-x-3">
                                <div className="flex items-center space-x-1 bg-white border border-gray-200 rounded-lg px-2 py-1">
                                  <label className="text-[10px] font-black text-gray-400 uppercase">Min</label>
                                  <input 
                                    type="number" 
                                    min="0" max="120"
                                    className="w-8 text-[11px] font-black text-indigo-600 outline-none"
                                    value={s.minute || 0}
                                    onChange={(e) => updateScorerMinute(currentScorers.indexOf(s), parseInt(e.target.value) || 0)}
                                  />
                                </div>
                                <button onClick={() => removeGoal(currentScorers.indexOf(s))} className="w-8 h-8 bg-red-50 text-red-500 rounded-xl flex items-center justify-center hover:bg-red-500 hover:text-white transition-all">
                                  <i className="fas fa-times text-xs"></i>
                                </button>
                              </div>
                            )}
                          </div>
                        ))}
                        {isEditing && (
                          <div className="pt-2">
                            <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-2 px-1">Add Scoring Event</label>
                            <select 
                              className="w-full text-xs font-bold border-2 border-gray-100 rounded-2xl p-3 bg-gray-50 focus:border-indigo-500 focus:bg-white outline-none transition-all"
                              onChange={(e) => {
                                const p = awayTeam?.players.find(p => p.id === e.target.value);
                                if (p) addGoal(p, match.awayTeamId);
                                e.target.value = "";
                              }}
                            >
                              <option value="">Select a Player...</option>
                              {awayTeam?.players.map(p => <option key={p.id} value={p.id}>{p.name} (#{p.jerseyNumber})</option>)}
                            </select>
                          </div>
                        )}
                        {!isEditing && currentScorers.filter(s => s.teamId === match.awayTeamId).length === 0 && (
                          <p className="text-xs italic text-gray-400 pl-2">No goals recorded</p>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default MatchScheduler;

import React, { useState, useRef, useEffect } from 'react';
import { Team } from '../types';

interface TeamRegistrationProps {
  onRegister: (team: Omit<Team, 'id' | 'players'>) => void;
  existingNames: string[];
  initialData?: Team; // Optional prop to enable "Edit Mode"
  onCancel?: () => void;
}

const TeamRegistration: React.FC<TeamRegistrationProps> = ({ onRegister, existingNames, initialData, onCancel }) => {
  const [formData, setFormData] = useState({
    name: '',
    manager: '',
    contact: '',
    homeGround: '',
    logo: ''
  });
  const [error, setError] = useState('');
  const [previewLogo, setPreviewLogo] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const isEditMode = !!initialData;

  useEffect(() => {
    if (initialData) {
      setFormData({
        name: initialData.name,
        manager: initialData.manager,
        contact: initialData.contact,
        homeGround: initialData.homeGround,
        logo: initialData.logo
      });
      setPreviewLogo(initialData.logo);
    }
  }, [initialData]);

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) {
        setError('Logo file size must be under 2MB');
        return;
      }

      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        setPreviewLogo(base64String);
        setFormData(prev => ({ ...prev, logo: base64String }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // Check for duplicate names, but ignore if it's the current team's name in edit mode
    const isDuplicate = existingNames.some(name => 
      name.toLowerCase() === formData.name.toLowerCase() && 
      (!isEditMode || name.toLowerCase() !== initialData?.name.toLowerCase())
    );

    if (isDuplicate) {
      setError('Team name already exists!');
      return;
    }
    setError('');

    const finalLogo = formData.logo || `https://picsum.photos/seed/${formData.name.replace(/\s+/g, '')}/200/200`;

    onRegister({
      ...formData,
      logo: finalLogo
    });
  };

  return (
    <div className="max-w-2xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="bg-white p-8 rounded-3xl shadow-xl border border-gray-100">
        <div className="text-center mb-10">
          <div className={`w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-4 shadow-lg ${isEditMode ? 'bg-indigo-600 shadow-indigo-200' : 'bg-blue-600 shadow-blue-200'}`}>
            <i className={`fas ${isEditMode ? 'fa-user-edit' : 'fa-users-cog'} text-white text-3xl`}></i>
          </div>
          <h2 className="text-3xl font-black text-gray-900">
            {isEditMode ? 'Update Team Profile' : 'Register Your Team'}
          </h2>
          <p className="text-gray-500 mt-2">
            {isEditMode ? 'Maintain your organization and leadership details.' : 'Join the elite competition today.'}
          </p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-8">
          {/* Logo Upload Section */}
          <div className="flex flex-col items-center">
            <label className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] mb-4">Team Identity (Logo)</label>
            <div 
              onClick={() => fileInputRef.current?.click()}
              className="group relative w-32 h-32 rounded-3xl bg-gray-50 border-2 border-dashed border-gray-200 flex items-center justify-center cursor-pointer hover:border-blue-400 hover:bg-blue-50 transition-all overflow-hidden shadow-inner"
            >
              {previewLogo ? (
                <img src={previewLogo} className="w-full h-full object-cover" alt="Preview" />
              ) : (
                <div className="text-center p-2">
                  <i className="fas fa-cloud-upload-alt text-2xl text-gray-300 group-hover:text-blue-500 transition-colors mb-1"></i>
                  <p className="text-[10px] font-bold text-gray-400 uppercase">Upload Logo</p>
                </div>
              )}
              <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                <span className="text-white text-[10px] font-black uppercase">Change Image</span>
              </div>
            </div>
            <input 
              type="file" 
              ref={fileInputRef} 
              className="hidden" 
              accept="image/*" 
              onChange={handleLogoChange} 
            />
            {!isEditMode && <p className="text-[10px] text-gray-400 mt-3 italic">Leave empty for an auto-generated placeholder</p>}
          </div>

          <div className="space-y-6">
            <h4 className="text-[11px] font-black text-gray-400 border-b border-gray-100 pb-2 uppercase tracking-[0.2em]">General Information</h4>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2 md:col-span-2">
                <label className="text-xs font-bold text-gray-700 block">Team Name</label>
                <input 
                  required
                  className="w-full border border-gray-200 bg-gray-50 rounded-xl px-4 py-3 focus:ring-4 focus:ring-blue-50 focus:border-blue-400 outline-none transition-all font-semibold"
                  placeholder="e.g. Manchester Blues"
                  value={formData.name}
                  onChange={e => setFormData({ ...formData, name: e.target.value })}
                />
                {error && <p className="text-red-500 text-xs font-semibold mt-1 flex items-center"><i className="fas fa-exclamation-circle mr-1"></i> {error}</p>}
              </div>

              <div className="space-y-2 md:col-span-2">
                <label className="text-xs font-bold text-gray-700 block">Home Ground</label>
                <input 
                  required
                  className="w-full border border-gray-200 bg-gray-50 rounded-xl px-4 py-3 focus:ring-4 focus:ring-blue-50 focus:border-blue-400 outline-none transition-all font-semibold"
                  placeholder="Stadium Name"
                  value={formData.homeGround}
                  onChange={e => setFormData({ ...formData, homeGround: e.target.value })}
                />
              </div>
            </div>
          </div>

          {/* Dedicated Manager Section */}
          <div className="space-y-6 bg-blue-50/30 p-6 rounded-3xl border border-blue-50">
            <div className="flex items-center space-x-2 border-b border-blue-100 pb-2">
              <i className="fas fa-user-tie text-blue-500 text-xs"></i>
              <h4 className="text-[11px] font-black text-blue-600 uppercase tracking-[0.2em]">Leadership & Contact</h4>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
