              <div className="text-center space-y-2 mb-8">
                <span className="text-[10px] font-black text-blue-300 uppercase tracking-[0.3em]">Season 2024 • Matchweek {selectedMatch.matchWeek}</span>
                <p className="text-sm font-bold text-gray-400">{selectedMatch.venue}</p>
              </div>

              <div className="flex items-center justify-between">
                <div className="flex flex-col items-center space-y-4 w-1/3">
                  <img src={getTeam(selectedMatch.homeTeamId)?.logo} className="w-20 h-20 rounded-full border-4 border-white/20 shadow-2xl object-cover" alt="" />
                  <h3 className="text-xl font-black tracking-tight text-center leading-tight">{getTeam(selectedMatch.homeTeamId)?.name}</h3>
                </div>

                <div className="flex flex-col items-center justify-center px-4 w-1/3">
                  <div className="flex items-center space-x-6">
                    <span className="text-6xl font-black tracking-tighter">{selectedMatch.homeScore}</span>
                    <span className="text-4xl font-black text-white/20">-</span>
                    <span className="text-6xl font-black tracking-tighter">{selectedMatch.awayScore}</span>
                  </div>
                  <div className="mt-4 px-4 py-1.5 rounded-full bg-green-500/20 border border-green-500/30 text-green-400 text-[10px] font-black tracking-widest uppercase">Full Time</div>
                </div>

                <div className="flex flex-col items-center space-y-4 w-1/3">
                  <img src={getTeam(selectedMatch.awayTeamId)?.logo} className="w-20 h-20 rounded-full border-4 border-white/20 shadow-2xl object-cover" alt="" />
                  <h3 className="text-xl font-black tracking-tight text-center leading-tight">{getTeam(selectedMatch.awayTeamId)?.name}</h3>
                </div>
              </div>
            </div>

            <div className="p-10 bg-gray-50">
              <h4 className="text-center text-[10px] font-black text-gray-400 uppercase tracking-[0.4em] mb-10">Match Timeline</h4>

              <div className="relative space-y-6 before:absolute before:inset-0 before:ml-5 before:-translate-x-px md:before:mx-auto md:before:translate-x-0 before:h-full before:w-0.5 before:bg-gradient-to-b before:from-transparent before:via-gray-200 before:to-transparent">
                {timelineEvents.map((event, idx) => {
                  const isHome = event.teamId === selectedMatch.homeTeamId;
                  const isCard = 'type' in event;

                  return (
                    <div key={idx} className={`relative flex items-center justify-between md:justify-normal md:odd:flex-row-reverse group animate-in slide-in-from-bottom-4`} style={{ animationDelay: `${idx * 100}ms` }}>
                      {/* Timeline dot */}
                      <div className={`flex items-center justify-center w-10 h-10 rounded-full border border-white shadow shrink-0 md:order-1 md:group-odd:-translate-x-1/2 md:group-even:translate-x-1/2 z-10 ${
                        'eventType' in event && event.eventType === 'goal' ? 'bg-blue-600 text-white' : 
                        isCard && (event as CardEvent).type === 'yellow' ? 'bg-yellow-400 text-yellow-900' : 'bg-red-500 text-white'
                      }`}>
                        <span className="text-[10px] font-black">{event.minute}'</span>
                      </div>

                      {/* Content card */}
                      <div className={`w-[calc(100%-4rem)] md:w-[calc(50%-2.5rem)] p-4 rounded-2xl bg-white border border-gray-100 shadow-sm transition-all hover:shadow-md ${isHome ? 'md:ml-auto' : 'md:mr-auto'}`}>
                        <div className="flex items-center space-x-3">
                          <img src={getPlayerPhoto(event.playerId)} className="w-8 h-8 rounded-full border border-gray-100" alt="" />
                          <div>
                            <p className="text-sm font-black text-gray-900">{event.playerName}</p>
                            <div className="flex items-center space-x-1.5">
                              { 'eventType' in event && event.eventType === 'goal' ? (
                                <>
                                  <i className="fas fa-futbol text-[10px] text-blue-500"></i>
                                  <span className="text-[9px] font-black text-blue-500 uppercase tracking-widest">Goal Scored</span>
                                </>
                              ) : (
                                <>
                                  <i className={`fas fa-square text-[10px] text-${(event as CardEvent).type === 'yellow' ? 'yellow' : 'red'}-500`}></i>
                                  <span className={`text-[9px] font-black text-${(event as CardEvent).type === 'yellow' ? 'yellow' : 'red'}-600 uppercase tracking-widest`}>{(event as CardEvent).type} Card</span>
                                </>
                              )}
                            </div>
                          </div>
                        </div>
                      </div>
                    </div>
                  );
                })}

                {timelineEvents.length === 0 && (
                  <div className="text-center py-20 text-gray-400 italic">No significant match events recorded.</div>
                )}
              </div>

              <div className="mt-12 text-center">
                <button 
                  onClick={() => setViewingMatchId(null)}
                  className="bg-white text-gray-900 border border-gray-200 px-8 py-3 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-gray-50 transition-all shadow-sm"
                >
                  Close Match Center
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default MatchScheduler;

import React, { useState, useMemo, useEffect } from 'react';
import { Team, Match, Player, Standing, UserRole, GoalScorer, CardEvent } from './types';
import { INITIAL_TEAMS, INITIAL_MATCHES } from './constants';
import Dashboard from './components/Dashboard';
import TeamRegistration from './components/TeamRegistration';
import StandingsTable from './components/StandingsTable';
import MatchScheduler from './components/MatchScheduler';
import AdminPanel from './components/AdminPanel';
import PlayerManager from './components/PlayerManager';
import Navbar from './components/Navbar';
import Login from './components/Login';

const LeagueAPI = {
  saveTeams: (teams: Team[]) => localStorage.setItem('lp_teams', JSON.stringify(teams)),
  saveMatches: (matches: Match[]) => localStorage.setItem('lp_matches', JSON.stringify(matches)),
  getTeams: (): Team[] | null => {
    const data = localStorage.getItem('lp_teams');
    return data ? JSON.parse(data) : null;
  },
  getMatches: (): Match[] | null => {
    const data = localStorage.getItem('lp_matches');
    return data ? JSON.parse(data) : null;
  }
};

const App: React.FC = () => {
  const [view, setView] = useState<string>('dashboard');
  const [role, setRole] = useState<UserRole>(UserRole.PUBLIC);
  const [teams, setTeams] = useState<Team[]>([]);
  const [matches, setMatches] = useState<Match[]>([]);
  const [selectedTeamId, setSelectedTeamId] = useState<string | null>(null);
  const [isLoaded, setIsLoaded] = useState(false);

  useEffect(() => {
    const storedTeams = LeagueAPI.getTeams();
    const storedMatches = LeagueAPI.getMatches();
    const savedRole = localStorage.getItem('lp_role');
    const savedSelectedTeam = localStorage.getItem('lp_selectedTeam');

    setTeams(storedTeams || INITIAL_TEAMS);
    setMatches(storedMatches || INITIAL_MATCHES);
    if (savedRole) setRole(savedRole as UserRole);
    if (savedSelectedTeam) setSelectedTeamId(savedSelectedTeam);
    setIsLoaded(true);
  }, []);

  useEffect(() => {
    if (isLoaded) {
      LeagueAPI.saveTeams(teams);
      LeagueAPI.saveMatches(matches);
      localStorage.setItem('lp_role', role);
      if (selectedTeamId) localStorage.setItem('lp_selectedTeam', selectedTeamId);
      else localStorage.removeItem('lp_selectedTeam');
    }
  }, [teams, matches, role, selectedTeamId, isLoaded]);

  const standings = useMemo(() => {
    const table: Record<string, Standing> = {};

    teams.forEach(team => {
      table[team.id] = {
        teamId: team.id,
        teamName: team.name,
        played: 0,
        won: 0,
        drawn: 0,
        lost: 0,
        goalsFor: 0,
        goalsAgainst: 0,
        goalDifference: 0,
        points: 0
      };
    });

    matches.filter(m => m.isCompleted).forEach(match => {
      const home = table[match.homeTeamId];
      const away = table[match.awayTeamId];
      if (!home || !away) return;

      const hScore = match.homeScore || 0;
      const aScore = match.awayScore || 0;

      home.played += 1;
      away.played += 1;
      home.goalsFor += hScore;
      home.goalsAgainst += aScore;
      away.goalsFor += aScore;
      away.goalsAgainst += hScore;

      if (hScore > aScore) {
        home.won += 1;
        home.points += 3;
        away.lost += 1;
      } else if (aScore > hScore) {
        away.won += 1;
        away.points += 3;
        home.lost += 1;
      } else {
        home.drawn += 1;
        away.drawn += 1;
        home.points += 1;
        away.points += 1;
      }

      home.goalDifference = home.goalsFor - home.goalsAgainst;
      away.goalDifference = away.goalsFor - away.goalsAgainst;
    });

    return Object.values(table).sort((a, b) => {
      if (b.points !== a.points) return b.points - a.points;
      if (b.goalDifference !== a.goalDifference) return b.goalDifference - a.goalDifference;
      return b.goalsFor - a.goalsFor;
    });
  }, [teams, matches]);

  const addTeam = (team: Omit<Team, 'id' | 'players'>) => {
    const newTeam: Team = { ...team, id: `t${Date.now()}`, players: [] };
    setTeams(prev => [...prev, newTeam]);
    setView('standings');
  };

  const updateTeam = (updatedTeam: Team) => {
    setTeams(prev => prev.map(t => t.id === updatedTeam.id ? updatedTeam : t));
  };

  const updateMatch = (matchId: string, hScore: number, aScore: number, scorers?: GoalScorer[], cards?: CardEvent[]) => {
    setMatches(prevMatches => prevMatches.map(m => m.id === matchId ? { 
      ...m, 
      homeScore: hScore, 
      awayScore: aScore, 
      scorers: scorers || m.scorers,
      cards: cards || m.cards,
      isCompleted: true 
    } : m));

    if (scorers) {
      setTeams(prevTeams => prevTeams.map(team => {
        const updatedPlayers = team.players.map(player => {
          const totalGoals = matches.reduce((acc, match) => {
            const currentScorers = match.id === matchId ? scorers : (match.scorers || []);
            const playerGoals = currentScorers.filter(s => s.playerId === player.id).length;
            return acc + playerGoals;
          }, 0);

          return { ...player, goals: totalGoals };
        });
        return { ...team, players: updatedPlayers };
      }));
    }
  };

  const addMatch = (newMatch: Match) => {
    setMatches(prev => [...prev, newMatch]);
  };

  const updatePlayers = (teamId: string, players: Player[]) => {
    setTeams(prev => prev.map(t => t.id === teamId ? { ...t, players } : t));
  };

  const handleLogin = (newRole: UserRole, teamId?: string) => {
    setRole(newRole);
    if (teamId) setSelectedTeamId(teamId);
    setView('dashboard');
  };

  const handleLogout = () => {
    setRole(UserRole.PUBLIC);
    setSelectedTeamId(null);
    setView('dashboard');
  };

  if (!isLoaded) return <div className="h-screen w-full flex items-center justify-center bg-gray-50 text-blue-600"><i className="fas fa-circle-notch fa-spin text-4xl"></i></div>;

  const renderView = () => {
    switch (view) {
      case 'login':
        return <Login teams={teams} onLogin={handleLogin} onBack={() => setView('dashboard')} />;
      case 'dashboard':
        return <Dashboard teams={teams} matches={matches} standings={standings} setView={setView} />;
      case 'standings':
        return <StandingsTable standings={standings} teams={teams} />;
      case 'registration':
        return <TeamRegistration onRegister={addTeam} existingNames={teams.map(t => t.name)} />;
      case 'schedule':
        return (
          <MatchScheduler 
            matches={matches} 
            teams={teams} 
            isAdmin={role === UserRole.ADMIN} 
            role={role}
            selectedTeamId={selectedTeamId}
            onAddMatch={addMatch} 
            onUpdateMatch={updateMatch} 
          />
        );
      case 'admin':
        return role === UserRole.ADMIN ? (
          <AdminPanel 
            teams={teams} 
            matches={matches} 
            onUpdateMatch={updateMatch} 
            onUpdateTeam={updateTeam}
            onReset={() => { 
              setTeams(INITIAL_TEAMS); 
              setMatches(INITIAL_MATCHES);
              LeagueAPI.saveTeams(INITIAL_TEAMS);
              LeagueAPI.saveMatches(INITIAL_MATCHES);
            }} 
          />
        ) : <Dashboard teams={teams} matches={matches} standings={standings} setView={setView} />;
      case 'players':
        const teamToManage = teams.find(t => t.id === selectedTeamId);
        return teamToManage ? (
          <PlayerManager team={teamToManage} onUpdate={(p) => updatePlayers(teamToManage.id, p)} onBack={() => setView('dashboard')} />
        ) : <div className="p-8 text-center text-gray-500 font-bold">Session expired or unauthorized. Please login again.</div>;
      default:
        return <Dashboard teams={teams} matches={matches} standings={standings} setView={setView} />;
    }
  };

  return (
    <div className="min-h-screen flex flex-col selection:bg-blue-100 selection:text-blue-900">
      <Navbar 
        currentView={view} 
        setView={setView} 
        role={role} 
        onLogout={handleLogout}
        selectedTeamId={selectedTeamId}
        teams={teams}
      />
      <main className="flex-1 container mx-auto px-4 py-8 max-w-6xl">
        {renderView()}
      </main>
      <footer className="bg-white border-t border-gray-100 py-8 text-center">
        <div className="container mx-auto px-4">
          <div className="flex justify-center space-x-6 mb-4 text-gray-400">
            <i className="fab fa-twitter hover:text-blue-400 cursor-pointer transition-colors"></i>
            <i className="fab fa-facebook hover:text-blue-600 cursor-pointer transition-colors"></i>
            <i className="fab fa-instagram hover:text-pink-600 cursor-pointer transition-colors"></i>
          </div>
          <p className="text-gray-400 text-xs font-bold uppercase tracking-widest">
            &copy; 2024 LeaguePro Engine &bull; Digital Sports Management
          </p>
        </div>
      </footer>
    </div>
  );
};

export default App;

