import express from 'express';
import cors from 'cors';
import { open } from 'sqlite';
import sqlite3 from 'sqlite3';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const app = express();
const port = process.env.PORT || 3001;

app.use(cors());
app.use(express.json({ limit: '10mb' }));

let db: any;

async function setupDb() {
  db = await open({
    filename: path.join(__dirname, '../../data/league.db'),
    driver: sqlite3.Database
  });

  await db.exec(`
    CREATE TABLE IF NOT EXISTS users (
      id TEXT PRIMARY KEY,
      username TEXT UNIQUE,
      password TEXT,
      role TEXT,
      teamId TEXT
    );
    CREATE TABLE IF NOT EXISTS teams (
      id TEXT PRIMARY KEY,
      data TEXT
    );
    CREATE TABLE IF NOT EXISTS matches (
      id TEXT PRIMARY KEY,
      data TEXT
    );
  `);

  // Seed default admin if not exists
  const admin = await db.get('SELECT * FROM users WHERE role = ?', ['ADMIN']);
  if (!admin) {
    await db.run(
      'INSERT INTO users (id, username, password, role) VALUES (?, ?, ?, ?)',
      ['u-admin', 'admin', 'admin123', 'ADMIN']
    );
  }
  console.log('Database initialized with Auth support');
}

// Auth Routes
app.post('/api/auth/register', async (req, res) => {
  const { username, password, role, teamId } = req.body;
  try {
    const id = `u-${Date.now()}`;
    await db.run(
      'INSERT INTO users (id, username, password, role, teamId) VALUES (?, ?, ?, ?, ?)',
      [id, username, password, role, teamId]
    );
    res.status(201).json({ id, username, role, teamId });
  } catch (e) {
    res.status(400).json({ error: 'Username already exists' });
  }
});

app.post('/api/auth/login', async (req, res) => {
  const { username, password } = req.body;
  const user = await db.get('SELECT * FROM users WHERE username = ? AND password = ?', [username, password]);
  if (user) {
    res.json({ id: user.id, username: user.username, role: user.role, teamId: user.teamId });
  } else {
    res.status(401).json({ error: 'Invalid credentials' });
  }
});

// Resources Routes
app.get('/api/teams', async (req, res) => {
  const teams = await db.all('SELECT data FROM teams');
  res.json(teams.map((t: any) => JSON.parse(t.data)));
});

app.post('/api/teams', async (req, res) => {
  const team = req.body;
  await db.run('INSERT OR REPLACE INTO teams (id, data) VALUES (?, ?)', [team.id, JSON.stringify(team)]);
  res.status(201).json(team);
});

app.get('/api/matches', async (req, res) => {
  const matches = await db.all('SELECT data FROM matches');
  res.json(matches.map((m: any) => JSON.parse(m.data)));
});

app.post('/api/matches', async (req, res) => {
  const match = req.body;
  await db.run('INSERT OR REPLACE INTO matches (id, data) VALUES (?, ?)', [match.id, JSON.stringify(match)]);
  res.status(201).json(match);
});

app.put('/api/matches/:id', async (req, res) => {
  const match = req.body;
  await db.run('UPDATE matches SET data = ? WHERE id = ?', [JSON.stringify(match), req.params.id]);
  res.json(match);
});

setupDb().then(() => {
  app.listen(port, () => {
    console.log(`Backend running with Auth at http://localhost:${port}`);
  });
});

import React, { useState } from 'react';
import { UserRole, Team } from '../types';

interface LoginProps {
  teams: Team[];
  onLogin: (role: UserRole, teamId?: string) => void;
  onBack: () => void;
}

const API_BASE = 'http://localhost:3001/api';

const Login: React.FC<LoginProps> = ({ teams, onLogin, onBack }) => {
  const [isRegistering, setIsRegistering] = useState(false);
  const [activeTab, setActiveTab] = useState<'manager' | 'admin'>('manager');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [selectedTeamId, setSelectedTeamId] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    try {
      if (isRegistering) {
        if (activeTab === 'admin') throw new Error('Admin registration disabled');
        if (!selectedTeamId) throw new Error('Please select a team');

        const res = await fetch(`${API_BASE}/auth/register`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            username,
            password,
            role: UserRole.TEAM_MANAGER,
            teamId: selectedTeamId
          })
        });

        if (!res.ok) throw new Error('Registration failed. Username might be taken.');
        const user = await res.json();
        onLogin(user.role, user.teamId);
      } else {
        const res = await fetch(`${API_BASE}/auth/login`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ username, password })
        });

        if (!res.ok) throw new Error('Invalid username or password');
        const user = await res.json();
        onLogin(user.role, user.teamId);
      }
    } catch (err: any) {
      setError(err.message);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-[80vh] flex items-center justify-center py-12 px-4 animate-in fade-in zoom-in duration-300">
      <div className="max-w-md w-full space-y-8 bg-white p-10 rounded-[2.5rem] shadow-2xl border border-gray-100">
        <div className="text-center">
          <div className="mx-auto h-16 w-16 bg-blue-600 rounded-2xl flex items-center justify-center shadow-lg shadow-blue-200 mb-4 text-white">
            <i className={`fas ${isRegistering ? 'fa-user-plus' : 'fa-shield-halved'} text-2xl`}></i>
          </div>
          <h2 className="text-3xl font-black text-gray-900 tracking-tight">
            {isRegistering ? 'Join LeaguePro' : 'Secure Access'}
          </h2>
          <p className="mt-2 text-sm text-gray-500 font-medium">
            {isRegistering ? 'Create a manager account' : 'Sign in to manage operations'}
          </p>
        </div>

        {!isRegistering && (
          <div className="flex p-1 bg-gray-100 rounded-xl mb-6">
            <button
              onClick={() => setActiveTab('manager')}
              className={`flex-1 py-2 text-xs font-black uppercase tracking-widest rounded-lg transition-all ${
                activeTab === 'manager' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'
              }`}
            >
              Manager
            </button>
            <button
              onClick={() => setActiveTab('admin')}
              className={`flex-1 py-2 text-xs font-black uppercase tracking-widest rounded-lg transition-all ${
                activeTab === 'admin' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'
              }`}
            >
              Admin
            </button>
          </div>
        )}

        <form className="space-y-5" onSubmit={handleAuth}>
          {error && (
            <div className="p-4 bg-red-50 border border-red-100 rounded-2xl text-red-600 text-xs font-bold flex items-center space-x-2 animate-in shake duration-300">
              <i className="fas fa-exclamation-circle"></i>
              <span>{error}</span>
            </div>
          )}

          <div className="space-y-4">
            <div>
              <label className="block text-[10px] font-black text-gray-400 uppercase mb-2 ml-1">Username</label>
              <input
