import React, { useState, useMemo, useEffect } from 'react';
import { Team, Match, Player, Standing, UserRole, GoalScorer, CardEvent } from './types';
import { INITIAL_TEAMS, INITIAL_MATCHES } from './constants';
import Dashboard from './components/Dashboard';
import TeamRegistration from './components/TeamRegistration';
import StandingsTable from './components/StandingsTable';
import MatchScheduler from './components/MatchScheduler';
import AdminPanel from './components/AdminPanel';
import PlayerManager from './components/PlayerManager';
import Navbar from './components/Navbar';
import Login from './components/Login';
import ErrorBoundary from './components/ErrorBoundary';

// Persistent Storage Utility
const STORAGE_KEYS = {
  TEAMS: 'lp_teams_v2',
  MATCHES: 'lp_matches_v2',
  USERS: 'lp_local_users_v2',
  ROLE: 'lp_role_v2',
  SELECTED_TEAM: 'lp_selectedTeam_v2'
};

const LeagueAPI = {
  // Local-first data access
  loadData: () => {
    const teams = localStorage.getItem(STORAGE_KEYS.TEAMS);
    const matches = localStorage.getItem(STORAGE_KEYS.MATCHES);
    return {
      teams: teams ? JSON.parse(teams) : INITIAL_TEAMS,
      matches: matches ? JSON.parse(matches) : INITIAL_MATCHES
    };
  },

  saveTeams: (teams: Team[]) => {
    localStorage.setItem(STORAGE_KEYS.TEAMS, JSON.stringify(teams));
  },

  saveMatches: (matches: Match[]) => {
    localStorage.setItem(STORAGE_KEYS.MATCHES, JSON.stringify(matches));
  },

  login: async (username: string, password: string): Promise<{role: UserRole, teamId?: string}> => {
    // Standard admin check
    if (username === 'admin' && password === 'admin123') {
      return { role: UserRole.ADMIN };
    }

    // Check local users
    const localUsers = JSON.parse(localStorage.getItem(STORAGE_KEYS.USERS) || '[]');
    const user = localUsers.find((u: any) => u.username === username && u.password === password);

    if (user) return { role: user.role, teamId: user.teamId };

    throw new Error('Invalid username or password');
  }
};

const App: React.FC = () => {
  const [view, setView] = useState<string>('dashboard');
  const [role, setRole] = useState<UserRole>(UserRole.PUBLIC);
  const [teams, setTeams] = useState<Team[]>([]);
  const [matches, setMatches] = useState<Match[]>([]);
  const [selectedTeamId, setSelectedTeamId] = useState<string | null>(null);
  const [isLoaded, setIsLoaded] = useState(false);

  // Initial Load
  useEffect(() => {
    const { teams: savedTeams, matches: savedMatches } = LeagueAPI.loadData();
    const savedRole = localStorage.getItem(STORAGE_KEYS.ROLE);
    const savedSelectedTeam = localStorage.getItem(STORAGE_KEYS.SELECTED_TEAM);

    setTeams(savedTeams);
    setMatches(savedMatches);
    if (savedRole) setRole(savedRole as UserRole);
    if (savedSelectedTeam) setSelectedTeamId(savedSelectedTeam);

    setIsLoaded(true);
  }, []);

  // Auto-Save Effect
  useEffect(() => {
    if (isLoaded) {
      LeagueAPI.saveTeams(teams);
      LeagueAPI.saveMatches(matches);
      localStorage.setItem(STORAGE_KEYS.ROLE, role);
      if (selectedTeamId) localStorage.setItem(STORAGE_KEYS.SELECTED_TEAM, selectedTeamId);
      else localStorage.removeItem(STORAGE_KEYS.SELECTED_TEAM);
    }
  }, [teams, matches, role, selectedTeamId, isLoaded]);

  const standings = useMemo(() => {
    const table: Record<string, Standing> = {};
    teams.forEach(team => {
      table[team.id] = { teamId: team.id, teamName: team.name, played: 0, won: 0, drawn: 0, lost: 0, goalsFor: 0, goalsAgainst: 0, goalDifference: 0, points: 0 };
    });
    matches.filter(m => m.isCompleted).forEach(match => {
      const home = table[match.homeTeamId];
      const away = table[match.awayTeamId];
      if (!home || !away) return;
      const hScore = match.homeScore || 0;
      const aScore = match.awayScore || 0;
      home.played += 1; away.played += 1;
      home.goalsFor += hScore; home.goalsAgainst += aScore;
      away.goalsFor += aScore; away.goalsAgainst += hScore;
      if (hScore > aScore) { home.won += 1; home.points += 3; away.lost += 1; }
      else if (aScore > hScore) { away.won += 1; away.points += 3; home.lost += 1; }
      else { home.drawn += 1; away.drawn += 1; home.points += 1; away.points += 1; }
      home.goalDifference = home.goalsFor - home.goalsAgainst;
      away.goalDifference = away.goalsFor - away.goalsAgainst;
    });
    return Object.values(table).sort((a, b) => b.points !== a.points ? b.points - a.points : b.goalDifference !== a.goalDifference ? b.goalDifference - a.goalDifference : b.goalsFor - a.goalsFor);
  }, [teams, matches]);

  const addTeam = (teamData: Omit<Team, 'id' | 'players'>) => {
    const newTeam: Team = { ...teamData, id: `t${Date.now()}`, players: [] };
    setTeams(prev => [...prev, newTeam]);
    if (role !== UserRole.ADMIN) setView('standings');
  };

  const updateMatch = (matchId: string, hScore: number, aScore: number, scorers?: GoalScorer[], cards?: CardEvent[], refereeName?: string) => {
    const updatedMatches = matches.map(m => m.id === matchId ? { 
      ...m, 
      homeScore: hScore, 
      awayScore: aScore, 
      scorers: scorers || m.scorers, 
      cards: cards || m.cards, 
      refereeName: refereeName !== undefined ? refereeName : m.refereeName,
      isCompleted: true 
    } : m);
    setMatches(updatedMatches);

    // Update player stats if goals were recorded
    if (scorers) {
      setTeams(prevTeams => {
        return prevTeams.map(team => {
          const updatedPlayers = team.players.map(player => {
            const totalGoals = updatedMatches.reduce((acc, m) => acc + (m.scorers || []).filter(s => s.playerId === player.id).length, 0);
            return { ...player, goals: totalGoals };
          });
          return { ...team, players: updatedPlayers };
        });
      });
    }
  };

  const updatePlayers = (teamId: string, players: Player[]) => {
    setTeams(prev => prev.map(t => t.id === teamId ? { ...t, players } : t));
  };

  const importLeagueState = (data: { teams: Team[], matches: Match[], users?: any[] }) => {
    if (data.teams) setTeams(data.teams);
    if (data.matches) setMatches(data.matches);
    if (data.users) localStorage.setItem(STORAGE_KEYS.USERS, JSON.stringify(data.users));
    alert('League data imported successfully!');
  };

  if (!isLoaded) return <div className="h-screen w-full flex items-center justify-center bg-gray-50 text-blue-600"><i className="fas fa-circle-notch fa-spin text-4xl"></i></div>;

  return (
    <div className="min-h-screen flex flex-col selection:bg-blue-100 selection:text-blue-900">
      <Navbar currentView={view} setView={setView} role={role} onLogout={() => { setRole(UserRole.PUBLIC); setSelectedTeamId(null); setView('dashboard'); }} selectedTeamId={selectedTeamId} teams={teams} />
      <main className="flex-1 container mx-auto px-4 py-8 max-width-6xl">
        {(() => {
          switch (view) {
            case 'login': return <ErrorBoundary componentName="Login Module"><Login teams={teams} onLogin={(r, tid) => { setRole(r); if (tid) setSelectedTeamId(tid); setView('dashboard'); }} onBack={() => setView('dashboard')} loginFn={LeagueAPI.login} /></ErrorBoundary>;
            case 'dashboard': return <ErrorBoundary componentName="Dashboard"><Dashboard teams={teams} matches={matches} standings={standings} setView={setView} /></ErrorBoundary>;
            case 'standings': return <ErrorBoundary componentName="Standings Table"><StandingsTable standings={standings} teams={teams} /></ErrorBoundary>;
            case 'registration': return <ErrorBoundary componentName="Team Registration"><TeamRegistration onRegister={addTeam} existingNames={teams.map(t => t.name)} /></ErrorBoundary>;
            case 'schedule': return <ErrorBoundary componentName="Fixture Scheduler"><MatchScheduler matches={matches} teams={teams} isAdmin={role === UserRole.ADMIN} role={role} selectedTeamId={selectedTeamId} onAddMatch={(m) => setMatches([...matches, m])} onUpdateMatch={updateMatch} /></ErrorBoundary>;
            case 'players':
              const teamToManage = teams.find(t => t.id === selectedTeamId);
              return teamToManage ? (
                <ErrorBoundary componentName="Squad Management">
                  <PlayerManager 
                    team={teamToManage} 
                    onUpdate={(p) => updatePlayers(teamToManage.id, p)} 
                    onBack={() => setView(role === UserRole.ADMIN ? 'admin' : 'dashboard')} 
                    isAdminOverride={role === UserRole.ADMIN}
                  />
                </ErrorBoundary>
              ) : null;
            case 'admin':
              return role === UserRole.ADMIN ? (
                <ErrorBoundary componentName="Administrative Control Panel">
                  <AdminPanel 
                    teams={teams} 
                    matches={matches} 
                    onUpdateMatch={updateMatch} 
                    onUpdateTeam={(updated) => setTeams(teams.map(t => t.id === updated.id ? updated : t))}
                    onRegisterTeam={addTeam}
                    onManageSquad={(tid) => { setSelectedTeamId(tid); setView('players'); }}
                    onReset={() => { 
                      if(confirm('This will wipe all local data. Continue?')) {
                        setTeams(INITIAL_TEAMS); 
                        setMatches(INITIAL_MATCHES); 
                        localStorage.removeItem(STORAGE_KEYS.USERS);
                      }
                    }} 
                    onImportState={importLeagueState}
                  />
                </ErrorBoundary>
              ) : null;
            default: return <ErrorBoundary componentName="Dashboard"><Dashboard teams={teams} matches={matches} standings={standings} setView={setView} /></ErrorBoundary>;
          }
        })()}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Team, Match, GoalScorer, UserRole } from '../types';
import TeamRegistration from './TeamRegistration';

interface User {
  id: string;
  username: string;
  role: UserRole;
  teamId?: string;
}

interface AdminPanelProps {
  teams: Team[];
  matches: Match[];
  onUpdateMatch: (id: string, h: number, a: number, scorers?: GoalScorer[], cards?: any[], refereeName?: string) => void;
  onUpdateTeam?: (updatedTeam: Team) => void;
  onRegisterTeam: (team: Omit<Team, 'id' | 'players'>) => void;
  onManageSquad: (teamId: string) => void;
  onReset: () => void;
  onImportState: (data: any) => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ teams, matches, onUpdateMatch, onUpdateTeam, onRegisterTeam, onManageSquad, onReset, onImportState }) => {
  const [editingTeam, setEditingTeam] = useState<Team | null>(null);
  const [showRegisterModal, setShowRegisterModal] = useState(false);
  const [staff, setStaff] = useState<User[]>([]);
  const [showAddStaff, setShowAddStaff] = useState(false);
  const [newStaff, setNewStaff] = useState({ username: '', password: '', role: UserRole.TEAM_MANAGER, teamId: '' });
  const importFileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const localUsers = JSON.parse(localStorage.getItem('lp_local_users_v2') || '[]');
    const allStaff = [
      { id: 'u-admin', username: 'admin', role: UserRole.ADMIN },
      ...localUsers
    ];
    setStaff(allStaff);
  }, []);

  const handleTeamOverride = (updatedData: Omit<Team, 'id' | 'players'>) => {
    if (editingTeam && onUpdateTeam) {
      const fullUpdatedTeam: Team = {
        ...editingTeam,
        ...updatedData
      };
      onUpdateTeam(fullUpdatedTeam);
      setEditingTeam(null);
    }
  };

  const removeStaff = (userId: string) => {
    if (userId === 'u-admin') return alert("Cannot remove the primary system administrator.");
    if (confirm('Are you sure you want to revoke access for this user?')) {
      const localUsers = JSON.parse(localStorage.getItem('lp_local_users_v2') || '[]');
      const updated = localUsers.filter((u: any) => u.username !== userId && u.id !== userId);
      localStorage.setItem('lp_local_users_v2', JSON.stringify(updated));
      setStaff(prev => prev.filter(u => u.id !== userId && u.username !== userId));
    }
  };

  const addStaff = (e: React.FormEvent) => {
    e.preventDefault();
    const id = `u-${Date.now()}`;
    const newUser = { ...newStaff, id };

    const localUsers = JSON.parse(localStorage.getItem('lp_local_users_v2') || '[]');
    localUsers.push(newUser);
    localStorage.setItem('lp_local_users_v2', JSON.stringify(localUsers));

    setStaff(prev => [...prev, newUser]);
    setShowAddStaff(false);
    setNewStaff({ username: '', password: '', role: UserRole.TEAM_MANAGER, teamId: '' });
  };

  const exportLeagueData = () => {
    const backup = {
      timestamp: new Date().toISOString(),
      teams,
      matches,
      users: JSON.parse(localStorage.getItem('lp_local_users_v2') || '[]')
    };
    const blob = new Blob([JSON.stringify(backup, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `leaguepro-backup-${new Date().toISOString().slice(0, 10)}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        try {
          const data = JSON.parse(event.target?.result as string);
          if (confirm('Importing will overwrite current local league data. Continue?')) {
            onImportState(data);
          }
        } catch (err) {
          alert('Invalid backup file format.');
        }
      };
      reader.readAsText(file);
    }
  };

  return (
    <div className="space-y-10 pb-20 animate-in fade-in duration-500">
      {/* Persistence and Backup Suite */}
      <div className="bg-indigo-900 rounded-[2.5rem] p-8 text-white shadow-2xl relative overflow-hidden">
        <div className="relative z-10 flex flex-col md:flex-row justify-between items-center gap-6">
          <div className="flex-1 space-y-2">
            <div className="flex items-center space-x-3">
              <div className="bg-indigo-400/20 p-2 rounded-lg">
                <i className="fas fa-cloud-upload-alt text-xl"></i>
              </div>
              <h3 className="text-xl font-black uppercase tracking-tight">Data Management</h3>
            </div>
            <p className="text-indigo-200 text-sm max-w-lg">
              Your league is stored locally in this browser. Use the tools below to download a permanent backup or migrate your data to another device.
            </p>
          </div>
          <div className="flex flex-wrap gap-3">
            <button 
              onClick={exportLeagueData}
              className="bg-white text-indigo-900 px-6 py-3 rounded-xl font-black text-xs uppercase tracking-widest hover:bg-indigo-50 transition-all flex items-center space-x-2 shadow-lg"
            >
              <i className="fas fa-download"></i>
              <span>Export Backup</span>
            </button>
            <button 
              onClick={() => importFileRef.current?.click()}
              className="bg-indigo-500 text-white px-6 py-3 rounded-xl font-black text-xs uppercase tracking-widest hover:bg-indigo-600 transition-all flex items-center space-x-2 border border-indigo-400"
            >
              <i className="fas fa-upload"></i>
              <span>Import Backup</span>
            </button>
            <input type="file" ref={importFileRef} className="hidden" accept=".json" onChange={handleImport} />
          </div>
        </div>
        <i className="fas fa-database absolute -right-10 -bottom-10 text-[180px] text-white/5 rotate-12"></i>
      </div>

      {/* Critical System Controls */}
      <div className="bg-red-50 border-l-4 border-red-500 p-6 rounded-r-2xl flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div className="flex items-center space-x-4">
          <div className="bg-red-100 p-3 rounded-full">
            <i className="fas fa-exclamation-triangle text-red-600 text-xl"></i>
          </div>
          <div>
            <h3 className="text-lg font-black text-red-900 uppercase tracking-tight">Season Hard Reset</h3>
            <p className="text-red-700 text-sm">Clear all matches and return to the default state.</p>
          </div>
        </div>
        <button 
          onClick={onReset}
          className="bg-white text-red-600 border border-red-200 px-8 py-3 rounded-xl font-black hover:bg-red-600 hover:text-white transition-all shadow-sm text-xs uppercase tracking-widest"
        >
          Factory Reset
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-xl font-black text-gray-900 flex items-center">
              <i className="fas fa-shield-alt mr-3 text-blue-600"></i>
              Active Members ({teams.length})
            </h3>
            <button 
              onClick={() => setShowRegisterModal(true)}
              className="bg-blue-600 text-white px-4 py-2 rounded-xl text-[10px] font-black shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all uppercase tracking-widest"
            >
              Add New Team
