  const [matches, setMatches] = useState<Match[]>([]);
  const [selectedTeamId, setSelectedTeamId] = useState<string | null>(null);
  const [isLoaded, setIsLoaded] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);

  useEffect(() => {
    const boot = async () => {
      // 1. Load Local
      const { teams: localT, matches: localM } = LeagueAPI.loadLocalData();
      setTeams(localT);
      setMatches(localM);

      // Restore Session
      const savedSession = localStorage.getItem(STORAGE_KEYS.SESSION);
      if (savedSession) {
        const session = JSON.parse(savedSession);
        setRole(session.role);
        setSelectedTeamId(session.teamId || null);
      }

      setIsLoaded(true);

      // 2. Hydrate from Cloud
      try {
        setIsSyncing(true);
        const [cloudT, cloudM] = await Promise.all([
          LeagueAPI.fetchTeams(),
          LeagueAPI.fetchMatches()
        ]);
        if (cloudT.length > 0) setTeams(cloudT);
        if (cloudM.length > 0) setMatches(cloudM);
      } catch (e) {
        console.warn('Sync failed: Working in offline mode');
      } finally {
        setIsSyncing(false);
      }
    };
    boot();
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEYS.TEAMS, JSON.stringify(teams));
      localStorage.setItem(STORAGE_KEYS.MATCHES, JSON.stringify(matches));
      // Save Session
      if (role !== UserRole.PUBLIC) {
        localStorage.setItem(STORAGE_KEYS.SESSION, JSON.stringify({ role, teamId: selectedTeamId }));
      } else {
        localStorage.removeItem(STORAGE_KEYS.SESSION);
      }
    }
  }, [teams, matches, role, selectedTeamId, isLoaded]);

  const standings = useMemo(() => {
    const table: Record<string, Standing> = {};
    teams.forEach(team => {
      table[team.id] = { teamId: team.id, teamName: team.name, played: 0, won: 0, drawn: 0, lost: 0, goalsFor: 0, goalsAgainst: 0, goalDifference: 0, points: 0 };
    });
    matches.filter(m => m.isCompleted).forEach(match => {
      const home = table[match.homeTeamId];
      const away = table[match.awayTeamId];
      if (!home || !away) return;
      const hScore = match.homeScore || 0;
      const aScore = match.awayScore || 0;
      home.played += 1; away.played += 1;
      home.goalsFor += hScore; home.goalsAgainst += aScore;
      away.goalsFor += aScore; away.goalsAgainst += hScore;
      if (hScore > aScore) { home.won += 1; home.points += 3; away.lost += 1; }
      else if (aScore > hScore) { away.won += 1; away.points += 3; home.lost += 1; }
      else { home.drawn += 1; away.drawn += 1; home.points += 1; away.points += 1; }
      home.goalDifference = home.goalsFor - home.goalsAgainst;
      away.goalDifference = away.goalsFor - away.goalsAgainst;
    });
    return Object.values(table).sort((a, b) => b.points !== a.points ? b.points - a.points : b.goalDifference !== a.goalDifference ? b.goalDifference - a.goalDifference : b.goalsFor - a.goalsFor);
  }, [teams, matches]);

  const addTeam = async (teamData: Omit<Team, 'id' | 'players'>) => {
    const newTeam: Team = { ...teamData, id: `t${Date.now()}`, players: [] };
    const updated = [...teams, newTeam];
    setTeams(updated);
    try {
      await LeagueAPI.saveTeam(newTeam);
    } catch (e) { console.warn('Saved locally, cloud sync pending'); }
    if (role !== UserRole.ADMIN) setView('standings');
  };

  const updateMatch = async (matchId: string, hScore: number, aScore: number, scorers?: GoalScorer[], cards?: CardEvent[], refereeName?: string) => {
    const updatedMatches = matches.map(m => m.id === matchId ? { 
      ...m, 
      homeScore: hScore, 
      awayScore: aScore, 
      scorers: scorers || m.scorers, 
      cards: cards || m.cards, 
      refereeName: refereeName !== undefined ? refereeName : m.refereeName,
      isCompleted: true 
    } : m);
    setMatches(updatedMatches);

    const match = updatedMatches.find(m => m.id === matchId);
    if (match) {
      try {
        await LeagueAPI.saveMatch(match);
      } catch (e) { console.warn('Saved locally, cloud sync pending'); }
    }

    if (scorers) {
      setTeams(prevTeams => {
        const newTeams = prevTeams.map(team => {
          const updatedPlayers = team.players.map(player => {
            const totalGoals = updatedMatches.reduce((acc, m) => acc + (m.scorers || []).filter(s => s.playerId === player.id).length, 0);
            return { ...player, goals: totalGoals };
          });
          return { ...team, players: updatedPlayers };
        });
        newTeams.forEach(t => LeagueAPI.saveTeam(t).catch(() => {}));
        return newTeams;
      });
    }
  };

  const updatePlayers = async (teamId: string, players: Player[]) => {
    const updatedTeams = teams.map(t => t.id === teamId ? { ...t, players } : t);
    setTeams(updatedTeams);
    const team = updatedTeams.find(t => t.id === teamId);
    if (team) {
      try {
        await LeagueAPI.saveTeam(team);
      } catch (e) { console.warn('Saved locally, cloud sync pending'); }
    }
  };

  const importLeagueState = (data: { teams: Team[], matches: Match[], users?: any[] }) => {
    if (data.teams) setTeams(data.teams);
    if (data.matches) setMatches(data.matches);
    alert('League data imported successfully!');
  };

  if (!isLoaded) return <div className="h-screen w-full flex items-center justify-center bg-gray-50 text-blue-600"><i className="fas fa-circle-notch fa-spin text-4xl"></i></div>;

  return (
    <div className="min-h-screen flex flex-col selection:bg-blue-100 selection:text-blue-900">
      <Navbar currentView={view} setView={setView} role={role} onLogout={() => { setRole(UserRole.PUBLIC); setSelectedTeamId(null); localStorage.removeItem(STORAGE_KEYS.SESSION); setView('dashboard'); }} selectedTeamId={selectedTeamId} teams={teams} isSyncing={isSyncing} />
      <main className="flex-1 container mx-auto px-4 py-8 max-width-6xl">
        {(() => {
          switch (view) {
            case 'login': return <ErrorBoundary componentName="Login Module"><Login teams={teams} onLogin={(r, tid) => { setRole(r); if (tid) setSelectedTeamId(tid); setView('dashboard'); }} onBack={() => setView('dashboard')} loginFn={LeagueAPI.login} /></ErrorBoundary>;
            case 'dashboard': return <ErrorBoundary componentName="Dashboard"><Dashboard teams={teams} matches={matches} standings={standings} setView={setView} /></ErrorBoundary>;
            case 'standings': return <ErrorBoundary componentName="Standings Table"><StandingsTable standings={standings} teams={teams} /></ErrorBoundary>;
            case 'registration': return <ErrorBoundary componentName="Team Registration"><TeamRegistration onRegister={addTeam} existingNames={teams.map(t => t.name)} /></ErrorBoundary>;
            case 'schedule': return <ErrorBoundary componentName="Fixture Scheduler"><MatchScheduler matches={matches} teams={teams} isAdmin={role === UserRole.ADMIN} role={role} selectedTeamId={selectedTeamId} onAddMatch={(m) => setMatches([...matches, m])} onUpdateMatch={updateMatch} /></ErrorBoundary>;
            case 'players':
              const teamToManage = teams.find(t => t.id === selectedTeamId);
              return teamToManage ? (
                <ErrorBoundary componentName="Squad Management">
                  <PlayerManager 
                    team={teamToManage} 
                    onUpdate={(p) => updatePlayers(teamToManage.id, p)} 
                    onBack={() => setView(role === UserRole.ADMIN ? 'admin' : 'dashboard')} 
                    isAdminOverride={role === UserRole.ADMIN}
                  />
                </ErrorBoundary>
              ) : null;
            case 'admin':
              return role === UserRole.ADMIN ? (
                <ErrorBoundary componentName="Administrative Control Panel">
                  <AdminPanel 
                    teams={teams} 
                    matches={matches} 
                    onUpdateMatch={updateMatch} 
                    onUpdateTeam={(updated) => {
                      const updatedTeams = teams.map(t => t.id === updated.id ? updated : t);
                      setTeams(updatedTeams);
                      LeagueAPI.saveTeam(updated).catch(() => {});
                    }}
                    onRegisterTeam={addTeam}
                    onManageSquad={(tid) => { setSelectedTeamId(tid); setView('players'); }}
                    onReset={() => { 
                      if(confirm('This will wipe all local data. Continue?')) {
                        setTeams(INITIAL_TEAMS); 
                        setMatches(INITIAL_MATCHES); 
                      }
                    }} 
                    onImportState={importLeagueState}
                  />
                </ErrorBoundary>
              ) : null;
            default: return <ErrorBoundary componentName="Dashboard"><Dashboard teams={teams} matches={matches} standings={standings} setView={setView} /></ErrorBoundary>;
          }
        })()}
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { UserRole, Team } from '../types';

interface LoginProps {
  teams: Team[];
  onLogin: (role: UserRole, teamId?: string) => void;
  onBack: () => void;
  loginFn: (u: string, p: string) => Promise<{role: UserRole, teamId?: string}>;
}

const API_BASE = '/api';

const Login: React.FC<LoginProps> = ({ teams, onLogin, onBack, loginFn }) => {
  const [isRegistering, setIsRegistering] = useState(false);
  const [activeTab, setActiveTab] = useState<'manager' | 'admin'>('manager');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [selectedTeamId, setSelectedTeamId] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    try {
      if (isRegistering) {
        if (activeTab === 'admin') throw new Error('Admin registration disabled');
        if (!selectedTeamId) throw new Error('Please select a team');

        const res = await fetch(`${API_BASE}/auth/register`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            username,
            password,
            role: UserRole.TEAM_MANAGER,
            teamId: selectedTeamId
          })
        });

        if (!res.ok) {
           // Local backup for demo/offline resilience
           const localUsers = JSON.parse(localStorage.getItem('lp_local_users_v2') || '[]');
           if (localUsers.some((u: any) => u.username === username)) throw new Error('Username taken');

           const newUser = { username, password, role: UserRole.TEAM_MANAGER, teamId: selectedTeamId };
           localUsers.push(newUser);
           localStorage.setItem('lp_local_users_v2', JSON.stringify(localUsers));
           onLogin(UserRole.TEAM_MANAGER, selectedTeamId);
           return;
        }
        const user = await res.json();
        onLogin(user.role, user.teamId);
      } else {
        const user = await loginFn(username, password);
        onLogin(user.role, user.teamId);
      }
    } catch (err: any) {
      setError(err.name === 'AbortError' ? 'Server timed out. Trying local access...' : err.message);

      // If it timed out, try one final check for local users right here for instant UX
      if (err.name === 'AbortError') {
        const localUsers = JSON.parse(localStorage.getItem('lp_local_users_v2') || '[]');
        const user = localUsers.find((u: any) => u.username === username && u.password === password);
        if (user) {
          onLogin(user.role, user.teamId);
        } else if (username === 'admin' && password === 'admin123') {
          onLogin(UserRole.ADMIN);
        }
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-[80vh] flex items-center justify-center py-12 px-4 animate-in fade-in zoom-in duration-300">
      <div className="max-w-md w-full space-y-8 bg-white p-10 rounded-[2.5rem] shadow-2xl border border-gray-100">
        <div className="text-center">
          <div className="mx-auto h-16 w-16 bg-blue-600 rounded-2xl flex items-center justify-center shadow-lg shadow-blue-200 mb-4 text-white">
            <i className={`fas ${isRegistering ? 'fa-user-plus' : 'fa-shield-halved'} text-2xl`}></i>
          </div>
          <h2 className="text-3xl font-black text-gray-900 tracking-tight">
            {isRegistering ? 'Join LeaguePro' : 'Secure Access'}
          </h2>
          <p className="mt-2 text-sm text-gray-500 font-medium">
            {isRegistering ? 'Create a manager account' : 'Sign in to manage operations'}
          </p>
        </div>

        {!isRegistering && (
          <div className="flex p-1 bg-gray-100 rounded-xl mb-6">
            <button
              onClick={() => setActiveTab('manager')}
              className={`flex-1 py-2 text-xs font-black uppercase tracking-widest rounded-lg transition-all ${
                activeTab === 'manager' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'
              }`}
            >
              Manager
            </button>
            <button
              onClick={() => setActiveTab('admin')}
              className={`flex-1 py-2 text-xs font-black uppercase tracking-widest rounded-lg transition-all ${
                activeTab === 'admin' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'
              }`}
            >
              Admin
            </button>
          </div>
        )}

        <form className="space-y-5" onSubmit={handleAuth}>
          {error && (
            <div className="p-4 bg-red-50 border border-red-100 rounded-2xl text-red-600 text-xs font-bold flex items-center space-x-2 animate-in shake duration-300">
              <i className="fas fa-exclamation-circle"></i>
              <span>{error}</span>
            </div>
          )}

          <div className="space-y-4">
            <div>
              <label className="block text-[10px] font-black text-gray-400 uppercase mb-2 ml-1">Username</label>
              <input
                type="text"
                required
                className="w-full rounded-2xl px-5 py-4 border border-gray-200 bg-gray-50 focus:ring-4 focus:ring-blue-50 focus:border-blue-500 outline-none transition-all font-bold"
                placeholder="Enter username"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
              />
            </div>

            <div>
              <label className="block text-[10px] font-black text-gray-400 uppercase mb-2 ml-1">Password</label>
              <input
                type="password"
                required
                className="w-full rounded-2xl px-5 py-4 border border-gray-200 bg-gray-50 focus:ring-4 focus:ring-blue-50 focus:border-blue-500 outline-none transition-all font-bold"
                placeholder="••••••••"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
              />
            </div>

            {isRegistering && (
              <div className="animate-in slide-in-from-top-2">
                <label className="block text-[10px] font-black text-gray-400 uppercase mb-2 ml-1">Affiliated Team</label>
                <select
                  required
                  className="w-full rounded-2xl px-5 py-4 border border-gray-200 bg-gray-50 focus:ring-4 focus:ring-blue-50 outline-none font-bold bg-white"
                  value={selectedTeamId}
                  onChange={(e) => setSelectedTeamId(e.target.value)}
                >
                  <option value="">Select Team</option>
                  {teams.map((t) => (
                    <option key={t.id} value={t.id}>{t.name}</option>
                  ))}
                </select>
              </div>
            )}
          </div>

          <button
            type="submit"
            disabled={isLoading}
            className="w-full flex justify-center py-5 px-4 border border-transparent text-sm font-black rounded-2xl text-white bg-blue-600 hover:bg-blue-700 transition-all shadow-xl shadow-blue-100 disabled:opacity-50"
          >
            {isLoading ? (
              <i className="fas fa-circle-notch fa-spin text-xl"></i>
            ) : (
              <span className="tracking-widest">{isRegistering ? 'CREATE ACCOUNT' : 'AUTHENTICATE'}</span>
            )}
          </button>

          <div className="flex flex-col space-y-3 pt-2 text-center">
            {!isRegistering && activeTab === 'manager' && (
              <button
                type="button"
                onClick={() => setIsRegistering(true)}
                className="text-[10px] font-black text-blue-600 hover:text-blue-800 uppercase tracking-widest"
              >
                No account? Register as Manager
              </button>
            )}
            {isRegistering && (
              <button
                type="button"
                onClick={() => setIsRegistering(false)}
                className="text-[10px] font-black text-blue-600 hover:text-blue-800 uppercase tracking-widest"
              >
                Already registered? Login
              </button>
            )}
            <button
              type="button"
              onClick={onBack}
              className="text-[10px] font-black text-gray-400 hover:text-gray-600 uppercase tracking-widest"
            >
              Back to Dashboard
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default Login;

import React, { ErrorInfo, ReactNode } from 'react';

interface Props {
  // Making children optional avoids "missing children" errors in some JSX compilers
  // even when children are provided between component tags in the parent.
  children?: ReactNode;
  componentName?: string;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

/**
 * Standard React Error Boundary component.
 * We extend React.Component explicitly to ensure this.props, this.state, and this.setState 
 * are correctly identified by the TypeScript compiler.
 */
// Fixed: Using fully qualified React.Component to ensure inheritance properties are recognized
class ErrorBoundary extends React.Component<Props, State> {
  constructor(props: Props) {
    super(props);
    // Fixed: Correctly initializing the instance state
    this.state = {
      hasError: false,
      error: null
    };
  }

  public static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    // Fixed: Accessing props via the instance context
    console.error(`Uncaught error in ${this.props.componentName || 'Component'}:`, error, errorInfo);
  }

  public render() {
    // Fixed: Correctly accessing the instance state
    if (this.state.hasError) {
      return (
        <div className="p-8 bg-white border-2 border-dashed border-red-100 rounded-[2.5rem] text-center space-y-4 my-4 animate-in fade-in zoom-in-95">
          <div className="w-16 h-16 bg-red-50 text-red-500 rounded-2xl flex items-center justify-center mx-auto shadow-sm">
            <i className="fas fa-microchip-slash text-2xl"></i>
          </div>
          <div className="space-y-1">
            <h3 className="text-xl font-black text-gray-900 tracking-tight">Component Encountered an Issue</h3>
            <p className="text-sm text-gray-500 font-medium">
              Something went wrong while rendering <span className="text-blue-600 font-bold">{this.props.componentName || 'this section'}</span>.
            </p>
          </div>
          <div className="pt-2 flex justify-center space-x-3">
            <button
              // Fixed: Using the inherited setState method
              onClick={() => this.setState({ hasError: false, error: null })}
              className="bg-blue-600 text-white px-6 py-2.5 rounded-xl font-bold text-xs hover:bg-blue-700 transition-all shadow-lg shadow-blue-100 flex items-center space-x-2"
            >
              <i className="fas fa-redo-alt"></i>
              <span>Attempt Recovery</span>
            </button>
            <button
              onClick={() => window.location.reload()}
              className="bg-gray-100 text-gray-600 px-6 py-2.5 rounded-xl font-bold text-xs hover:bg-gray-200 transition-all flex items-center space-x-2"
            >
              <i className="fas fa-sync"></i>
              <span>Full Reload</span>
            </button>
          </div>
          {/* Fixed: Accessing instance state for the error object */}
          {this.state.error && (
            <details className="mt-4 text-left group">
              <summary className="text-[10px] font-black text-gray-300 uppercase cursor-pointer hover:text-gray-400 text-center tracking-widest list-none">
                Technical Details <i className="fas fa-chevron-down ml-1 group-open:rotate-180 transition-transform"></i>
              </summary>
              <div className="mt-4 p-4 bg-gray-900 rounded-2xl overflow-x-auto">
                <code className="text-[10px] font-mono text-red-400 break-all leading-relaxed">
                  {/* Fixed: Accessing error property from state */}
                  {this.state.error.toString()}
                </code>
              </div>
            </details>
          )}
        </div>
      );
    }

    // Fixed: Return children from the instance props to support the Error Boundary wrapper pattern
    return this.props.children;
  }
}

export default ErrorBoundary;

import React, { useState, useMemo, useEffect } from 'react';
import { Team, Match, Player, Standing, UserRole, GoalScorer, CardEvent } from './types';
import { INITIAL_TEAMS, INITIAL_MATCHES } from './constants';
import Dashboard from './components/Dashboard';
import TeamRegistration from './components/TeamRegistration';
import StandingsTable from './components/StandingsTable';
import MatchScheduler from './components/MatchScheduler';
import AdminPanel from './components/AdminPanel';
import PlayerManager from './components/PlayerManager';
import Navbar from './components/Navbar';
import Login from './components/Login';
import ErrorBoundary from './components/ErrorBoundary';

const API_BASE = '/api';

const STORAGE_KEYS = {
  TEAMS: 'lp_teams_v2',
  MATCHES: 'lp_matches_v2',
  USERS: 'lp_local_users_v2',
  ROLE: 'lp_role_v2',
  SELECTED_TEAM: 'lp_selectedTeam_v2',
  SESSION: 'lp_session_v2'
};

const LeagueAPI = {
  loadLocalData: () => {
    const teams = localStorage.getItem(STORAGE_KEYS.TEAMS);
    const matches = localStorage.getItem(STORAGE_KEYS.MATCHES);
    return {
      teams: teams ? JSON.parse(teams) : INITIAL_TEAMS,
      matches: matches ? JSON.parse(matches) : INITIAL_MATCHES
    };
  },

  fetchTeams: async (): Promise<Team[]> => {
    const res = await fetch(`${API_BASE}/teams`);
    if (!res.ok) throw new Error('API Error');
    return res.json();
  },

  fetchMatches: async (): Promise<Match[]> => {
    const res = await fetch(`${API_BASE}/matches`);
    if (!res.ok) throw new Error('API Error');
    return res.json();
  },

  saveTeam: async (team: Team) => {
    await fetch(`${API_BASE}/teams`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(team)
    });
  },

  saveMatch: async (match: Match) => {
    await fetch(`${API_BASE}/matches`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(match)
    });
  },

  login: async (username: string, password: string): Promise<{role: UserRole, teamId?: string}> => {
    // 1. Instant Admin Override (No network wait)
    if (username === 'admin' && password === 'admin123') {
      return { role: UserRole.ADMIN };
    }

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 5000);

    try {
      const res = await fetch(`${API_BASE}/auth/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username, password }),
        signal: controller.signal
      });
      clearTimeout(timeoutId);

      if (res.ok) return res.json();
      throw new Error('Cloud auth failed');
    } catch (err) {
      console.warn('Remote auth failed, checking local storage fallback...');

      // Local Manager Fallback
      const localUsers = JSON.parse(localStorage.getItem(STORAGE_KEYS.USERS) || '[]');
      const user = localUsers.find((u: any) => u.username === username && u.password === password);
      if (user) return { role: user.role, teamId: user.teamId };

      throw new Error('Invalid credentials or authentication server unreachable.');
    }
  }
};

const App: React.FC = () => {
  const [view, setView] = useState<string>('dashboard');
  const [role, setRole] = useState<UserRole>(UserRole.PUBLIC);
  const [teams, setTeams] = useState<Team[]>([]);
  const [matches, setMatches] = useState<Match[]>([]);
  const [selectedTeamId, setSelectedTeamId] = useState<string | null>(null);
  const [isLoaded, setIsLoaded] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);

  useEffect(() => {
    const boot = async () => {
      const { teams: localT, matches: localM } = LeagueAPI.loadLocalData();
      setTeams(localT);
      setMatches(localM);

      const savedSession = localStorage.getItem(STORAGE_KEYS.SESSION);
      if (savedSession) {
        const session = JSON.parse(savedSession);
        setRole(session.role);
        setSelectedTeamId(session.teamId || null);
      }

      setIsLoaded(true);

      try {
        setIsSyncing(true);
        const [cloudT, cloudM] = await Promise.all([
          LeagueAPI.fetchTeams(),
          LeagueAPI.fetchMatches()
        ]);
        if (cloudT.length > 0) setTeams(cloudT);
        if (cloudM.length > 0) setMatches(cloudM);
      } catch (e) {
        console.warn('Cloud sync unavailable');
      } finally {
        setIsSyncing(false);
      }
    };
    boot();
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEYS.TEAMS, JSON.stringify(teams));
      localStorage.setItem(STORAGE_KEYS.MATCHES, JSON.stringify(matches));
      if (role !== UserRole.PUBLIC) {
        localStorage.setItem(STORAGE_KEYS.SESSION, JSON.stringify({ role, teamId: selectedTeamId }));
      } else {
        localStorage.removeItem(STORAGE_KEYS.SESSION);
      }
    }
  }, [teams, matches, role, selectedTeamId, isLoaded]);

  const standings = useMemo(() => {
    const table: Record<string, Standing> = {};
    teams.forEach(team => {
      table[team.id] = { teamId: team.id, teamName: team.name, played: 0, won: 0, drawn: 0, lost: 0, goalsFor: 0, goalsAgainst: 0, goalDifference: 0, points: 0 };
    });
    matches.filter(m => m.isCompleted).forEach(match => {
      const home = table[match.homeTeamId];
      const away = table[match.awayTeamId];
      if (!home || !away) return;
      const hScore = match.homeScore || 0;
      const aScore = match.awayScore || 0;
      home.played += 1; away.played += 1;
      home.goalsFor += hScore; home.goalsAgainst += aScore;
      away.goalsFor += aScore; away.goalsAgainst += hScore;
      if (hScore > aScore) { home.won += 1; home.points += 3; away.lost += 1; }
      else if (aScore > hScore) { away.won += 1; away.points += 3; home.lost += 1; }
      else { home.drawn += 1; away.drawn += 1; home.points += 1; away.points += 1; }
      home.goalDifference = home.goalsFor - home.goalsAgainst;
      away.goalDifference = away.goalsFor - away.goalsAgainst;
    });
    return Object.values(table).sort((a, b) => b.points !== a.points ? b.points - a.points : b.goalDifference !== a.goalDifference ? b.goalDifference - a.goalDifference : b.goalsFor - a.goalsFor);
  }, [teams, matches]);

  const addTeam = async (teamData: Omit<Team, 'id' | 'players'>) => {
    const newTeam: Team = { ...teamData, id: `t${Date.now()}`, players: [] };
    const updated = [...teams, newTeam];
    setTeams(updated);
    try {
      await LeagueAPI.saveTeam(newTeam);
    } catch (e) { console.warn('Saved locally'); }
    if (role !== UserRole.ADMIN) setView('standings');
  };

  const updateMatch = async (matchId: string, hScore: number, aScore: number, scorers?: GoalScorer[], cards?: CardEvent[], refereeName?: string) => {
    const updatedMatches = matches.map(m => m.id === matchId ? { 
      ...m, 
      homeScore: hScore, 
      awayScore: aScore, 
      scorers: scorers || m.scorers, 
      cards: cards || m.cards, 
      refereeName: refereeName !== undefined ? refereeName : m.refereeName,
      isCompleted: true 
    } : m);
    setMatches(updatedMatches);

    const match = updatedMatches.find(m => m.id === matchId);
    if (match) {
      try {
        await LeagueAPI.saveMatch(match);
      } catch (e) { console.warn('Saved locally'); }
    }

    if (scorers) {
      setTeams(prevTeams => {
        const newTeams = prevTeams.map(team => {
          const updatedPlayers = team.players.map(player => {
            const totalGoals = updatedMatches.reduce((acc, m) => acc + (m.scorers || []).filter(s => s.playerId === player.id).length, 0);
            return { ...player, goals: totalGoals };
          });
          return { ...team, players: updatedPlayers };
        });
        newTeams.forEach(t => LeagueAPI.saveTeam(t).catch(() => {}));
        return newTeams;
      });
    }
  };

  const updatePlayers = async (teamId: string, players: Player[]) => {
    const updatedTeams = teams.map(t => t.id === teamId ? { ...t, players } : t);
    setTeams(updatedTeams);
    const team = updatedTeams.find(t => t.id === teamId);
    if (team) {
      try {
        await LeagueAPI.saveTeam(team);
      } catch (e) { console.warn('Saved locally'); }
    }
  };

  const importLeagueState = (data: { teams: Team[], matches: Match[], users?: any[] }) => {
    if (data.teams) setTeams(data.teams);
    if (data.matches) setMatches(data.matches);
    alert('League data imported successfully!');
  };

  const handleLogin = (r: UserRole, tid?: string) => {
    setRole(r);
    // Explicitly set tid to null if not provided (important for admin override)
    setSelectedTeamId(tid || null);
    setView('dashboard');
  };

  if (!isLoaded) return <div className="h-screen w-full flex items-center justify-center bg-gray-50 text-blue-600"><i className="fas fa-circle-notch fa-spin text-4xl"></i></div>;

  return (
    <div className="min-h-screen flex flex-col selection:bg-blue-100 selection:text-blue-900">
      <Navbar currentView={view} setView={setView} role={role} onLogout={() => { setRole(UserRole.PUBLIC); setSelectedTeamId(null); localStorage.removeItem(STORAGE_KEYS.SESSION); setView('dashboard'); }} selectedTeamId={selectedTeamId} teams={teams} isSyncing={isSyncing} />
      <main className="flex-1 container mx-auto px-4 py-8 max-width-6xl">
        {(() => {
          switch (view) {
            case 'login': return <ErrorBoundary componentName="Login Module"><Login teams={teams} onLogin={handleLogin} onBack={() => setView('dashboard')} loginFn={LeagueAPI.login} /></ErrorBoundary>;
            case 'dashboard': return <ErrorBoundary componentName="Dashboard"><Dashboard teams={teams} matches={matches} standings={standings} setView={setView} /></ErrorBoundary>;
            case 'standings': return <ErrorBoundary componentName="Standings Table"><StandingsTable standings={standings} teams={teams} /></ErrorBoundary>;
            case 'registration': return <ErrorBoundary componentName="Team Registration"><TeamRegistration onRegister={addTeam} existingNames={teams.map(t => t.name)} /></ErrorBoundary>;
            case 'schedule': return <ErrorBoundary componentName="Fixture Scheduler"><MatchScheduler matches={matches} teams={teams} isAdmin={role === UserRole.ADMIN} role={role} selectedTeamId={selectedTeamId} onAddMatch={(m) => setMatches([...matches, m])} onUpdateMatch={updateMatch} /></ErrorBoundary>;
            case 'players':
              const teamToManage = teams.find(t => t.id === selectedTeamId);
              return teamToManage ? (
                <ErrorBoundary componentName="Squad Management">
                  <PlayerManager 
                    team={teamToManage} 
                    onUpdate={(p) => updatePlayers(teamToManage.id, p)} 
                    onBack={() => setView(role === UserRole.ADMIN ? 'admin' : 'dashboard')} 
                    isAdminOverride={role === UserRole.ADMIN}
                  />
                </ErrorBoundary>
              ) : null;
            case 'admin':
              return role === UserRole.ADMIN ? (
                <ErrorBoundary componentName="Administrative Control Panel">
                  <AdminPanel 
                    teams={teams} 
                    matches={matches} 
                    onUpdateMatch={updateMatch} 
                    onUpdateTeam={(updated) => {
                      const updatedTeams = teams.map(t => t.id === updated.id ? updated : t);
                      setTeams(updatedTeams);
                      LeagueAPI.saveTeam(updated).catch(() => {});
                    }}
                    onRegisterTeam={addTeam}
                    onManageSquad={(tid) => { setSelectedTeamId(tid); setView('players'); }}
                    onReset={() => { 
                      if(confirm('This will wipe all local data. Continue?')) {
                        setTeams(INITIAL_TEAMS); 
                        setMatches(INITIAL_MATCHES); 
                      }
                    }} 
                    onImportState={importLeagueState}
                  />
                </ErrorBoundary>
              ) : null;
            default: return <ErrorBoundary componentName="Dashboard"><Dashboard teams={teams} matches={matches} standings={standings} setView={setView} /></ErrorBoundary>;
          }
        })()}
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { UserRole, Team } from '../types';

interface LoginProps {
  teams: Team[];
  onLogin: (role: UserRole, teamId?: string) => void;
  onBack: () => void;
  loginFn: (u: string, p: string) => Promise<{role: UserRole, teamId?: string}>;
}

const API_BASE = '/api';

const Login: React.FC<LoginProps> = ({ teams, onLogin, onBack, loginFn }) => {
  const [isRegistering, setIsRegistering] = useState(false);
  const [activeTab, setActiveTab] = useState<'manager' | 'admin'>('manager');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [selectedTeamId, setSelectedTeamId] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    try {
      if (isRegistering) {
        if (activeTab === 'admin') throw new Error('Admin registration disabled');
        if (!selectedTeamId) throw new Error('Please select a team');

        const res = await fetch(`${API_BASE}/auth/register`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            username,
            password,
            role: UserRole.TEAM_MANAGER,
            teamId: selectedTeamId
          })
        });

        if (!res.ok) {
           // Local backup for offline resilience
           const localUsers = JSON.parse(localStorage.getItem('lp_local_users_v2') || '[]');
           if (localUsers.some((u: any) => u.username === username)) throw new Error('Username taken');

           const newUser = { username, password, role: UserRole.TEAM_MANAGER, teamId: selectedTeamId };
           localUsers.push(newUser);
           localStorage.setItem('lp_local_users_v2', JSON.stringify(localUsers));
           onLogin(UserRole.TEAM_MANAGER, selectedTeamId);
           return;
        }
        const user = await res.json();
        onLogin(user.role, user.teamId);
      } else {
        const user = await loginFn(username, password);
        onLogin(user.role, user.teamId);
      }
    } catch (err: any) {
      setError(err.message || 'Authentication failed. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-[80vh] flex items-center justify-center py-12 px-4 animate-in fade-in zoom-in duration-300">
      <div className="max-w-md w-full space-y-8 bg-white p-10 rounded-[2.5rem] shadow-2xl border border-gray-100">
        <div className="text-center">
          <div className="mx-auto h-16 w-16 bg-blue-600 rounded-2xl flex items-center justify-center shadow-lg shadow-blue-200 mb-4 text-white">
            <i className={`fas ${isRegistering ? 'fa-user-plus' : 'fa-shield-halved'} text-2xl`}></i>
          </div>
          <h2 className="text-3xl font-black text-gray-900 tracking-tight">
            {isRegistering ? 'Join LeaguePro' : 'Secure Access'}
          </h2>
          <p className="mt-2 text-sm text-gray-500 font-medium">
            {isRegistering ? 'Create a manager account' : 'Sign in to manage operations'}
          </p>
        </div>

        {!isRegistering && (
          <div className="flex p-1 bg-gray-100 rounded-xl mb-6">
            <button
              onClick={() => setActiveTab('manager')}
              className={`flex-1 py-2 text-xs font-black uppercase tracking-widest rounded-lg transition-all ${
                activeTab === 'manager' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'
              }`}
            >
              Manager
            </button>
            <button
              onClick={() => setActiveTab('admin')}
              className={`flex-1 py-2 text-xs font-black uppercase tracking-widest rounded-lg transition-all ${
                activeTab === 'admin' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'
              }`}
            >
              Admin
            </button>
          </div>
        )}

        <form className="space-y-5" onSubmit={handleAuth}>
          {error && (
            <div className="p-4 bg-red-50 border border-red-100 rounded-2xl text-red-600 text-xs font-bold flex items-center space-x-2 animate-in shake duration-300">
              <i className="fas fa-exclamation-circle"></i>
              <span>{error}</span>
            </div>
          )}

          <div className="space-y-4">
            <div>
              <label className="block text-[10px] font-black text-gray-400 uppercase mb-2 ml-1">Username</label>
              <input
                type="text"
                required
                className="w-full rounded-2xl px-5 py-4 border border-gray-200 bg-gray-50 focus:ring-4 focus:ring-blue-50 focus:border-blue-500 outline-none transition-all font-bold"
                placeholder="Enter username"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
              />
            </div>

            <div>
              <label className="block text-[10px] font-black text-gray-400 uppercase mb-2 ml-1">Password</label>
              <input
                type="password"
                required
                className="w-full rounded-2xl px-5 py-4 border border-gray-200 bg-gray-50 focus:ring-4 focus:ring-blue-50 focus:border-blue-500 outline-none transition-all font-bold"
                placeholder="••••••••"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
              />
            </div>

            {isRegistering && (
              <div className="animate-in slide-in-from-top-2">
                <label className="block text-[10px] font-black text-gray-400 uppercase mb-2 ml-1">Affiliated Team</label>
                <select
                  required
                  className="w-full rounded-2xl px-5 py-4 border border-gray-200 bg-gray-50 focus:ring-4 focus:ring-blue-50 outline-none font-bold bg-white"
                  value={selectedTeamId}
                  onChange={(e) => setSelectedTeamId(e.target.value)}
                >
                  <option value="">Select Team</option>
                  {teams.map((t) => (
                    <option key={t.id} value={t.id}>{t.name}</option>
                  ))}
                </select>
              </div>
            )}
          </div>

          <button
            type="submit"
            disabled={isLoading}
            className="w-full flex justify-center py-5 px-4 border border-transparent text-sm font-black rounded-2xl text-white bg-blue-600 hover:bg-blue-700 transition-all shadow-xl shadow-blue-100 disabled:opacity-50"
          >
            {isLoading ? (
              <i className="fas fa-circle-notch fa-spin text-xl"></i>
            ) : (
              <span className="tracking-widest">{isRegistering ? 'CREATE ACCOUNT' : 'AUTHENTICATE'}</span>
            )}
          </button>

          <div className="flex flex-col space-y-3 pt-2 text-center">
            {!isRegistering && activeTab === 'manager' && (
              <button
                type="button"
                onClick={() => setIsRegistering(true)}
                className="text-[10px] font-black text-blue-600 hover:text-blue-800 uppercase tracking-widest"
              >
                No account? Register as Manager
              </button>
            )}
            {isRegistering && (
              <button
                type="button"
                onClick={() => setIsRegistering(false)}
                className="text-[10px] font-black text-blue-600 hover:text-blue-800 uppercase tracking-widest"
              >
                Already registered? Login
              </button>
            )}
            <button
              type="button"
              onClick={onBack}
              className="text-[10px] font-black text-gray-400 hover:text-gray-600 uppercase tracking-widest"
            >
              Back to Dashboard
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default Login;

import React, { Component, ErrorInfo, ReactNode } from 'react';

interface Props {
  // Making children optional avoids "missing children" errors in some JSX compilers
  // even when children are provided between component tags in the parent.
  children?: ReactNode;
  componentName?: string;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

/**
 * Standard React Error Boundary component.
 * We extend Component explicitly to ensure this.props, this.state, and this.setState 
 * are correctly identified by the TypeScript compiler.
 */
// Fix: Extending Component directly from the react import to resolve property recognition issues
class ErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    // Fix: Correctly initialize the instance state
    this.state = {
      hasError: false,
      error: null
    };
  }

  public static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    // Fix: Access props correctly from the instance context
    console.error(`Uncaught error in ${this.props.componentName || 'Component'}:`, error, errorInfo);
  }

  public render() {
    // Fix: Access state correctly from the instance context
    if (this.state.hasError) {
      return (
        <div className="p-8 bg-white border-2 border-dashed border-red-100 rounded-[2.5rem] text-center space-y-4 my-4 animate-in fade-in zoom-in-95">
          <div className="w-16 h-16 bg-red-50 text-red-500 rounded-2xl flex items-center justify-center mx-auto shadow-sm">
            <i className="fas fa-microchip-slash text-2xl"></i>
          </div>
          <div className="space-y-1">
            <h3 className="text-xl font-black text-gray-900 tracking-tight">Component Encountered an Issue</h3>
            <p className="text-sm text-gray-500 font-medium">
              Something went wrong while rendering <span className="text-blue-600 font-bold">{this.props.componentName || 'this section'}</span>.
            </p>
          </div>
          <div className="pt-2 flex justify-center space-x-3">
            <button
              // Fix: Use the inherited setState method to clear the error state
              onClick={() => this.setState({ hasError: false, error: null })}
              className="bg-blue-600 text-white px-6 py-2.5 rounded-xl font-bold text-xs hover:bg-blue-700 transition-all shadow-lg shadow-blue-100 flex items-center space-x-2"
            >
              <i className="fas fa-redo-alt"></i>
              <span>Attempt Recovery</span>
            </button>
            <button
              onClick={() => window.location.reload()}
              className="bg-gray-100 text-gray-600 px-6 py-2.5 rounded-xl font-bold text-xs hover:bg-gray-200 transition-all flex items-center space-x-2"
            >
              <i className="fas fa-sync"></i>
              <span>Full Reload</span>
            </button>
          </div>
          {/* Fix: Check the state for the captured error object */}
          {this.state.error && (
            <details className="mt-4 text-left group">
              <summary className="text-[10px] font-black text-gray-300 uppercase cursor-pointer hover:text-gray-400 text-center tracking-widest list-none">
                Technical Details <i className="fas fa-chevron-down ml-1 group-open:rotate-180 transition-transform"></i>
              </summary>
              <div className="mt-4 p-4 bg-gray-900 rounded-2xl overflow-x-auto">
                <code className="text-[10px] font-mono text-red-400 break-all leading-relaxed">
                  {/* Fix: Extract error message from state */}
                  {this.state.error.toString()}
                </code>
              </div>
            </details>
          )}
        </div>
      );
    }

    // Fix: Return children from the props to render the wrapped content
    return this.props.children;
  }
}

export default ErrorBoundary;

