              {standings.length === 0 && (
                <tr>
                  <td colSpan={10} className="px-6 py-20 text-center text-gray-400">
                    No teams registered yet.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <StatsCard icon="fa-users" title="Total Teams" value={teams.length.toString()} color="blue" />
        <StatsCard icon="fa-futbol" title="Matches Played" value={standings.reduce((acc, s) => acc + s.played, 0).toString()} color="indigo" />
        <StatsCard icon="fa-star" title="Avg Goals/Game" value={(standings.reduce((acc, s) => acc + s.goalsFor, 0) / Math.max(1, standings.reduce((acc, s) => acc + s.played, 0) / 2)).toFixed(1)} color="purple" />
      </div>
    </div>
  );
};

const StatsCard: React.FC<{ icon: string; title: string; value: string; color: string }> = ({ icon, title, value, color }) => (
  <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm flex items-center space-x-4">
    <div className={`w-12 h-12 rounded-xl bg-${color}-100 flex items-center justify-center text-${color}-600 text-xl`}>
      <i className={`fas ${icon}`}></i>
    </div>
    <div>
      <p className="text-sm text-gray-500 font-medium">{title}</p>
      <p className="text-2xl font-bold text-gray-900">{value}</p>
    </div>
  </div>
);

export default StandingsTable;

import React, { useState, useMemo } from 'react';
import { Match, Team, UserRole, GoalScorer, Player, CardEvent, LeagueSettings } from '../types';

interface MatchSchedulerProps {
  matches: Match[];
  teams: Team[];
  isAdmin: boolean;
  role: UserRole;
  selectedTeamId: string | null;
  onAddMatch: (m: Match) => void;
  onUpdateMatch: (id: string, h: number, a: number, scorers: GoalScorer[], cards?: CardEvent[], refereeName?: string) => void;
  leagueSettings: LeagueSettings;
}

const MatchScheduler: React.FC<MatchSchedulerProps> = ({ 
  matches, 
  teams, 
  isAdmin, 
  role,
  selectedTeamId,
  onAddMatch, 
  onUpdateMatch,
  leagueSettings
}) => {
  const [showAdd, setShowAdd] = useState(false);
  const [editingMatchId, setEditingMatchId] = useState<string | null>(null);
  const [viewingMatchId, setViewingMatchId] = useState<string | null>(null);
  const [scores, setScores] = useState({ home: 0, away: 0 });
  const [currentScorers, setCurrentScorers] = useState<GoalScorer[]>([]);
  const [currentCards, setCurrentCards] = useState<CardEvent[]>([]);
  const [currentReferee, setCurrentReferee] = useState('');

  const [newMatch, setNewMatch] = useState<Partial<Match>>({
    date: '',
    time: '',
    venue: '',
    homeTeamId: '',
    awayTeamId: '',
    matchWeek: 1,
    refereeName: ''
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newMatch.homeTeamId && newMatch.awayTeamId && newMatch.homeTeamId !== newMatch.awayTeamId) {
      onAddMatch({
        ...newMatch as Match,
        id: `m${Date.now()}`,
        isCompleted: false
      });
      setShowAdd(false);
    }
  };

  const getTeam = (id: string) => teams.find(t => t.id === id);

  const canManageMatch = (match: Match) => {
    if (isAdmin) return true;
    if (role === UserRole.TEAM_MANAGER && selectedTeamId) {
      return match.homeTeamId === selectedTeamId || match.awayTeamId === selectedTeamId;
    }
    return false;
  };

  const startEditing = (e: React.MouseEvent, match: Match) => {
    e.stopPropagation();
    setEditingMatchId(match.id);
    setScores({ home: match.homeScore || 0, away: match.awayScore || 0 });
    setCurrentScorers(match.scorers || []);
    setCurrentCards(match.cards || []);
    setCurrentReferee(match.refereeName || '');
  };

  const addGoal = (player: Player, teamId: string) => {
    const minute = currentScorers.length > 0 ? Math.min(90, currentScorers[currentScorers.length - 1].minute + 5) : 10;
    setCurrentScorers([...currentScorers, { 
      playerId: player.id, 
      playerName: player.name, 
      teamId, 
      goals: 1, 
      minute 
    }].sort((a, b) => a.minute - b.minute));
  };

  const addCard = (player: Player, teamId: string, type: 'yellow' | 'red') => {
    setCurrentCards([...currentCards, {
      playerId: player.id,
      playerName: player.name,
      teamId,
      type,
      minute: 45
    }].sort((a, b) => a.minute - b.minute));
  };

  const updateScorerMinute = (index: number, minute: number) => {
    const updated = [...currentScorers];
    updated[index] = { ...updated[index], minute: Math.max(0, Math.min(120, minute)) };
    setCurrentScorers(updated.sort((a, b) => a.minute - b.minute));
  };

  const updateCardMinute = (index: number, minute: number) => {
    const updated = [...currentCards];
    updated[index] = { ...updated[index], minute: Math.max(0, Math.min(120, minute)) };
    setCurrentCards(updated.sort((a, b) => a.minute - b.minute));
  };

  const saveResult = (match: Match) => {
    onUpdateMatch(match.id, scores.home, scores.away, currentScorers, currentCards, currentReferee);
    setEditingMatchId(null);
  };

  const getPlayerPhoto = (playerId: string) => {
    for (const team of teams) {
      const player = team.players.find(p => p.id === playerId);
      if (player) return player.photoUrl;
    }
    return `https://api.dicebear.com/7.x/avataaars/svg?seed=${playerId}`;
  };

  const selectedMatch = matches.find(m => m.id === viewingMatchId);

  const timelineEvents = useMemo(() => {
    if (!selectedMatch) return [];
    const events = [
      ...(selectedMatch.scorers || []).map(s => ({ ...s, eventType: 'goal' as const })),
      ...(selectedMatch.cards || []).map(c => ({ ...c, eventType: 'card' as const }))
    ];
    return events.sort((a, b) => a.minute - b.minute);
  }, [selectedMatch]);

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-3xl font-black text-gray-900 tracking-tight">Fixtures & Results</h2>
          <p className="text-gray-500">{leagueSettings.name} matches for {leagueSettings.season}.</p>
        </div>
        {isAdmin && (
          <button 
            onClick={() => setShowAdd(!showAdd)}
            className="bg-blue-600 text-white px-6 py-3 rounded-xl font-bold shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all flex items-center space-x-2 w-full md:w-auto justify-center"
          >
            <i className={`fas ${showAdd ? 'fa-times' : 'fa-plus'}`}></i>
            <span>{showAdd ? 'Cancel' : 'Schedule New Match'}</span>
          </button>
        )}
      </div>

      {showAdd && (
        <form onSubmit={handleSubmit} className="bg-white p-8 rounded-3xl border border-blue-100 shadow-2xl grid grid-cols-1 md:grid-cols-3 gap-6 animate-in slide-in-from-top-4 duration-300">
          <div className="space-y-2">
            <label className="text-xs font-black text-gray-400 uppercase tracking-widest">Home Team</label>
            <select required className="w-full border border-gray-200 rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-blue-500 bg-gray-50" value={newMatch.homeTeamId} onChange={e => setNewMatch({ ...newMatch, homeTeamId: e.target.value })}>
              <option value="">Select Home</option>
              {teams.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
            </select>
          </div>
          <div className="space-y-2 text-center flex flex-col justify-center">
            <span className="text-2xl font-black text-gray-200">VS</span>
          </div>
          <div className="space-y-2">
            <label className="text-xs font-black text-gray-400 uppercase tracking-widest">Away Team</label>
            <select required className="w-full border border-gray-200 rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-blue-500 bg-gray-50" value={newMatch.awayTeamId} onChange={e => setNewMatch({ ...newMatch, awayTeamId: e.target.value })}>
              <option value="">Select Away</option>
              {teams.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-xs font-black text-gray-400 uppercase tracking-widest">Date & Time</label>
            <div className="flex space-x-2">
              <input type="date" required className="flex-1 border border-gray-200 rounded-xl px-4 py-3 bg-gray-50" value={newMatch.date} onChange={e => setNewMatch({ ...newMatch, date: e.target.value })} />
              <input type="time" required className="w-28 border border-gray-200 rounded-xl px-4 py-3 bg-gray-50" value={newMatch.time} onChange={e => setNewMatch({ ...newMatch, time: e.target.value })} />
            </div>
          </div>
          <div className="space-y-2">
            <label className="text-xs font-black text-gray-400 uppercase tracking-widest">Venue</label>
            <input type="text" required className="w-full border border-gray-200 rounded-xl px-4 py-3 bg-gray-50" placeholder="Stadium Name" value={newMatch.venue} onChange={e => setNewMatch({ ...newMatch, venue: e.target.value })} />
          </div>
          <div className="space-y-2">
            <label className="text-xs font-black text-gray-400 uppercase tracking-widest">Lead Referee</label>
            <input type="text" className="w-full border border-gray-200 rounded-xl px-4 py-3 bg-gray-50 outline-none focus:ring-2 focus:ring-blue-500" placeholder="Referee Name" value={newMatch.refereeName} onChange={e => setNewMatch({ ...newMatch, refereeName: e.target.value })} />
          </div>
          <div className="space-y-2">
            <label className="text-xs font-black text-gray-400 uppercase tracking-widest">Match Week</label>
            <input type="number" min="1" required className="w-full border border-gray-200 rounded-xl px-4 py-3 bg-gray-50 focus:ring-2 focus:ring-blue-500 outline-none" placeholder="e.g. 1" value={newMatch.matchWeek} onChange={e => setNewMatch({ ...newMatch, matchWeek: parseInt(e.target.value) || 1 })} />
          </div>
          <div className="flex items-end md:col-span-2">
            <button type="submit" className="w-full bg-blue-600 text-white py-3.5 rounded-xl font-black hover:bg-blue-700 transition-all shadow-lg shadow-blue-100 uppercase tracking-widest text-sm">
              Confirm Schedule
            </button>
          </div>
        </form>
      )}

      <div className="space-y-6">
        {matches.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime()).map(match => {
          const isManagerMatch = !isAdmin && role === UserRole.TEAM_MANAGER && (match.homeTeamId === selectedTeamId || match.awayTeamId === selectedTeamId);
          const isEditing = editingMatchId === match.id;
          const homeTeam = getTeam(match.homeTeamId);
          const awayTeam = getTeam(match.awayTeamId);

          return (
            <div 
              key={match.id} 
              onClick={() => match.isCompleted && !isEditing && setViewingMatchId(match.id)}
              className={`bg-white rounded-3xl border transition-all relative overflow-hidden flex flex-col ${match.isCompleted && !isEditing ? 'cursor-pointer hover:border-blue-300 hover:shadow-2xl' : ''} ${isManagerMatch ? 'border-blue-200 ring-4 ring-blue-50/50 shadow-xl' : 'border-gray-100'} p-6 group`}
            >
              <div className="flex flex-col md:flex-row items-center justify-between">
                <div className="flex flex-col items-center md:items-start space-y-1 mb-4 md:mb-0 w-full md:w-1/4">
                  <div className="flex items-center space-x-2">
                    <span className="text-[10px] font-black text-blue-600 bg-blue-50 px-2 py-0.5 rounded-full uppercase tracking-tighter">WEEK {match.matchWeek}</span>
                  </div>
                  <span className="text-lg font-black text-gray-900">{new Date(match.date).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' })}</span>
                  <div className="flex flex-col">
                    <span className="text-xs text-gray-400 font-medium uppercase tracking-widest">{match.time} • {match.venue}</span>
                    {match.refereeName && <span className="text-[10px] font-bold text-gray-300 uppercase mt-0.5"><i className="fas fa-bullhorn mr-1"></i> {match.refereeName}</span>}
                  </div>
                </div>

                <div className="flex items-center justify-center space-x-4 md:space-x-8 w-full md:w-2/4">
                  <div className="flex flex-col items-center space-y-3 w-1/3 text-center">
                    <img src={homeTeam?.logo} alt="" className="w-14 h-14 rounded-full border-4 border-white shadow-md object-cover" />
                    <span className="text-sm font-black text-gray-900 leading-tight">{homeTeam?.name}</span>
                  </div>

                  <div className="flex flex-col items-center justify-center px-4 min-w-[140px]">
                    {isEditing ? (
                      <div className="flex items-center space-x-2" onClick={e => e.stopPropagation()}>
                        <div className="flex flex-col items-center">
                          <label className="text-[8px] font-bold text-gray-400 uppercase">Home</label>
                          <input type="number" min="0" className="w-12 text-center border-2 border-blue-300 rounded-lg font-black py-2 text-blue-700" value={scores.home} onChange={(e) => setScores({ ...scores, home: parseInt(e.target.value) || 0 })} />
                        </div>
                        <span className="font-bold text-blue-300 text-lg mt-4">:</span>
                        <div className="flex flex-col items-center">
                          <label className="text-[8px] font-bold text-gray-400 uppercase">Away</label>
                          <input type="number" min="0" className="w-12 text-center border-2 border-blue-300 rounded-lg font-black py-2 text-blue-700" value={scores.away} onChange={(e) => setScores({ ...scores, away: parseInt(e.target.value) || 0 })} />
                        </div>
                      </div>
                    ) : match.isCompleted ? (
                      <div className="flex flex-col items-center">
                        <div className="flex items-center space-x-4 bg-gray-50 px-6 py-2 rounded-2xl border border-gray-100">
                          <span className="text-3xl font-black text-gray-900">{match.homeScore}</span>
                          <span className="text-gray-300 font-bold text-xl">:</span>
                          <span className="text-3xl font-black text-gray-900">{match.awayScore}</span>
                        </div>
                        <span className="text-[9px] font-black text-blue-400 mt-2 uppercase tracking-widest opacity-0 group-hover:opacity-100 transition-opacity">View Match Center</span>
                      </div>
                    ) : (
                      <div className="bg-gray-100 text-gray-400 px-4 py-1.5 rounded-full text-[10px] font-black tracking-widest uppercase border border-gray-200">UPCOMING</div>
                    )}
                  </div>

                  <div className="flex flex-col items-center space-y-3 w-1/3 text-center">
                    <img src={awayTeam?.logo} alt="" className="w-14 h-14 rounded-full border-4 border-white shadow-md object-cover" />
                    <span className="text-sm font-black text-gray-900 leading-tight">{awayTeam?.name}</span>
                  </div>
                </div>

                <div className="flex justify-center md:justify-end w-full md:w-1/4 mt-6 md:mt-0">
                  {canManageMatch(match) && !isEditing ? (
                    <button onClick={(e) => startEditing(e, match)} className="bg-green-600 text-white px-6 py-2.5 rounded-xl text-sm font-black hover:bg-green-700 shadow-lg transition-all flex items-center space-x-2">
                      <i className="fas fa-edit"></i>
                      <span>{match.isCompleted ? 'Edit Result' : 'Enter Result'}</span>
                    </button>
                  ) : isEditing ? (
                    <div className="flex space-x-2" onClick={e => e.stopPropagation()}>
                      <button onClick={() => saveResult(match)} className="bg-blue-600 text-white text-xs px-4 py-2 rounded-lg font-black uppercase">Save</button>
                      <button onClick={() => setEditingMatchId(null)} className="bg-white text-gray-500 text-xs px-4 py-2 rounded-lg font-black uppercase border border-gray-200">Cancel</button>
                    </div>
                  ) : match.isCompleted ? (
                    <div className="flex items-center space-x-1.5 bg-green-50 px-4 py-2 rounded-xl">
                      <i className="fas fa-check-double text-green-500 text-xs"></i>
                      <span className="text-[10px] font-black text-green-700 uppercase tracking-widest">Verified</span>
                    </div>
                  ) : null}
                </div>
              </div>

              {isEditing && (
                <div className="mt-8 pt-8 border-t border-gray-100 space-y-8 animate-in slide-in-from-bottom-2 duration-300" onClick={e => e.stopPropagation()}>
                  <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-gray-50 p-4 rounded-2xl border border-gray-100">
                    <div className="flex-1">
                      <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-1">Match Official (Referee)</label>
                      <input 
                        type="text" 
                        placeholder="Assign Official..." 
                        className="w-full bg-white border border-gray-200 rounded-xl px-4 py-2.5 font-bold focus:ring-2 focus:ring-blue-400 outline-none" 
                        value={currentReferee} 
                        onChange={(e) => setCurrentReferee(e.target.value)}
                      />
                    </div>
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                    {[match.homeTeamId, match.awayTeamId].map((tId) => {
                      const team = getTeam(tId);
                      return (
                        <div key={tId} className="space-y-4">
                          <div className="flex items-center space-x-2 mb-2">
                            <img src={team?.logo} className="w-6 h-6 rounded-full" alt="" />
                            <h4 className="text-[11px] font-black text-gray-900 uppercase tracking-wider">{team?.name} Timeline</h4>
                          </div>

                          <div className="space-y-3">
                            {currentScorers.filter(s => s.teamId === tId).map((s, idx) => (
                              <div key={`g-${idx}`} className="flex items-center justify-between bg-blue-50/40 p-3 rounded-2xl border border-blue-100/50">
                                <div className="flex items-center space-x-4">
                                  <div className="flex flex-col">
                                    <label className="text-[7px] font-black text-blue-400 uppercase ml-1">Min</label>
                                    <input 
                                      type="number" min="0" max="120" className="w-12 text-center bg-white border border-blue-100 rounded-lg font-black py-1 text-xs" 
                                      value={s.minute} onChange={(e) => updateScorerMinute(currentScorers.indexOf(s), parseInt(e.target.value) || 0)}
                                    />
                                  </div>
                                  <i className="fas fa-futbol text-blue-600 text-xs mt-3"></i>
                                  <span className="text-xs font-bold text-gray-700 mt-3">{s.playerName}</span>
                                </div>
                                <button onClick={() => setCurrentScorers(currentScorers.filter((_, i) => i !== currentScorers.indexOf(s)))} className="text-red-400 hover:text-red-600 mt-3"><i className="fas fa-times"></i></button>
                              </div>
                            ))}
                            {currentCards.filter(c => c.teamId === tId).map((c, idx) => (
                              <div key={`c-${idx}`} className="flex items-center justify-between bg-orange-50/40 p-3 rounded-2xl border border-orange-100/50">
                                <div className="flex items-center space-x-4">
                                  <div className="flex flex-col">
                                    <label className="text-[7px] font-black text-orange-400 uppercase ml-1">Min</label>
                                    <input 
                                      type="number" min="0" max="120" className="w-12 text-center bg-white border border-orange-100 rounded-lg font-black py-1 text-xs" 
                                      value={c.minute} onChange={(e) => updateCardMinute(currentCards.indexOf(c), parseInt(e.target.value) || 0)}
                                    />
                                  </div>
                                  <i className={`fas fa-square text-${c.type === 'yellow' ? 'yellow' : 'red'}-500 text-xs mt-3`}></i>
                                  <span className="text-xs font-bold text-gray-700 mt-3">{c.playerName}</span>
                                </div>
                                <button onClick={() => setCurrentCards(currentCards.filter((_, i) => i !== currentCards.indexOf(c)))} className="text-red-400 hover:text-red-600 mt-3"><i className="fas fa-times"></i></button>
                              </div>
                            ))}

                            <div className="pt-2 flex flex-col space-y-2">
                              <select className="w-full text-xs font-bold border-2 border-gray-100 rounded-xl p-2 bg-gray-50 outline-none" onChange={(e) => {
                                const p = team?.players.find(p => p.id === e.target.value);
                                if (p) addGoal(p, tId);
                                e.target.value = "";
                              }}>
                                <option value="">+ Record Goal Scorer...</option>
                                {team?.players.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                              </select>
                              <select className="w-full text-xs font-bold border-2 border-gray-100 rounded-xl p-2 bg-gray-50 outline-none" onChange={(e) => {
                                const [pId, type] = e.target.value.split('|');
                                const p = team?.players.find(p => p.id === pId);
                                if (p) addCard(p, tId, type as 'yellow' | 'red');
                                e.target.value = "";
                              }}>
                                <option value="">+ Record Disciplinary Card...</option>
                                {team?.players.map(p => (
                                  <React.Fragment key={p.id}>
                                    <option value={`${p.id}|yellow`}>Yellow Card: {p.name}</option>
                                    <option value={`${p.id}|red`}>Red Card: {p.name}</option>
                                  </React.Fragment>
                                ))}
                              </select>
                            </div>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>

      {viewingMatchId && selectedMatch && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-md animate-in fade-in duration-300 overflow-y-auto">
          <div className="bg-white w-full max-w-2xl rounded-[3rem] shadow-2xl border border-gray-100 overflow-hidden animate-in zoom-in-95 duration-300 my-8">
            <div className="bg-gradient-to-br from-gray-900 to-blue-900 p-10 text-white relative">
              <button 
                onClick={() => setViewingMatchId(null)} 
                className="absolute top-8 right-8 w-10 h-10 flex items-center justify-center rounded-full bg-white/10 hover:bg-white/20 transition-all"
              >
                <i className="fas fa-times"></i>
              </button>

              <div className="text-center space-y-2 mb-8">
                <span className="text-[10px] font-black text-blue-300 uppercase tracking-[0.3em]">{leagueSettings.season} • Matchweek {selectedMatch.matchWeek}</span>
                <p className="text-sm font-bold text-gray-400">{selectedMatch.venue}</p>
                {selectedMatch.refereeName && (
                  <div className="inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-white/10 border border-white/10 mt-2">
                    <i className="fas fa-user-tie text-[10px] text-blue-400"></i>
                    <span className="text-[10px] font-black uppercase tracking-widest">Referee: {selectedMatch.refereeName}</span>
                  </div>
                )}
              </div>

              <div className="flex items-center justify-between">
                <div className="flex flex-col items-center space-y-4 w-1/3">
                  <img src={getTeam(selectedMatch.homeTeamId)?.logo} className="w-20 h-20 rounded-full border-4 border-white/20 shadow-2xl object-cover" alt="" />
                  <h3 className="text-xl font-black tracking-tight text-center leading-tight">{getTeam(selectedMatch.homeTeamId)?.name}</h3>
                </div>

                <div className="flex flex-col items-center justify-center px-4 w-1/3">
                  <div className="flex items-center space-x-6">
                    <span className="text-6xl font-black tracking-tighter">{selectedMatch.homeScore}</span>
                    <span className="text-4xl font-black text-white/20">-</span>
                    <span className="text-6xl font-black tracking-tighter">{selectedMatch.awayScore}</span>
                  </div>
                  <div className="mt-4 px-4 py-1.5 rounded-full bg-green-500/20 border border-green-500/30 text-green-400 text-[10px] font-black tracking-widest uppercase">Full Time</div>
                </div>

                <div className="flex flex-col items-center space-y-4 w-1/3">
                  <img src={getTeam(selectedMatch.awayTeamId)?.logo} className="w-20 h-20 rounded-full border-4 border-white/20 shadow-2xl object-cover" alt="" />
                  <h3 className="text-xl font-black tracking-tight text-center leading-tight">{getTeam(selectedMatch.awayTeamId)?.name}</h3>
                </div>
              </div>
            </div>

            <div className="p-10 bg-gray-50">
              <h4 className="text-center text-[10px] font-black text-gray-400 uppercase tracking-[0.4em] mb-10">Match Timeline</h4>

              <div className="relative space-y-6 before:absolute before:inset-0 before:ml-5 before:-translate-x-px md:before:mx-auto md:before:translate-x-0 before:h-full before:w-0.5 before:bg-gradient-to-b before:from-transparent before:via-gray-200 before:to-transparent">
                {timelineEvents.map((event, idx) => {
                  const isHome = event.teamId === selectedMatch.homeTeamId;
                  const isCard = 'type' in event;

                  return (
                    <div key={idx} className={`relative flex items-center justify-between md:justify-normal md:odd:flex-row-reverse group animate-in slide-in-from-bottom-4`} style={{ animationDelay: `${idx * 100}ms` }}>
                      <div className={`flex items-center justify-center w-10 h-10 rounded-full border border-white shadow shrink-0 md:order-1 md:group-odd:-translate-x-1/2 md:group-even:translate-x-1/2 z-10 ${
                        'eventType' in event && event.eventType === 'goal' ? 'bg-blue-600 text-white' : 
                        isCard && (event as CardEvent).type === 'yellow' ? 'bg-yellow-400 text-yellow-900' : 'bg-red-500 text-white'
                      }`}>
                        <span className="text-[10px] font-black">{event.minute}'</span>
                      </div>

                      <div className={`w-[calc(100%-4rem)] md:w-[calc(50%-2.5rem)] p-4 rounded-2xl bg-white border border-gray-100 shadow-sm transition-all hover:shadow-md ${isHome ? 'md:ml-auto' : 'md:mr-auto'}`}>
                        <div className="flex items-center space-x-3">
                          <img src={getPlayerPhoto(event.playerId)} className="w-8 h-8 rounded-full border border-gray-100" alt="" />
                          <div>
                            <p className="text-sm font-black text-gray-900">{event.playerName}</p>
                            <div className="flex items-center space-x-1.5">
                              { 'eventType' in event && event.eventType === 'goal' ? (
                                <>
                                  <i className="fas fa-futbol text-[10px] text-blue-500"></i>
                                  <span className="text-[9px] font-black text-blue-500 uppercase tracking-widest">Goal Scored</span>
                                </>
                              ) : (
                                <>
                                  <i className={`fas fa-square text-[10px] text-${(event as CardEvent).type === 'yellow' ? 'yellow' : 'red'}-500`}></i>
                                  <span className={`text-[9px] font-black text-${(event as CardEvent).type === 'yellow' ? 'yellow' : 'red'}-600 uppercase tracking-widest`}>{(event as CardEvent).type} Card</span>
                                </>
                              )}
                            </div>
                          </div>
                        </div>
                      </div>
                    </div>
                  );
                })}

                {timelineEvents.length === 0 && (
                  <div className="text-center py-20 text-gray-400 italic">No significant match events recorded.</div>
                )}
              </div>

              <div className="mt-12 text-center">
                <button 
                  onClick={() => setViewingMatchId(null)}
                  className="bg-white text-gray-900 border border-gray-200 px-8 py-3 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-gray-50 transition-all shadow-sm"
                >
                  Close Match Center
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default MatchScheduler;

import React, { useState, useEffect, useRef } from 'react';
import { Team, Match, GoalScorer, UserRole, LeagueSettings } from '../types';
import TeamRegistration from './TeamRegistration';

interface User {
  id: string;
  username: string;
  role: UserRole;
  teamId?: string;
}

interface AdminPanelProps {
  teams: Team[];
  matches: Match[];
  leagueSettings: LeagueSettings;
  onUpdateLeagueSettings: (settings: LeagueSettings) => void;
  onUpdateMatch: (id: string, h: number, a: number, scorers?: GoalScorer[], cards?: any[], refereeName?: string) => void;
  onUpdateTeam?: (updatedTeam: Team) => void;
  onRegisterTeam: (team: Omit<Team, 'id' | 'players'>) => void;
  onManageSquad: (teamId: string) => void;
  onReset: () => void;
  onImportState: (data: any) => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ 
  teams, 
  matches, 
  leagueSettings, 
  onUpdateLeagueSettings, 
  onUpdateMatch, 
  onUpdateTeam, 
  onRegisterTeam, 
  onManageSquad, 
  onReset, 
  onImportState 
}) => {
  const [editingTeam, setEditingTeam] = useState<Team | null>(null);
  const [showRegisterModal, setShowRegisterModal] = useState(false);
  const [staff, setStaff] = useState<User[]>([]);
  const [showAddStaff, setShowAddStaff] = useState(false);
  const [newStaff, setNewStaff] = useState({ username: '', password: '', role: UserRole.TEAM_MANAGER, teamId: '' });

  const [settingsForm, setSettingsForm] = useState<LeagueSettings>(leagueSettings);
  const [logoPreview, setLogoPreview] = useState(leagueSettings.logo);

  const importFileRef = useRef<HTMLInputElement>(null);
  const logoInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const localUsers = JSON.parse(localStorage.getItem('lp_local_users_v2') || '[]');
    const allStaff = [
      { id: 'u-admin', username: 'admin', role: UserRole.ADMIN },
      ...localUsers
    ];
    setStaff(allStaff);
  }, []);

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64 = reader.result as string;
        setLogoPreview(base64);
        setSettingsForm(prev => ({ ...prev, logo: base64 }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveSettings = (e: React.FormEvent) => {
    e.preventDefault();
    onUpdateLeagueSettings(settingsForm);
    alert('League configuration updated successfully!');
  };

  const handleTeamOverride = (updatedData: Omit<Team, 'id' | 'players'>) => {
    if (editingTeam && onUpdateTeam) {
      const fullUpdatedTeam: Team = {
        ...editingTeam,
        ...updatedData
      };
      onUpdateTeam(fullUpdatedTeam);
      setEditingTeam(null);
    }
  };

  const removeStaff = (userId: string) => {
    if (userId === 'u-admin') return alert("Cannot remove the primary system administrator.");
    if (confirm('Are you sure you want to revoke access for this user?')) {
      const localUsers = JSON.parse(localStorage.getItem('lp_local_users_v2') || '[]');
      const updated = localUsers.filter((u: any) => u.username !== userId && u.id !== userId);
      localStorage.setItem('lp_local_users_v2', JSON.stringify(updated));
      setStaff(prev => prev.filter(u => u.id !== userId && u.username !== userId));
    }
  };

  const addStaff = (e: React.FormEvent) => {
    e.preventDefault();
    const id = `u-${Date.now()}`;
    const newUser = { ...newStaff, id };

    const localUsers = JSON.parse(localStorage.getItem('lp_local_users_v2') || '[]');
    localUsers.push(newUser);
    localStorage.setItem('lp_local_users_v2', JSON.stringify(localUsers));

    setStaff(prev => [...prev, newUser]);
    setShowAddStaff(false);
    setNewStaff({ username: '', password: '', role: UserRole.TEAM_MANAGER, teamId: '' });
  };

  const exportLeagueData = () => {
    const backup = {
      timestamp: new Date().toISOString(),
      teams,
      matches,
      settings: leagueSettings,
      users: JSON.parse(localStorage.getItem('lp_local_users_v2') || '[]')
    };
    const blob = new Blob([JSON.stringify(backup, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `leaguepro-backup-${new Date().toISOString().slice(0, 10)}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        try {
          const data = JSON.parse(event.target?.result as string);
          if (confirm('Importing will overwrite current local league data. Continue?')) {
            onImportState(data);
          }
        } catch (err) {
          alert('Invalid backup file format.');
        }
      };
      reader.readAsText(file);
    }
  };

  return (
    <div className="space-y-10 pb-20 animate-in fade-in duration-500">
      {/* League Settings Suite */}
      <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-xl overflow-hidden relative">
        <div className="absolute top-0 right-0 p-8 opacity-5">
          <i className="fas fa-cog text-[120px]"></i>
        </div>

        <h3 className="text-2xl font-black text-gray-900 mb-8 flex items-center">
          <i className="fas fa-id-card mr-4 text-blue-600"></i>
          League Identity & Configuration
        </h3>

        <form onSubmit={handleSaveSettings} className="grid grid-cols-1 md:grid-cols-3 gap-8 relative z-10">
          <div className="flex flex-col items-center space-y-4">
            <div 
              onClick={() => logoInputRef.current?.click()}
              className="w-full aspect-square rounded-3xl bg-gray-50 border-2 border-dashed border-gray-200 flex items-center justify-center cursor-pointer hover:border-blue-400 hover:bg-blue-50 transition-all group overflow-hidden"
            >
              {logoPreview ? (
                <img src={logoPreview} className="w-full h-full object-contain p-4" alt="League Logo" />
              ) : (
                <div className="text-center p-6">
                  <i className="fas fa-trophy text-3xl text-gray-300 mb-2"></i>
                  <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">League Logo</p>
                </div>
              )}
              <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                <span className="text-white text-[10px] font-black uppercase">Change Logo</span>
              </div>
            </div>
            <input type="file" ref={logoInputRef} className="hidden" accept="image/*" onChange={handleLogoUpload} />
          </div>

          <div className="md:col-span-2 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">League Name</label>
                <input 
                  required
                  className="w-full border border-gray-100 bg-gray-50 rounded-xl px-4 py-3 font-bold focus:ring-2 focus:ring-blue-500 outline-none"
                  value={settingsForm.name}
                  onChange={e => setSettingsForm({...settingsForm, name: e.target.value})}
                />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Current Season</label>
                <input 
                  required
                  className="w-full border border-gray-100 bg-gray-50 rounded-xl px-4 py-3 font-bold focus:ring-2 focus:ring-blue-500 outline-none"
                  value={settingsForm.season}
                  onChange={e => setSettingsForm({...settingsForm, season: e.target.value})}
                />
              </div>
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Welcome Description</label>
              <textarea 
                rows={3}
                className="w-full border border-gray-100 bg-gray-50 rounded-xl px-4 py-3 font-bold focus:ring-2 focus:ring-blue-500 outline-none resize-none"
                value={settingsForm.description}
                onChange={e => setSettingsForm({...settingsForm, description: e.target.value})}
              />
            </div>
            <button 
              type="submit"
              className="w-full bg-blue-600 text-white py-4 rounded-2xl font-black uppercase text-xs tracking-[0.2em] shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all"
            >
              Update League Identity
            </button>
          </div>
        </form>
      </div>

      {/* Persistence and Backup Suite */}
      <div className="bg-indigo-900 rounded-[2.5rem] p-8 text-white shadow-2xl relative overflow-hidden">
        <div className="relative z-10 flex flex-col md:flex-row justify-between items-center gap-6">
          <div className="flex-1 space-y-2">
            <div className="flex items-center space-x-3">
              <div className="bg-indigo-400/20 p-2 rounded-lg">
                <i className="fas fa-cloud-upload-alt text-xl"></i>
              </div>
              <h3 className="text-xl font-black uppercase tracking-tight">Data Management</h3>
            </div>
            <p className="text-indigo-200 text-sm max-w-lg">
              Your league is stored locally in this browser. Use the tools below to download a permanent backup or migrate your data to another device.
            </p>
          </div>
          <div className="flex flex-wrap gap-3">
            <button 
              onClick={exportLeagueData}
              className="bg-white text-indigo-900 px-6 py-3 rounded-xl font-black text-xs uppercase tracking-widest hover:bg-indigo-50 transition-all flex items-center space-x-2 shadow-lg"
            >
              <i className="fas fa-download"></i>
              <span>Export Backup</span>
            </button>
            <button 
              onClick={() => importFileRef.current?.click()}
              className="bg-indigo-500 text-white px-6 py-3 rounded-xl font-black text-xs uppercase tracking-widest hover:bg-indigo-600 transition-all flex items-center space-x-2 border border-indigo-400"
            >
              <i className="fas fa-upload"></i>
              <span>Import Backup</span>
            </button>
            <input type="file" ref={importFileRef} className="hidden" accept=".json" onChange={handleImport} />
          </div>
        </div>
        <i className="fas fa-database absolute -right-10 -bottom-10 text-[180px] text-white/5 rotate-12"></i>
      </div>

      {/* Critical System Controls */}
      <div className="bg-red-50 border-l-4 border-red-500 p-6 rounded-r-2xl flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div className="flex items-center space-x-4">
          <div className="bg-red-100 p-3 rounded-full">
            <i className="fas fa-exclamation-triangle text-red-600 text-xl"></i>
          </div>
          <div>
            <h3 className="text-lg font-black text-red-900 uppercase tracking-tight">Season Hard Reset</h3>
            <p className="text-red-700 text-sm">Clear all matches and return to the default state.</p>
          </div>
        </div>
        <button 
          onClick={onReset}
          className="bg-white text-red-600 border border-red-200 px-8 py-3 rounded-xl font-black hover:bg-red-600 hover:text-white transition-all shadow-sm text-xs uppercase tracking-widest"
        >
          Factory Reset
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-xl font-black text-gray-900 flex items-center">
              <i className="fas fa-shield-alt mr-3 text-blue-600"></i>
              Active Members ({teams.length})
            </h3>
            <button 
              onClick={() => setShowRegisterModal(true)}
              className="bg-blue-600 text-white px-4 py-2 rounded-xl text-[10px] font-black shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all uppercase tracking-widest"
            >
              Add New Team
            </button>
          </div>
          <div className="space-y-3 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">
            {teams.map(team => (
              <div key={team.id} className="flex flex-col p-4 bg-gray-50 rounded-2xl hover:bg-white hover:shadow-md hover:ring-1 hover:ring-blue-100 transition-all group">
                <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-4">
                    <div className="relative">
                      <img src={team.logo} className="w-12 h-12 rounded-xl border-2 border-white shadow-sm object-cover" alt="" />
                    </div>
                    <div>
                      <p className="font-black text-gray-900 leading-tight">{team.name}</p>
                      <div className="flex items-center space-x-2 text-[10px] font-bold text-gray-400 uppercase tracking-tight mt-1">
                        <span>{team.manager}</span>
                        <span className="text-gray-200">•</span>
                        <span>{team.players.length} Squad</span>
                      </div>
                    </div>
                  </div>
                  <div className="flex space-x-2">
                    <button 
                      onClick={() => setEditingTeam(team)}
                      className="bg-white text-blue-600 px-3 py-1.5 rounded-lg text-[9px] font-black shadow-sm border border-gray-100 hover:bg-blue-50 transition-all uppercase tracking-widest"
                    >
                      Profile
                    </button>
                    <button 
                      onClick={() => onManageSquad(team.id)}
                      className="bg-blue-600 text-white px-3 py-1.5 rounded-lg text-[9px] font-black shadow-sm hover:bg-blue-700 transition-all uppercase tracking-widest"
                    >
                      Squad
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm flex flex-col">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-xl font-black text-gray-900 flex items-center">
              <i className="fas fa-user-lock mr-3 text-indigo-600"></i>
              Staff & Access
            </h3>
            <button 
              onClick={() => setShowAddStaff(true)}
              className="bg-indigo-50 text-indigo-600 p-2 rounded-lg hover:bg-indigo-600 hover:text-white transition-all"
            >
              <i className="fas fa-plus"></i>
            </button>
          </div>
          <div className="space-y-3 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar flex-1">
            {staff.map(user => {
              const userTeam = teams.find(t => t.id === user.teamId);
              return (
                <div key={user.id} className="flex items-center justify-between p-4 bg-indigo-50/30 rounded-2xl border border-indigo-50">
                  <div className="flex items-center space-x-3">
                    <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-indigo-500 shadow-sm">
                      <i className={`fas ${user.role === UserRole.ADMIN ? 'fa-user-shield' : 'fa-user-tie'}`}></i>
                    </div>
                    <div>
                      <p className="font-black text-gray-900 text-sm leading-none">{user.username}</p>
                      <span className="text-[9px] font-bold text-indigo-400 uppercase tracking-widest">
                        {user.role === UserRole.ADMIN ? 'System Administrator' : userTeam?.name || 'Unassigned Manager'}
                      </span>
                    </div>
                  </div>
                  {user.id !== 'u-admin' && (
                    <button 
                      onClick={() => removeStaff(user.id)}
                      className="text-red-400 hover:text-red-600 p-2 transition-colors"
                    >
                      <i className="fas fa-user-minus"></i>
                    </button>
                  )}
                </div>
              );
            })}
          </div>
        </div>

        <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm lg:col-span-2">
          <h3 className="text-xl font-black text-gray-900 mb-6 flex items-center">
            <i className="fas fa-history mr-3 text-blue-600"></i>
            Match History Overrides
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">
            {matches.filter(m => m.isCompleted).length > 0 ? (
              matches.filter(m => m.isCompleted).map(match => (
                <div key={match.id} className="p-5 bg-gray-50 rounded-2xl border border-gray-100 space-y-4">
                  <div className="flex justify-between items-center">
                    <span className="text-[10px] font-black text-blue-500 bg-blue-50 px-2 py-0.5 rounded-md uppercase">Match Week {match.matchWeek}</span>
                    <div className="text-right">
                      <span className="text-[10px] font-bold text-gray-400 block tracking-tighter">ID: {match.id}</span>
                      <input 
                        type="text"
                        placeholder="Assign Official..."
                        className="mt-1 text-[9px] font-black text-blue-600 bg-white border border-gray-100 rounded px-2 py-0.5 outline-none focus:ring-1 focus:ring-blue-300"
                        defaultValue={match.refereeName}
                        onBlur={(e) => onUpdateMatch(match.id, match.homeScore || 0, match.awayScore || 0, undefined, undefined, e.target.value)}
                      />
                    </div>
                  </div>
                  <div className="flex justify-between items-center">
                    <div className="w-1/3 text-right">
                      <p className="font-bold text-gray-900 truncate text-xs">{teams.find(t => t.id === match.homeTeamId)?.name}</p>
                    </div>
                    <div className="flex space-x-2 items-center px-4">
                      <input 
                        type="number" 
                        min="0"
                        className="w-10 text-center border-2 border-white bg-white rounded-lg font-black py-1 shadow-sm focus:ring-2 focus:ring-blue-400 outline-none text-xs" 
                        defaultValue={match.homeScore} 
                        onBlur={(e) => onUpdateMatch(match.id, parseInt(e.target.value) || 0, match.awayScore || 0)}
                      />
                      <span className="font-black text-gray-300">-</span>
                      <input 
                        type="number" 
                        min="0"
                        className="w-10 text-center border-2 border-white bg-white rounded-lg font-black py-1 shadow-sm focus:ring-2 focus:ring-blue-400 outline-none text-xs" 
                        defaultValue={match.awayScore} 
                        onBlur={(e) => onUpdateMatch(match.id, match.homeScore || 0, parseInt(e.target.value) || 0)}
                      />
                    </div>
                    <div className="w-1/3 text-left">
                      <p className="font-bold text-gray-900 truncate text-xs">{teams.find(t => t.id === match.awayTeamId)?.name}</p>
                    </div>
                  </div>
                </div>
              ))
            ) : (
              <div className="col-span-full text-center py-20 text-gray-400 border-2 border-dashed border-gray-100 rounded-[2.5rem]">
                <i className="fas fa-file-invoice text-4xl mb-3 opacity-20"></i>
                <p className="text-sm font-medium">No results recorded to override yet.</p>
              </div>
            )}
          </div>
        </div>
      </div>

      {showRegisterModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-md animate-in fade-in duration-300 overflow-y-auto">
          <div className="bg-white w-full max-w-2xl rounded-[3rem] shadow-2xl border border-gray-100 overflow-hidden animate-in zoom-in-95 duration-300 my-8">
            <div className="relative">
              <TeamRegistration 
                existingNames={teams.map(t => t.name)}
                onRegister={(t) => { onRegisterTeam(t); setShowRegisterModal(false); }}
                onCancel={() => setShowRegisterModal(false)}
              />
            </div>
          </div>
        </div>
      )}

      {showAddStaff && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-md animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-2xl p-8 space-y-6">
            <h3 className="text-2xl font-black text-gray-900">Admit New Staff</h3>
            <form onSubmit={addStaff} className="space-y-4">
              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Username</label>
                <input 
                  required
                  className="w-full border border-gray-100 bg-gray-50 rounded-xl px-4 py-3 font-bold focus:ring-2 focus:ring-indigo-500 outline-none"
                  value={newStaff.username}
                  onChange={e => setNewStaff({...newStaff, username: e.target.value})}
                />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Initial Password</label>
                <input 
                  required
                  type="password"
                  className="w-full border border-gray-100 bg-gray-50 rounded-xl px-4 py-3 font-bold focus:ring-2 focus:ring-indigo-500 outline-none"
                  value={newStaff.password}
                  onChange={e => setNewStaff({...newStaff, password: e.target.value})}
                />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Associated Team</label>
                <select 
                  className="w-full border border-gray-100 bg-gray-50 rounded-xl px-4 py-3 font-bold focus:ring-2 focus:ring-indigo-500 outline-none"
                  value={newStaff.teamId}
                  onChange={e => setNewStaff({...newStaff, teamId: e.target.value})}
                >
                  <option value="">No Team (Admin Only)</option>
                  {teams.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
                </select>
              </div>
              <div className="flex space-x-3 pt-4">
                <button type="submit" className="flex-1 bg-indigo-600 text-white py-3 rounded-xl font-black uppercase text-xs tracking-widest hover:bg-indigo-700 shadow-lg shadow-indigo-100">Confirm Admission</button>
                <button type="button" onClick={() => setShowAddStaff(false)} className="px-6 bg-gray-100 text-gray-500 py-3 rounded-xl font-bold uppercase text-xs">Cancel</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {editingTeam && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-md animate-in fade-in duration-300 overflow-y-auto">
          <div className="bg-white w-full max-w-2xl rounded-[3rem] shadow-2xl border border-gray-100 overflow-hidden animate-in zoom-in-95 duration-300 my-8">
            <div className="relative">
              <TeamRegistration 
                initialData={editingTeam}
                existingNames={teams.map(t => t.name)}
                onRegister={handleTeamOverride}
                onCancel={() => setEditingTeam(null)}
              />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminPanel;

import express from 'express';
import cors from 'cors';
import { createClient } from '@libsql/client';
import dotenv from 'dotenv';

dotenv.config();

const app = express();
const port = process.env.PORT || 3001;

app.use(cors());
app.use(express.json({ limit: '10mb' }));

// Turso Client Configuration
const db = createClient({
  url: process.env.TURSO_DATABASE_URL || 'libsql://your-db-name.turso.io',
  authToken: process.env.TURSO_AUTH_TOKEN || '',
});

async function setupDb() {
  try {
    // Create tables if they don't exist
    await db.execute(`
      CREATE TABLE IF NOT EXISTS users (
        id TEXT PRIMARY KEY,
        username TEXT UNIQUE,
        password TEXT,
        role TEXT,
        teamId TEXT
      );
    `);
    await db.execute(`
      CREATE TABLE IF NOT EXISTS teams (
        id TEXT PRIMARY KEY,
        data TEXT
      );
    `);
    await db.execute(`
      CREATE TABLE IF NOT EXISTS matches (
        id TEXT PRIMARY KEY,
        data TEXT
      );
    `);
    await db.execute(`
      CREATE TABLE IF NOT EXISTS settings (
        id TEXT PRIMARY KEY,
        data TEXT
      );
    `);

    // Seed default admin if not exists
    const adminCheck = await db.execute({
      sql: 'SELECT * FROM users WHERE role = ?',
      args: ['ADMIN']
    });

    if (adminCheck.rows.length === 0) {
      await db.execute({
        sql: 'INSERT INTO users (id, username, password, role) VALUES (?, ?, ?, ?)',
        args: ['u-admin', 'admin', 'admin123', 'ADMIN']
      });
      console.log('Seeded default admin user');
    }

    console.log('Turso Database initialized successfully');
  } catch (err) {
    console.error('Failed to initialize Turso DB:', err);
  }
}

// Auth Routes
app.post('/api/auth/register', async (req, res) => {
  const { username, password, role, teamId } = req.body;
  try {
    const id = `u-${Date.now()}`;
    await db.execute({
      sql: 'INSERT INTO users (id, username, password, role, teamId) VALUES (?, ?, ?, ?, ?)',
      args: [id, username, password, role, teamId || null]
    });
    res.status(201).json({ id, username, role, teamId });
  } catch (e) {
    res.status(400).json({ error: 'Username already exists' });
  }
});

app.post('/api/auth/login', async (req, res) => {
  const { username, password } = req.body;
  try {
    const result = await db.execute({
      sql: 'SELECT * FROM users WHERE username = ? AND password = ?',
      args: [username, password]
    });
    const user = result.rows[0];
    if (user) {
      res.json({ 
        id: user.id, 
        username: user.username, 
        role: user.role, 
        teamId: user.teamId 
      });
    } else {
      res.status(401).json({ error: 'Invalid credentials' });
    }
  } catch (e) {
    res.status(500).json({ error: 'Internal server error during login' });
  }
});

// Settings Routes
app.get('/api/settings', async (req, res) => {
  try {
    const result = await db.execute("SELECT data FROM settings WHERE id = 'global'");
    if (result.rows.length > 0) {
      res.json(JSON.parse(result.rows[0].data as string));
    } else {
      res.json(null);
    }
  } catch (e) {
    res.status(500).json({ error: 'Failed to fetch settings' });
  }
});

app.post('/api/settings', async (req, res) => {
  const settings = req.body;
  try {
    await db.execute({
      sql: "INSERT INTO settings (id, data) VALUES ('global', ?) ON CONFLICT(id) DO UPDATE SET data = excluded.data",
      args: [JSON.stringify(settings)]
    });
    res.status(201).json(settings);
  } catch (e) {
    res.status(500).json({ error: 'Failed to save settings' });
  }
});

// Resource Routes
app.get('/api/teams', async (req, res) => {
  try {
    const result = await db.execute('SELECT data FROM teams');
    res.json(result.rows.map((row: any) => JSON.parse(row.data)));
  } catch (e) {
    res.status(500).json({ error: 'Failed to fetch teams' });
  }
});

app.post('/api/teams', async (req, res) => {
  const team = req.body;
  try {
    await db.execute({
      sql: 'INSERT INTO teams (id, data) VALUES (?, ?) ON CONFLICT(id) DO UPDATE SET data = excluded.data',
      args: [team.id, JSON.stringify(team)]
    });
    res.status(201).json(team);
  } catch (e) {
    res.status(500).json({ error: 'Failed to save team' });
  }
});

app.get('/api/matches', async (req, res) => {
  try {
    const result = await db.execute('SELECT data FROM matches');
    res.json(result.rows.map((row: any) => JSON.parse(row.data)));
  } catch (e) {
    res.status(500).json({ error: 'Failed to fetch matches' });
  }
});

app.post('/api/matches', async (req, res) => {
  const match = req.body;
  try {
    await db.execute({
      sql: 'INSERT INTO matches (id, data) VALUES (?, ?) ON CONFLICT(id) DO UPDATE SET data = excluded.data',
      args: [match.id, JSON.stringify(match)]
    });
    res.status(201).json(match);
  } catch (e) {
    res.status(500).json({ error: 'Failed to save match' });
  }
});

app.put('/api/matches/:id', async (req, res) => {
  const match = req.body;
  try {
    await db.execute({
      sql: 'UPDATE matches SET data = ? WHERE id = ?',
      args: [JSON.stringify(match), req.params.id]
    });
    res.json(match);
  } catch (e) {
    res.status(500).json({ error: 'Failed to update match' });
  }
});

setupDb().then(() => {
  app.listen(port, () => {
    console.log(`Backend running with Turso at http://localhost:${port}`);
  });
});

import React, { Component, ErrorInfo, ReactNode } from 'react';

interface Props {
  // Making children optional avoids "missing children" errors in some JSX compilers
  // even when children are provided between component tags in the parent.
  children?: ReactNode;
  componentName?: string;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

/**
 * Standard React Error Boundary component.
 * We extend React.Component explicitly to ensure this.props, this.state, and this.setState 
 * are correctly identified by the TypeScript compiler.
 */
class ErrorBoundary extends React.Component<Props, State> {
  // Fix: Initialize state as a class property for better TypeScript inference and to resolve state property errors
  public state: State = {
    hasError: false,
    error: null
  };

  public static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    // Fix: Access props correctly from the instance context by extending React.Component
    console.error(`Uncaught error in ${this.props.componentName || 'Component'}:`, error, errorInfo);
  }

  public render() {
    // Fix: Access state correctly from the instance context
    if (this.state.hasError) {
      return (
        <div className="p-8 bg-white border-2 border-dashed border-red-100 rounded-[2.5rem] text-center space-y-4 my-4 animate-in fade-in zoom-in-95">
          <div className="w-16 h-16 bg-red-50 text-red-500 rounded-2xl flex items-center justify-center mx-auto shadow-sm">
            <i className="fas fa-microchip-slash text-2xl"></i>
          </div>
          <div className="space-y-1">
            <h3 className="text-xl font-black text-gray-900 tracking-tight">Component Encountered an Issue</h3>
            <p className="text-sm text-gray-500 font-medium">
              Something went wrong while rendering <span className="text-blue-600 font-bold">{this.props.componentName || 'this section'}</span>.
            </p>
          </div>
          <div className="pt-2 flex justify-center space-x-3">
            <button
              // Fix: Use the inherited setState method to clear the error state
              onClick={() => this.setState({ hasError: false, error: null })}
              className="bg-blue-600 text-white px-6 py-2.5 rounded-xl font-bold text-xs hover:bg-blue-700 transition-all shadow-lg shadow-blue-100 flex items-center space-x-2"
            >
              <i className="fas fa-redo-alt"></i>
              <span>Attempt Recovery</span>
            </button>
            <button
              onClick={() => window.location.reload()}
              className="bg-gray-100 text-gray-600 px-6 py-2.5 rounded-xl font-bold text-xs hover:bg-gray-200 transition-all flex items-center space-x-2"
            >
              <i className="fas fa-sync"></i>
              <span>Full Reload</span>
            </button>
          </div>
          {/* Fix: Check the state for the captured error object */}
          {this.state.error && (
            <details className="mt-4 text-left group">
              <summary className="text-[10px] font-black text-gray-300 uppercase cursor-pointer hover:text-gray-400 text-center tracking-widest list-none">
                Technical Details <i className="fas fa-chevron-down ml-1 group-open:rotate-180 transition-transform"></i>
              </summary>
              <div className="mt-4 p-4 bg-gray-900 rounded-2xl overflow-x-auto">
                <code className="text-[10px] font-mono text-red-400 break-all leading-relaxed">
                  {/* Fix: Extract error message from state */}
                  {this.state.error.toString()}
                </code>
              </div>
            </details>
          )}
        </div>
      );
    }

    // Fix: Return children from the props to render the wrapped content
    return this.props.children;
  }
}

export default ErrorBoundary;

import React, { useState, useEffect, useRef } from 'react';
import { Team, Match, GoalScorer, UserRole, LeagueSettings } from '../types';
import TeamRegistration from './TeamRegistration';

interface User {
  id: string;
  username: string;
  role: UserRole;
  teamId?: string;
}

interface AdminPanelProps {
  teams: Team[];
  matches: Match[];
  leagueSettings: LeagueSettings;
  onUpdateLeagueSettings: (settings: LeagueSettings) => void;
  onUpdateMatch: (id: string, h: number, a: number, scorers?: GoalScorer[], cards?: any[], refereeName?: string) => void;
  onUpdateTeam?: (updatedTeam: Team) => void;
  onRegisterTeam: (team: Omit<Team, 'id' | 'players'>) => void;
  onManageSquad: (teamId: string) => void;
  onReset: () => void;
  onImportState: (data: any) => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ 
  teams, 
  matches, 
  leagueSettings, 
  onUpdateLeagueSettings, 
  onUpdateMatch, 
  onUpdateTeam, 
  onRegisterTeam, 
  onManageSquad, 
  onReset, 
  onImportState 
}) => {
  const [editingTeam, setEditingTeam] = useState<Team | null>(null);
  const [showRegisterModal, setShowRegisterModal] = useState(false);
  const [staff, setStaff] = useState<User[]>([]);
  const [showAddStaff, setShowAddStaff] = useState(false);
  const [newStaff, setNewStaff] = useState({ username: '', password: '', role: UserRole.TEAM_MANAGER, teamId: '' });

  // Collapsible state
  const [expandedSections, setExpandedSections] = useState<Record<string, boolean>>({
    branding: true,
    data: false,
    members: true,
    staff: true,
    history: true
  });

  const [settingsForm, setSettingsForm] = useState<LeagueSettings>(leagueSettings);
  const [logoPreview, setLogoPreview] = useState(leagueSettings.logo);

  const importFileRef = useRef<HTMLInputElement>(null);
  const logoInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const localUsers = JSON.parse(localStorage.getItem('lp_local_users_v2') || '[]');
    const allStaff = [
      { id: 'u-admin', username: 'admin', role: UserRole.ADMIN },
      ...localUsers
    ];
    setStaff(allStaff);
  }, []);

  const toggleSection = (section: string) => {
    setExpandedSections(prev => ({ ...prev, [section]: !prev[section] }));
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64 = reader.result as string;
        setLogoPreview(base64);
        setSettingsForm(prev => ({ ...prev, logo: base64 }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveSettings = (e: React.FormEvent) => {
    e.preventDefault();
    onUpdateLeagueSettings(settingsForm);
    alert('League configuration updated successfully!');
  };

  const handleTeamOverride = (updatedData: Omit<Team, 'id' | 'players'>) => {
    if (editingTeam && onUpdateTeam) {
      const fullUpdatedTeam: Team = {
        ...editingTeam,
        ...updatedData
      };
      onUpdateTeam(fullUpdatedTeam);
      setEditingTeam(null);
    }
  };

  const removeStaff = (userId: string) => {
    if (userId === 'u-admin') return alert("Cannot remove the primary system administrator.");
    if (confirm('Are you sure you want to revoke access for this user?')) {
      const localUsers = JSON.parse(localStorage.getItem('lp_local_users_v2') || '[]');
      const updated = localUsers.filter((u: any) => u.username !== userId && u.id !== userId);
      localStorage.setItem('lp_local_users_v2', JSON.stringify(updated));
      setStaff(prev => prev.filter(u => u.id !== userId && u.username !== userId));
    }
  };

  const addStaff = (e: React.FormEvent) => {
    e.preventDefault();
    const id = `u-${Date.now()}`;
    const newUser = { ...newStaff, id };

    const localUsers = JSON.parse(localStorage.getItem('lp_local_users_v2') || '[]');
    localUsers.push(newUser);
    localStorage.setItem('lp_local_users_v2', JSON.stringify(localUsers));

    setStaff(prev => [...prev, newUser]);
    setShowAddStaff(false);
    setNewStaff({ username: '', password: '', role: UserRole.TEAM_MANAGER, teamId: '' });
  };

  const exportLeagueData = () => {
    const backup = {
      timestamp: new Date().toISOString(),
      teams,
      matches,
      settings: leagueSettings,
      users: JSON.parse(localStorage.getItem('lp_local_users_v2') || '[]')
    };
    const blob = new Blob([JSON.stringify(backup, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `leaguepro-backup-${new Date().toISOString().slice(0, 10)}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        try {
          const data = JSON.parse(event.target?.result as string);
          if (confirm('Importing will overwrite current local league data. Continue?')) {
            onImportState(data);
          }
        } catch (err) {
          alert('Invalid backup file format.');
        }
      };
      reader.readAsText(file);
    }
  };

  const SectionHeader: React.FC<{ title: string; icon: string; sectionKey: string }> = ({ title, icon, sectionKey }) => (
    <div 
      className="flex justify-between items-center cursor-pointer group mb-4"
      onClick={() => toggleSection(sectionKey)}
    >
      <h3 className="text-xl font-black text-gray-900 flex items-center tracking-tight">
        <i className={`fas ${icon} mr-3 text-blue-600 transition-transform group-hover:scale-110`}></i>
        {title}
      </h3>
      <div className={`text-gray-300 group-hover:text-blue-500 transition-all ${expandedSections[sectionKey] ? 'rotate-180' : ''}`}>
        <i className="fas fa-chevron-down"></i>
      </div>
    </div>
  );

  return (
    <div className="space-y-6 pb-20 animate-in fade-in duration-500 max-w-5xl mx-auto">

      {/* 1. League Branding & Settings - Redesigned to be compact */}
      <div className="bg-white p-6 md:p-8 rounded-[2rem] border border-gray-100 shadow-xl overflow-hidden">
        <SectionHeader title="League Identity" icon="fa-id-card" sectionKey="branding" />

        {expandedSections.branding && (
          <form onSubmit={handleSaveSettings} className="animate-in slide-in-from-top-2 duration-300">
            <div className="flex flex-col md:flex-row gap-8 items-start">
              <div className="w-full md:w-32 flex-shrink-0">
                <div 
                  onClick={() => logoInputRef.current?.click()}
                  className="w-32 h-32 rounded-3xl bg-gray-50 border-2 border-dashed border-gray-200 flex items-center justify-center cursor-pointer hover:border-blue-400 hover:bg-blue-50 transition-all group overflow-hidden mx-auto"
                >
                  {logoPreview ? (
                    <img src={logoPreview} className="w-full h-full object-contain p-2" alt="League Logo" />
                  ) : (
                    <div className="text-center p-2">
                      <i className="fas fa-trophy text-xl text-gray-300 mb-1"></i>
                      <p className="text-[8px] font-black text-gray-400 uppercase tracking-tighter">Branding</p>
                    </div>
                  )}
                  <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                    <span className="text-white text-[9px] font-black uppercase">Upload</span>
                  </div>
                </div>
                <input type="file" ref={logoInputRef} className="hidden" accept="image/*" onChange={handleLogoUpload} />
              </div>

              <div className="flex-1 space-y-4 w-full">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest">League Name</label>
                    <input 
                      required
                      className="w-full border border-gray-100 bg-gray-50 rounded-xl px-4 py-2.5 text-sm font-bold focus:ring-2 focus:ring-blue-500 outline-none"
                      value={settingsForm.name}
                      onChange={e => setSettingsForm({...settingsForm, name: e.target.value})}
                    />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Season</label>
                    <input 
                      required
                      className="w-full border border-gray-100 bg-gray-50 rounded-xl px-4 py-2.5 text-sm font-bold focus:ring-2 focus:ring-blue-500 outline-none"
                      value={settingsForm.season}
                      onChange={e => setSettingsForm({...settingsForm, season: e.target.value})}
                    />
                  </div>
                </div>
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Welcome Message</label>
                  <textarea 
                    rows={2}
                    className="w-full border border-gray-100 bg-gray-50 rounded-xl px-4 py-2.5 text-sm font-bold focus:ring-2 focus:ring-blue-500 outline-none resize-none"
                    value={settingsForm.description}
                    onChange={e => setSettingsForm({...settingsForm, description: e.target.value})}
                  />
                </div>
                <button 
                  type="submit"
                  className="w-full bg-blue-600 text-white py-3 rounded-xl font-black uppercase text-[10px] tracking-widest shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all active:scale-[0.98]"
                >
                  Save Global Settings
                </button>
              </div>
            </div>
          </form>
        )}
      </div>

      {/* 2. Data & Persistence */}
      <div className="bg-indigo-900 rounded-[2rem] p-6 text-white shadow-2xl relative overflow-hidden transition-all">
        <div className="flex justify-between items-center cursor-pointer mb-2" onClick={() => toggleSection('data')}>
          <div className="flex items-center space-x-3">
             <i className="fas fa-database text-indigo-400"></i>
             <h3 className="text-lg font-black uppercase tracking-tight">Data Integrity</h3>
          </div>
          <div className={`text-indigo-400 transition-all ${expandedSections.data ? 'rotate-180' : ''}`}>
            <i className="fas fa-chevron-down"></i>
          </div>
        </div>

        {expandedSections.data && (
          <div className="relative z-10 space-y-4 animate-in slide-in-from-top-2 duration-300">
            <p className="text-indigo-200 text-[11px] font-medium max-w-lg leading-relaxed">
              Managing local persistence. Export your league regularly to ensure data safety across devices.
            </p>
            <div className="flex flex-wrap gap-3">
              <button 
                onClick={exportLeagueData}
                className="bg-white text-indigo-900 px-5 py-2.5 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-indigo-50 transition-all flex items-center space-x-2"
              >
                <i className="fas fa-download"></i>
                <span>Export JSON</span>
              </button>
              <button 
                onClick={() => importFileRef.current?.click()}
                className="bg-indigo-500 text-white px-5 py-2.5 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-indigo-600 transition-all flex items-center space-x-2 border border-indigo-400"
              >
                <i className="fas fa-upload"></i>
                <span>Import JSON</span>
              </button>
              <input type="file" ref={importFileRef} className="hidden" accept=".json" onChange={handleImport} />

              <button 
