                className="ml-auto bg-red-500/20 text-red-100 border border-red-500/30 px-5 py-2.5 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-red-500 transition-all"
              >
                Factory Reset
              </button>
            </div>
