import express from 'express';
import cors from 'cors';
import { createClient } from '@libsql/client';
import dotenv from 'dotenv';

dotenv.config();

const app = express();
const port = process.env.PORT || 3001;

// Fix: Cast cors() to any to bypass strict type check conflicts between Express and cors middleware signatures
app.use(cors() as any);
app.use(express.json({ limit: '10mb' }));

// Turso Client Configuration
const db = createClient({
  url: process.env.TURSO_DATABASE_URL || 'libsql://your-db-name.turso.io',
  authToken: process.env.TURSO_AUTH_TOKEN || '',
});

async function setupDb() {
  try {
    // Create tables if they don't exist
    await db.execute(`
      CREATE TABLE IF NOT EXISTS users (
        id TEXT PRIMARY KEY,
        username TEXT UNIQUE,
        password TEXT,
        role TEXT,
        teamId TEXT
      );
    `);
    await db.execute(`
      CREATE TABLE IF NOT EXISTS teams (
        id TEXT PRIMARY KEY,
        data TEXT
      );
    `);
    await db.execute(`
      CREATE TABLE IF NOT EXISTS matches (
        id TEXT PRIMARY KEY,
        data TEXT
      );
    `);
    await db.execute(`
      CREATE TABLE IF NOT EXISTS settings (
        id TEXT PRIMARY KEY,
        data TEXT
      );
    `);

    // Seed default admin if not exists
    const adminCheck = await db.execute({
      sql: 'SELECT * FROM users WHERE role = ?',
      args: ['ADMIN']
    });

    if (adminCheck.rows.length === 0) {
      await db.execute({
        sql: 'INSERT INTO users (id, username, password, role) VALUES (?, ?, ?, ?)',
        args: ['u-admin', 'admin', 'admin123', 'ADMIN']
      });
      console.log('Seeded default admin user');
    }

    console.log('Turso Database initialized successfully');
  } catch (err) {
    console.error('Failed to initialize Turso DB:', err);
  }
}

// Auth Routes
app.post('/api/auth/register', async (req, res) => {
  const { username, password, role, teamId } = req.body;
  try {
    const id = `u-${Date.now()}`;
    await db.execute({
      sql: 'INSERT INTO users (id, username, password, role, teamId) VALUES (?, ?, ?, ?, ?)',
      args: [id, username, password, role, teamId || null]
    });
    res.status(201).json({ id, username, role, teamId });
  } catch (e) {
    res.status(400).json({ error: 'Username already exists' });
  }
});

app.post('/api/auth/login', async (req, res) => {
  const { username, password } = req.body;
  try {
    const result = await db.execute({
      sql: 'SELECT * FROM users WHERE username = ? AND password = ?',
      args: [username, password]
    });
    const user = result.rows[0];
    if (user) {
      res.json({ 
        id: user.id, 
        username: user.username, 
        role: user.role, 
        teamId: user.teamId 
      });
    } else {
      res.status(401).json({ error: 'Invalid credentials' });
    }
  } catch (e) {
